{
  "name": "Life Sync Pro - Peak Performance OS",
  "description": "A high-performance personal management ecosystem featuring AI strategy, goal tracking, vitality monitoring, and digital hub integration.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Goal {
  id: string;
  text: string;
  done: boolean;
}

export interface StudyLog {
  id: string;
  category: string;
  topic: string;
  time: string;
}

export interface DayData {
  goals: Goal[];
  weekly: Goal[];
  steps: number;
  calories: number;
  deviceTime: string;
  studyLogs: StudyLog[];
}

export enum AppState {
  WELCOME = 'welcome',
  GUIDE = 'guide',
  DASHBOARD = 'dashboard'
}

export enum Tab {
  CALENDAR = 'calendar',
  PLANNING = 'planning',
  DIGITAL = 'digital',
  ANALYTICS = 'analytics'
}

import { GoogleGenAI } from "@google/genai";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
};

export const askAIArchitect = async (prompt: string, context?: any) => {
  const ai = getAIClient();
  const systemPrompt = `You are the Life Sync Pro AI Architect. 
  Your goal is to provide high-level strategic advice, productivity optimizations, and mindset shifts. 
  Keep responses concise, professional, and actionable. 
  Context: ${JSON.stringify(context || {})}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.7,
      },
    });

    return response.text || "I'm having trouble processing that request right now.";
  } catch (error) {
    console.error("AI Service Error:", error);
    return "The strategic neural link encountered an error. Please try again.";
  }
};

import React from 'react';
import { Calendar, Target, Clock, BarChart3 } from 'lucide-react';
import { Tab } from '../types';

interface NavProps {
  activeTab: Tab;
  setActiveTab: (tab: Tab) => void;
}

export const Navigation: React.FC<NavProps> = ({ activeTab, setActiveTab }) => {
  const navItems = [
    { id: Tab.CALENDAR, icon: Calendar, label: 'Daily', color: 'text-indigo-400' },
    { id: Tab.PLANNING, icon: Target, label: 'Goals', color: 'text-purple-400' },
    { id: Tab.DIGITAL, icon: Clock, label: 'Digital', color: 'text-cyan-400' },
    { id: Tab.ANALYTICS, icon: BarChart3, label: 'Log', color: 'text-emerald-400' },
  ];

  return (
    <nav className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900/90 border border-white/10 px-8 py-4 flex gap-8 md:gap-12 items-center rounded-full backdrop-blur-2xl shadow-2xl z-50">
      {navItems.map(({ id, icon: Icon, label, color }) => (
        <button
          key={id}
          onClick={() => setActiveTab(id)}
          className={`flex flex-col items-center transition-all ${
            activeTab === id ? `${color} scale-110` : 'text-slate-500 hover:text-slate-300'
          }`}
        >
          <Icon className="w-6 h-6 mb-1" />
          <span className="text-[9px] font-black uppercase tracking-widest">{label}</span>
        </button>
      ))}
    </nav>
  );
};

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  ArrowRight, 
  ChevronRight, 
  ShieldCheck, 
  Bot, 
  BookOpen, 
  X, 
  Wand2,
  Calendar as CalendarIcon,
  Plus,
  Trash2,
  CheckCircle2,
  Zap,
  Layers,
  Footprints,
  Flame,
  Smartphone,
  GraduationCap,
  Briefcase,
  UserPlus,
  Moon,
  Trophy,
  Heart
} from 'lucide-react';
import { AppState, Tab, DayData, Goal, StudyLog } from './types';
import { Navigation } from './components/Navigation';
import { askAIArchitect } from './geminiService';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [activeTab, setActiveTab] = useState<Tab>(Tab.CALENDAR);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [showAI, setShowAI] = useState(false);
  const [localData, setLocalData] = useState<Record<string, DayData>>({});

  // Sync with Local Storage for persistence (simulating Firebase for this demo)
  useEffect(() => {
    const saved = localStorage.getItem('life-sync-pro-data');
    if (saved) setLocalData(JSON.parse(saved));
  }, []);

  const updateDayData = (date: string, updates: Partial<DayData>) => {
    const newData = {
      ...localData,
      [date]: {
        ...(localData[date] || { goals: [], weekly: [], steps: 0, calories: 0, deviceTime: '', studyLogs: [] }),
        ...updates
      }
    };
    setLocalData(newData);
    localStorage.setItem('life-sync-pro-data', JSON.stringify(newData));
  };

  const currentDay = localData[selectedDate] || { 
    goals: [], weekly: [], steps: 0, calories: 0, deviceTime: '', studyLogs: [] 
  };

  // Views
  if (appState === AppState.WELCOME) {
    return (
      <div className="h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-center overflow-hidden">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_#1e1b4b_0%,_#020617_100%)] opacity-50" />
        <div className="relative z-10 space-y-8 max-w-lg animate-in fade-in zoom-in duration-1000">
          <div className="w-24 h-24 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-[32px] mx-auto flex items-center justify-center shadow-2xl shadow-indigo-500/40 transform rotate-12 transition-transform hover:rotate-0 duration-500">
            <LayoutDashboard className="w-12 h-12 text-white -rotate-12" />
          </div>
          <div className="space-y-2">
            <h1 className="text-5xl font-black tracking-tighter text-white">LIFE SYNC <span className="text-indigo-500">PRO</span></h1>
            <p className="text-indigo-400/60 font-black uppercase tracking-[0.4em] text-[10px]">Peak Performance OS</p>
          </div>
          <p className="text-slate-400 font-medium leading-relaxed">
            Personal management redefined. A unified ecosystem for your missions, health, and strategic growth.
          </p>
          <button 
            onClick={() => setAppState(AppState.GUIDE)}
            className="group flex items-center gap-3 bg-white text-slate-950 px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-sm hover:bg-indigo-50 transition-all active:scale-95 shadow-xl shadow-white/5"
          >
            Initialize System <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
          </button>
        </div>
      </div>
    );
  }

  if (appState === AppState.GUIDE) {
    return (
      <div className="h-screen bg-[#020617] overflow-y-auto p-6 md:p-12">
        <div className="max-w-4xl mx-auto space-y-12 animate-in slide-in-from-bottom-8 duration-700">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-3xl font-black text-white uppercase tracking-tight">Strategic Handbook</h2>
              <p className="text-indigo-500 font-black uppercase tracking-widest text-[10px]">Version 3.0 Gemini Integrated</p>
            </div>
            <button onClick={() => setAppState(AppState.DASHBOARD)} className="text-slate-400 hover:text-white font-black uppercase tracking-widest text-xs flex items-center gap-2">
              Skip Guide <ChevronRight className="w-4 h-4" />
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <GuideCard icon={<Bot className="text-indigo-400" />} title="AI Architect" desc="Access strategic advice powered by Gemini 3 Flash. It analyzes your data to suggest optimizations." />
            <GuideCard icon={<Zap className="text-purple-400" />} title="Mission Hierarchy" desc="Align daily actions with long-term vision using our priority-first tracking system." />
          </div>
          <div className="bg-indigo-600/10 border border-indigo-500/20 rounded-[40px] p-8 flex flex-col md:flex-row items-center justify-between gap-6">
             <div className="flex items-center gap-4">
               <ShieldCheck className="w-8 h-8 text-indigo-500" />
               <p className="text-slate-400 text-sm font-medium">System is operational and ready for deployment.</p>
             </div>
             <button onClick={() => setAppState(AppState.DASHBOARD)} className="bg-indigo-600 text-white px-10 py-4 rounded-2xl font-black uppercase tracking-widest text-sm shadow-xl hover:bg-indigo-500 transition-all">
               Enter Dashboard
             </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-100 overflow-hidden">
      <header className="p-4 bg-slate-900/80 border-b border-white/10 flex justify-between items-center backdrop-blur-xl sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center">
            <LayoutDashboard className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-lg font-black tracking-tight text-white hidden sm:block">Life Sync <span className="text-indigo-400">Pro</span></h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setAppState(AppState.GUIDE)} className="p-2 text-slate-500 hover:text-white transition-colors">
            <BookOpen className="w-5 h-5" />
          </button>
          <button onClick={() => setShowAI(true)} className="flex items-center gap-2 bg-indigo-500/10 border border-indigo-500/30 px-4 py-2 rounded-xl text-indigo-400 hover:bg-indigo-500/20 transition-all">
            <Bot className="w-5 h-5" />
            <span className="text-[10px] font-black uppercase tracking-widest hidden md:block">AI Architect</span>
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto bg-[radial-gradient(circle_at_50%_0%,_#1e1b4b_0%,_#020617_70%)] pb-32">
        <div className="max-w-5xl mx-auto p-4 md:p-8 space-y-8">
          {activeTab === Tab.CALENDAR && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-in slide-in-from-bottom-8">
              <div className="lg:col-span-4 space-y-4">
                <div className="bg-slate-900/80 p-8 rounded-[40px] border border-white/10 flex flex-col items-center">
                  <CalendarIcon className="w-10 h-10 text-indigo-500 mb-4" />
                  <input type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} className="w-full bg-slate-950 border border-white/5 rounded-2xl p-4 text-center font-black outline-none focus:ring-2 focus:ring-indigo-500" />
                </div>
                <div className="bg-slate-900/80 p-6 rounded-[40px] border border-white/10 space-y-4">
                  <VitalityInput icon={<Footprints className="text-emerald-400"/>} label="Steps" value={currentDay.steps} onChange={v => updateDayData(selectedDate, { steps: Number(v) })} />
                  <VitalityInput icon={<Flame className="text-rose-500"/>} label="Calories" value={currentDay.calories} onChange={v => updateDayData(selectedDate, { calories: Number(v) })} />
                </div>
              </div>
              <div className="lg:col-span-8 space-y-8">
                <div className="bg-slate-900/60 border border-white/10 rounded-[48px] p-8 space-y-8">
                  <GoalCategory title="Daily Missions" items={currentDay.goals} onUpdate={it => updateDayData(selectedDate, { goals: it })} accent="indigo" icon={<Zap className="w-5 h-5" />} />
                  <GoalCategory title="Weekly Milestones" items={currentDay.weekly} onUpdate={it => updateDayData(selectedDate, { weekly: it })} accent="purple" icon={<Layers className="w-5 h-5" />} />
                </div>
              </div>
            </div>
          )}

          {activeTab === Tab.DIGITAL && (
            <div className="space-y-8 animate-in slide-in-from-bottom-6">
              <div className="bg-slate-900/80 p-6 rounded-[32px] border border-white/10 flex flex-col md:flex-row gap-6 items-center">
                <div className="flex-1"><h2 className="text-2xl font-black text-cyan-400 uppercase">Digital Hub</h2></div>
                <div className="bg-cyan-500/10 border border-cyan-500/20 px-6 py-3 rounded-2xl flex items-center gap-4">
                   <Smartphone className="w-5 h-5 text-cyan-400" />
                   <input value={currentDay.deviceTime} onChange={e => updateDayData(selectedDate, { deviceTime: e.target.value })} placeholder="Screentime" className="bg-transparent border-none text-cyan-400 font-black text-lg outline-none w-28" />
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {CATEGORIES.map(cat => (
                  <CategoryCard 
                    key={cat.name} cat={cat} logs={currentDay.studyLogs.filter(l => l.category === cat.name)}
                    onAdd={(t, tm) => updateDayData(selectedDate, { studyLogs: [...currentDay.studyLogs, { id: Date.now().toString(), category: cat.name, topic: t, time: tm }] })}
                    onDelete={id => updateDayData(selectedDate, { studyLogs: currentDay.studyLogs.filter(l => l.id !== id) })}
                  />
                ))}
              </div>
            </div>
          )}

          {activeTab === Tab.PLANNING && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in">
              <StrategicCard title="Core Pillars" icon={<Trophy />} color="purple" />
              <StrategicCard title="Core Values" icon={<Heart />} color="indigo" />
            </div>
          )}

          {activeTab === Tab.ANALYTICS && (
            <div className="bg-slate-900/60 border border-white/10 rounded-[40px] p-8 animate-in slide-in-from-bottom-4">
              <h2 className="text-xl font-black uppercase mb-8 text-emerald-400">Activity Summary</h2>
              {currentDay.studyLogs.length > 0 ? (
                <div className="space-y-4">
                  {currentDay.studyLogs.map(log => (
                    <div key={log.id} className="flex justify-between border-b border-white/5 pb-4">
                      <div>
                        <p className="font-bold">{log.topic}</p>
                        <p className="text-[10px] text-slate-500 uppercase">{log.category}</p>
                      </div>
                      <span className="font-black text-emerald-400">{log.time}</span>
                    </div>
                  ))}
                </div>
              ) : <p className="text-slate-500 text-center py-12">No logs found for this cycle.</p>}
            </div>
          )}
        </div>
      </main>

      {showAI && <AIModal onClose={() => setShowAI(false)} context={currentDay} />}
      <Navigation activeTab={activeTab} setActiveTab={setActiveTab} />
    </div>
  );
};

// Helper Components
const GuideCard: React.FC<{ icon: React.ReactNode, title: string, desc: string }> = ({ icon, title, desc }) => (
  <div className="bg-slate-900/50 border border-white/5 p-8 rounded-[40px] space-y-4 hover:border-white/10 transition-all group">
    <div className="w-12 h-12 bg-slate-800 rounded-2xl flex items-center justify-center">{icon}</div>
    <h3 className="font-black text-white uppercase tracking-widest text-sm">{title}</h3>
    <p className="text-slate-400 text-sm font-medium leading-relaxed">{desc}</p>
  </div>
);

const VitalityInput: React.FC<{ icon: React.ReactNode, label: string, value: number, onChange: (v: string) => void }> = ({ icon, label, value, onChange }) => (
  <div className="bg-black/40 p-4 rounded-3xl border border-white/5 flex items-center justify-between">
    <div className="flex items-center gap-3">{icon} <span className="text-[10px] font-black uppercase text-slate-500">{label}</span></div>
    <input type="number" value={value || ''} onChange={e => onChange(e.target.value)} className="bg-transparent border-none text-right font-black text-white w-20 outline-none" />
  </div>
);

const GoalCategory: React.FC<{ title: string, items: Goal[], onUpdate: (items: Goal[]) => void, accent: 'indigo' | 'purple', icon: React.ReactNode }> = ({ title, items, onUpdate, accent, icon }) => {
  const [val, setVal] = useState('');
  const add = () => { if(val) { onUpdate([...items, { text: val, id: Date.now().toString(), done: false }]); setVal(''); } };
  const accentClass = accent === 'indigo' ? 'from-indigo-500 to-blue-600' : 'from-purple-500 to-indigo-600';
  return (
    <div className="space-y-4">
      <h3 className="text-sm font-black uppercase flex items-center gap-3">{icon} {title}</h3>
      <div className="flex gap-2">
        <input value={val} onChange={e => setVal(e.target.value)} onKeyDown={e => e.key === 'Enter' && add()} placeholder="New focus..." className="flex-1 bg-slate-800/50 border border-white/5 rounded-2xl px-6 py-3 text-sm" />
        <button onClick={add} className={`px-6 rounded-2xl bg-gradient-to-br ${accentClass} text-white hover:scale-105 active:scale-95 transition-all`}><Plus /></button>
      </div>
      <div className="grid gap-2">
        {items.map(i => (
          <div key={i.id} className="flex items-center justify-between bg-slate-950/40 p-4 rounded-2xl border border-white/5 group">
             <div className="flex items-center gap-4 cursor-pointer flex-1" onClick={() => onUpdate(items.map(x => x.id === i.id ? {...x, done: !x.done} : x))}>
                <div className={`w-5 h-5 rounded border flex items-center justify-center ${i.done ? `bg-gradient-to-br ${accentClass} border-transparent` : 'border-slate-700'}`}>
                   {i.done && <CheckCircle2 className="w-3 h-3 text-white" />}
                </div>
                <span className={`text-sm ${i.done ? 'line-through text-slate-600' : 'text-slate-200'}`}>{i.text}</span>
             </div>
             <button onClick={() => onUpdate(items.filter(x => x.id !== i.id))} className="opacity-0 group-hover:opacity-100 text-rose-500 transition-opacity"><Trash2 className="w-4 h-4" /></button>
          </div>
        ))}
      </div>
    </div>
  );
};

const CategoryCard: React.FC<{ cat: any, logs: StudyLog[], onAdd: (t: string, tm: string) => void, onDelete: (id: string) => void }> = ({ cat, logs, onAdd, onDelete }) => {
  const [topic, setTopic] = useState('');
  const [time, setTime] = useState('');
  const submit = () => { if(topic && time) { onAdd(topic, time); setTopic(''); setTime(''); } };
  return (
    <div className="bg-slate-900/60 border border-white/10 rounded-[40px] p-6 flex flex-col h-[400px]">
      <div className="flex items-center gap-3 mb-6">
        <div className={`p-3 rounded-2xl bg-gradient-to-br ${cat.color} text-white`}>{cat.icon}</div>
        <h4 className="text-sm font-black uppercase tracking-widest">{cat.name}</h4>
      </div>
      <div className="space-y-2 mb-4">
        <input value={topic} onChange={e => setTopic(e.target.value)} placeholder="Topic..." className="w-full bg-slate-950 border border-white/5 rounded-xl px-4 py-2 text-xs text-white outline-none focus:ring-1 focus:ring-white/20" />
        <div className="flex gap-2">
          <input value={time} onChange={e => setTime(e.target.value)} placeholder="Duration" className="flex-1 bg-slate-950 border border-white/5 rounded-xl px-4 py-2 text-xs text-white outline-none" />
          <button onClick={submit} className={`px-4 rounded-xl bg-gradient-to-br ${cat.color} text-white`}><Plus className="w-4 h-4" /></button>
        </div>
      </div>
      <div className="flex-1 overflow-y-auto space-y-2">
        {logs.map(l => (
          <div key={l.id} className="bg-slate-950/40 p-3 rounded-xl flex justify-between items-center group border border-white/5">
            <div>
              <p className="text-xs font-bold text-white">{l.topic}</p>
              <p className="text-[10px] text-slate-500">{l.time}</p>
            </div>
            <button onClick={() => onDelete(l.id)} className="opacity-0 group-hover:opacity-100 text-rose-500"><Trash2 className="w-3.5 h-3.5" /></button>
          </div>
        ))}
      </div>
    </div>
  );
};

const StrategicCard: React.FC<{ title: string, icon: React.ReactNode, color: 'purple' | 'indigo' }> = ({ title, icon, color }) => {
  const [items, setItems] = useState<{id: string, text: string}[]>([]);
  const [val, setVal] = useState('');
  const add = () => { if(val) { setItems([...items, { id: Date.now().toString(), text: val }]); setVal(''); } };
  const colorClass = color === 'purple' ? 'from-purple-500 to-pink-500' : 'from-indigo-500 to-blue-500';
  return (
    <div className="bg-slate-900/60 border border-white/10 rounded-[40px] p-8 space-y-6">
      <div className="flex items-center gap-4">{icon} <h3 className="text-lg font-black uppercase">{title}</h3></div>
      <div className="flex gap-2">
        <input value={val} onChange={e => setVal(e.target.value)} onKeyDown={e => e.key === 'Enter' && add()} placeholder="Define..." className="flex-1 bg-slate-950 border border-white/5 rounded-2xl px-6 py-3 text-sm" />
        <button onClick={add} className={`px-6 rounded-2xl bg-gradient-to-br ${colorClass} text-white`}><Plus /></button>
      </div>
      <div className="space-y-2">
        {items.map(i => (
          <div key={i.id} className="bg-black/40 p-4 rounded-2xl flex justify-between items-center group border border-white/5">
            <span className="text-sm font-medium">{i.text}</span>
            <button onClick={() => setItems(items.filter(x => x.id !== i.id))} className="opacity-0 group-hover:opacity-100 text-rose-500 transition-opacity"><Trash2 className="w-4 h-4" /></button>
          </div>
        ))}
      </div>
    </div>
  );
};

const AIModal: React.FC<{ onClose: () => void, context: DayData }> = ({ onClose, context }) => {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);

  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true);
    const result = await askAIArchitect(prompt, context);
    setResponse(result);
    setLoading(false);
  };

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-white/10 w-full max-w-xl rounded-[40px] overflow-hidden shadow-2xl animate-in zoom-in-95">
        <div className="p-6 bg-indigo-600 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <Bot className="text-white w-6 h-6" />
            <h2 className="font-black uppercase tracking-widest text-sm">AI Strategic Core</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X /></button>
        </div>
        <div className="p-8 space-y-6">
          <textarea 
            value={prompt} onChange={e => setPrompt(e.target.value)}
            placeholder="Ask about optimizations, health, or focus shifts..."
            className="w-full bg-slate-950 border border-white/5 rounded-2xl p-4 text-sm font-bold text-white outline-none focus:ring-2 focus:ring-indigo-500 h-32"
          />
          <button 
            onClick={handleAsk} disabled={loading}
            className="w-full py-4 bg-indigo-600 rounded-2xl font-black uppercase tracking-widest text-sm shadow-lg active:scale-[0.98] transition-all flex items-center justify-center gap-2"
          >
            {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <><Wand2 className="w-5 h-5"/> Analyze Focus</>}
          </button>
          {response && (
            <div className="bg-indigo-500/10 border border-indigo-500/20 rounded-2xl p-6 max-h-48 overflow-y-auto">
              <p className="text-sm font-medium leading-relaxed text-indigo-100 whitespace-pre-wrap">{response}</p>
