import { GoogleGenAI } from "@google/genai";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
};

export const askAIArchitectStream = async function* (prompt: string, context?: any) {
  const ai = getAIClient();
  const systemPrompt = `You are the Life Sync Pro AI Architect. 
  Your goal is to provide high-level strategic advice, productivity optimizations, and mindset shifts. 
  Keep responses concise, professional, and actionable. 
  Context: ${JSON.stringify(context || {})}`;

  try {
    const responseStream = await ai.models.generateContentStream({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.7,
      },
    });

    for await (const chunk of responseStream) {
      if (chunk.text) {
        yield chunk.text;
      }
    }
  } catch (error) {
    console.error("AI Service Error:", error);
    yield "The strategic neural link encountered an error. Please check your connectivity.";
  }
};

