const AIModal: React.FC<{ onClose: () => void, context: DayData }> = ({ onClose, context }) => {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);

  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true);
    setResponse(""); // Clear previous

    try {
      const stream = askAIArchitectStream(prompt, context);
      for await (const chunk of stream) {
        setResponse(prev => prev + chunk);
      }
    } catch (err) {
      setResponse("Fatal error in AI core. Re-initialize.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-slate-900 border border-white/10 w-full max-w-xl rounded-[40px] overflow-hidden shadow-2xl animate-in zoom-in-95" onClick={e => e.stopPropagation()}>
        <div className="p-6 bg-indigo-600 flex justify-between items-center shadow-lg">
          <div className="flex items-center gap-3">
            <Bot className="text-white w-6 h-6 animate-pulse" />
            <h2 className="font-black uppercase tracking-widest text-sm text-white">AI Strategic Core</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors text-white"><X /></button>
        </div>
        <div className="p-8 space-y-6">
          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-2">Mission Parameters</label>
            <textarea 
              value={prompt} onChange={e => setPrompt(e.target.value)}
              placeholder="E.g. How can I optimize my study hours based on my health data today?"
              className="w-full bg-slate-950 border border-white/5 rounded-2xl p-4 text-sm font-bold text-white outline-none focus:ring-2 focus:ring-indigo-500 h-32 resize-none"
            />
          </div>
          <button 
            onClick={handleAsk} disabled={loading}
            className="w-full py-4 bg-indigo-600 rounded-2xl font-black uppercase tracking-widest text-sm shadow-xl active:scale-[0.98] transition-all flex items-center justify-center gap-2 hover:bg-indigo-500 disabled:opacity-50"
          >
            {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <><Wand2 className="w-5 h-5"/> Analyze Ecosystem</>}
          </button>
          {response && (
            <div className="bg-indigo-500/10 border border-indigo-500/20 rounded-2xl p-6 max-h-[300px] overflow-y-auto custom-scroll">
              <p className="text-sm font-medium leading-relaxed text-indigo-100 whitespace-pre-wrap">{response}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

