const AIModal: React.FC<{ onClose: () => void, context: DayData }> = ({ onClose, context }) => {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);

  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true);
    setResponse("");
    try {
      const stream = askAIArchitectStream(prompt, context);
      for await (const chunk of stream) {
        setResponse(prev => prev + chunk);
      }
    } catch (err) {
      setResponse("Fatal error in neural bridge. Re-sync necessary.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/90 backdrop-blur-xl z-[100] flex items-center justify-center p-4 animate-in fade-in" onClick={onClose}>
      <div className="bg-slate-950/80 border border-white/10 w-full max-w-2xl rounded-[48px] overflow-hidden shadow-[0_0_100px_rgba(79,70,229,0.15)] animate-in zoom-in-95" onClick={e => e.stopPropagation()}>
        <div className="p-8 bg-indigo-600 flex justify-between items-center relative overflow-hidden">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_0%,_rgba(255,255,255,0.2),_transparent)]" />
          <div className="flex items-center gap-4 relative z-10">
            <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center backdrop-blur-md">
              <Bot className="text-white w-6 h-6 animate-pulse" />
            </div>
            <div>
              <h2 className="font-black uppercase tracking-[0.2em] text-[10px] text-indigo-200">System Intelligence</h2>
              <p className="text-xl font-black text-white tracking-tighter">AI Strategic Architect</p>
            </div>
          </div>
          <button onClick={onClose} className="p-3 hover:bg-white/10 rounded-2xl transition-all text-white relative z-10"><X /></button>
        </div>
        <div className="p-10 space-y-8">
          <div className="space-y-3">
            <div className="flex justify-between items-center px-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Mission Query</label>
              <button className="text-[9px] font-black uppercase text-indigo-400 flex items-center gap-1 hover:text-indigo-300 transition-colors">
                <Mic className="w-3 h-3" /> Audio Input
              </button>
            </div>
            <textarea 
              value={prompt} onChange={e => setPrompt(e.target.value)}
              placeholder="e.g. Optimize my schedule based on my step count and weekly vision..."
              className="w-full bg-slate-900 border border-white/5 rounded-[24px] p-6 text-sm font-bold text-white outline-none focus:ring-4 focus:ring-indigo-500/10 h-40 resize-none transition-all placeholder:text-slate-800"
            />
          </div>
          <button 
            onClick={handleAsk} disabled={loading}
            className="w-full py-5 bg-indigo-600 rounded-[24px] font-black uppercase tracking-[0.2em] text-sm shadow-2xl active:scale-[0.98] transition-all flex items-center justify-center gap-3 hover:bg-indigo-500 disabled:opacity-50 text-white"
          >
            {loading ? <div className="w-6 h-6 border-3 border-white/20 border-t-white rounded-full animate-spin" /> : <><Wand2 className="w-5 h-5"/> Analyze Ecosystem</>}
          </button>
          {response && (
            <div className="bg-indigo-500/5 border border-indigo-500/10 rounded-[32px] p-8 max-h-[350px] overflow-y-auto custom-scroll shadow-inner">
              <p className="text-sm font-medium leading-relaxed text-indigo-100 whitespace-pre-wrap italic selection:bg-indigo-500/40">
                {response}
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

