      <div className="w-full h-1 bg-slate-900 rounded-full overflow-hidden border border-white/5 relative">
        <div className={`h-full bg-gradient-to-r ${accentClass} transition-all duration-1000 ease-out shadow-[0_0_15px_rgba(99,102,241,0.5)]`} style={{ width: `${progress}%` }} />
