import { GoogleGenAI } from "@google/genai";

const getAIClient = () => {
  // Always use { apiKey: process.env.API_KEY } for initialization
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const askAIArchitectStream = async function* (prompt: string, context?: any) {
  const ai = getAIClient();
  const systemPrompt = `You are the "Life Sync Pro" Strategic Architect. 
  Your persona is a high-level performance coach.
  Analyze the following context: ${JSON.stringify(context || {})}

  Guidelines:
  1. Be concise, direct, and slightly futuristic in tone.
  2. Use "we" to emphasize partnership with the user.
  3. Provide actionable optimizations for productivity and vitality.
  4. If user data (steps/calories) is low, suggest a 'physiological reboot'.`;

  try {
    // Use ai.models.generateContentStream with contents and config
    // Updated model to 'gemini-3-pro-preview' as per guidelines for complex tasks
    const responseStream = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.8,
      },
    });

    for await (const chunk of responseStream) {
      // Access the .text property directly
      const text = chunk.text;
      if (text) {
        yield text;
      }
    }
  } catch (error) {
    console.error("AI Service Error:", error);
    yield "Strategic link unstable. Verify neural connection (API Key) and retry.";
  }
};

