    const current = localData[date] || { goals: [], weekly: [], steps: 0, calories: 0, deviceTime: '', studyLogs: [] };

    // Automatic Fuel Burn Calculation: approx 0.04 calories per step
    if (updates.steps !== undefined && updates.calories === undefined) {
      updates.calories = Math.round(updates.steps * 0.045);
    }

    const newData = {
      ...localData,
      [date]: {
        ...current,
        ...updates
