const MissionControl: React.FC<{ title: string, items: Goal[], onUpdate: (items: Goal[]) => void, accent: 'indigo' | 'purple', icon: React.ReactNode, progress: number }> = ({ title, items, onUpdate, accent, icon, progress }) => {
  const [val, setVal] = useState('');
  const [intent, setIntent] = useState('');
  const [priority, setPriority] = useState<'critical' | 'standard'>('standard');
  const [showAdd, setShowAdd] = useState(false);

  const add = () => { 
    if(val) { 
      onUpdate([...items, { text: val, intent: intent || 'Growth Focus', priority, id: Date.now().toString(), done: false }]); 
      setVal(''); setIntent(''); setPriority('standard'); setShowAdd(false);
    } 
  };

  const accentClass = accent === 'indigo' ? 'from-indigo-500 to-blue-600' : 'from-purple-500 to-pink-600';

  return (
    <div className="space-y-10">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-6">
          <div className={`p-4 bg-slate-950 rounded-2xl border border-white/5 text-white shadow-xl`}>{icon}</div>
          <div>
            <h3 className="text-2xl font-black uppercase tracking-tighter text-white">{title}</h3>
            <div className="flex gap-3 mt-1">
              <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-full ${accent === 'indigo' ? 'bg-indigo-500/20 text-indigo-400' : 'bg-purple-500/20 text-purple-400'}`}>{items.length} Active Missions</span>
            </div>
          </div>
        </div>
        <div className="flex flex-col items-end">
          <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Efficacy</span>
          <span className={`text-3xl font-black tracking-tighter ${accent === 'indigo' ? 'text-indigo-400' : 'text-purple-400'}`}>{progress}%</span>
        </div>
      </div>

      <div className="w-full h-2 bg-slate-950 rounded-full overflow-hidden border border-white/5 relative">
        <div className={`h-full bg-gradient-to-r ${accentClass} transition-all duration-1000 ease-out shadow-[0_0_15px_rgba(99,102,241,0.3)]`} style={{ width: `${progress}%` }} />
      </div>

      <div className="space-y-6">
        {!showAdd ? (
          <button onClick={() => setShowAdd(true)} className="w-full py-5 border border-dashed border-white/10 rounded-3xl text-[11px] font-black uppercase tracking-[0.3em] text-slate-500 hover:text-white hover:border-white/20 transition-all flex items-center justify-center gap-3 group">
            <Plus className="w-5 h-5 group-hover:rotate-90 transition-transform" /> New Mission Entry
          </button>
        ) : (
          <div className="bg-slate-950/80 p-8 rounded-[40px] border border-white/10 space-y-6 animate-in fade-in zoom-in-95 shadow-2xl">
             <div className="flex gap-4">
               <input value={val} onChange={e => setVal(e.target.value)} placeholder="Objective..." className="flex-1 bg-slate-900 border-none rounded-2xl px-6 py-4 text-sm font-bold text-white outline-none focus:ring-1 focus:ring-white/10 transition-all" />
               <button onClick={() => setPriority(p => p === 'critical' ? 'standard' : 'critical')} className={`px-5 rounded-2xl border transition-all flex items-center justify-center gap-2 ${priority === 'critical' ? 'bg-rose-500/20 border-rose-500 text-rose-500' : 'border-white/10 text-slate-500'}`}>
                 <Star className={`w-5 h-5 ${priority === 'critical' ? 'fill-current' : ''}`} />
               </button>
             </div>
             <input value={intent} onChange={e => setIntent(e.target.value)} placeholder="Mission Intent (Why?)" className="w-full bg-slate-900 border-none rounded-2xl px-6 py-4 text-xs font-bold text-indigo-300 outline-none placeholder:text-slate-700" />
             <div className="flex gap-3 pt-2">
               <button onClick={add} className={`flex-1 py-4 rounded-2xl bg-gradient-to-br ${accentClass} text-white font-black uppercase text-xs tracking-[0.2em] shadow-2xl`}>Synchronize Mission</button>
               <button onClick={() => setShowAdd(false)} className="px-8 py-4 rounded-2xl bg-slate-800 text-slate-400 font-black uppercase text-xs tracking-widest">Abort</button>
             </div>
          </div>
        )}

        <div className="grid gap-4">
          {items.map(i => (
            <div key={i.id} className={`flex items-center justify-between p-6 rounded-[32px] border transition-all duration-500 group relative overflow-hidden ${i.done ? 'bg-slate-950/20 border-white/5 opacity-40' : 'bg-slate-900/60 border-white/5 hover:border-white/10'}`}>
               {i.priority === 'critical' && !i.done && <div className="absolute left-0 top-0 bottom-0 w-1 bg-rose-500 shadow-[2px_0_10px_rgba(244,63,94,0.5)]" />}
               <div className="flex items-center gap-6 cursor-pointer flex-1 z-10" onClick={() => onUpdate(items.map(x => x.id === i.id ? {...x, done: !x.done} : x))}>
                  <div className={`w-8 h-8 rounded-xl border-2 flex items-center justify-center transition-all duration-300 ${i.done ? `bg-gradient-to-br ${accentClass} border-transparent shadow-lg scale-90` : 'border-slate-700 group-hover:border-slate-500'}`}>
                     {i.done && <CheckCircle2 className="w-5 h-5 text-white" />}
                  </div>
                  <div>
                    <div className="flex items-center gap-3">
                      <span className={`text-base font-black tracking-tight transition-all duration-500 ${i.done ? 'line-through text-slate-600' : 'text-slate-100'}`}>{i.text}</span>
                      {i.priority === 'critical' && !i.done && <span className="text-rose-500 text-[9px] font-black uppercase tracking-widest bg-rose-500/10 px-3 py-1 rounded-full">Critical Focus</span>}
                    </div>
                    {i.intent && <p className="text-[10px] font-bold text-indigo-400/60 uppercase mt-1 tracking-widest italic flex items-center gap-2">
                      <Target className="w-3 h-3" /> {i.intent}
                    </p>}
                  </div>
               </div>
               <button onClick={() => onUpdate(items.filter(x => x.id !== i.id))} className="opacity-0 group-hover:opacity-100 text-rose-500/40 hover:text-rose-500 p-3 rounded-2xl hover:bg-rose-500/10 transition-all z-10"><Trash2 className="w-5 h-5" /></button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const StrategicHierarchy: React.FC<{ title: string, icon: React.ReactNode, color: 'rose' | 'indigo', placeholder: string }> = ({ title, icon, color, placeholder }) => {
