        <div className="p-4 bg-slate-950 rounded-[24px] border border-white/5">{icon}</div>
        <h3 className="text-2xl font-black uppercase tracking-tighter text-white">{title}</h3>
      </div>
      <div className="flex gap-4">
        <input 
          value={val} onChange={e => setVal(e.target.value)} onKeyDown={e => e.key === 'Enter' && add()} 
