const AIModal: React.FC<{ onClose: () => void, context: DayData }> = ({ onClose, context }) => {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);

  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true);
    setResponse("");
    try {
      const stream = askAIArchitectStream(prompt, context);
      for await (const chunk of stream) {
        setResponse(prev => prev + chunk);
      }
    } catch (err) {
      setResponse("Fatal error in neural bridge core. Initialization required.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 animate-in fade-in" onClick={onClose}>
      <div className="bg-slate-950 border border-white/10 w-full max-w-3xl rounded-[64px] overflow-hidden shadow-[0_0_150px_rgba(79,70,229,0.15)] animate-in zoom-in-95" onClick={e => e.stopPropagation()}>
        <div className="p-10 bg-indigo-600 flex justify-between items-center relative overflow-hidden">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_0%,_rgba(255,255,255,0.2),_transparent)]" />
          <div className="flex items-center gap-6 relative z-10">
            <div className="p-4 bg-white/10 rounded-3xl backdrop-blur-md border border-white/10">
              <Bot className="text-white w-8 h-8 animate-pulse" />
            </div>
            <div>
              <h2 className="text-[11px] font-black uppercase tracking-[0.3em] text-indigo-200">System Oracle</h2>
              <p className="text-3xl font-black text-white tracking-tighter">AI Strategic Architect</p>
            </div>
          </div>
          <button onClick={onClose} className="p-4 hover:bg-white/10 rounded-3xl transition-all text-white relative z-10 border border-white/10"><X className="w-6 h-6"/></button>
        </div>
        <div className="p-12 space-y-10">
          <textarea 
            value={prompt} onChange={e => setPrompt(e.target.value)}
            placeholder="E.g. Evaluate my mission priority matrix for today..."
            className="w-full bg-slate-900 border border-white/5 rounded-[32px] p-8 text-sm font-bold text-white outline-none focus:ring-4 focus:ring-indigo-500/10 h-48 resize-none transition-all placeholder:text-slate-800"
          />
          <button 
            onClick={handleAsk} disabled={loading}
            className="w-full py-6 bg-indigo-600 rounded-[32px] font-black uppercase tracking-[0.3em] text-sm shadow-2xl transition-all flex items-center justify-center gap-4 hover:bg-indigo-500 disabled:opacity-50 text-white active:scale-95"
          >
            {loading ? <div className="w-8 h-8 border-4 border-white/20 border-t-white rounded-full animate-spin" /> : <><Wand2 className="w-6 h-6"/> Analyze Neural Ecosystem</>}
          </button>
          {response && (
            <div className="bg-indigo-500/5 border border-indigo-500/10 rounded-[40px] p-10 max-h-[350px] overflow-y-auto custom-scroll shadow-inner">
              <p className="text-sm font-medium leading-relaxed text-indigo-100 whitespace-pre-wrap italic selection:bg-indigo-500/30">
                {response}
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

