const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [activeTab, setActiveTab] = useState<Tab>(Tab.CALENDAR);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [showAI, setShowAI] = useState(false);
  const [localData, setLocalData] = useState<Record<string, DayData>>({});
  const [proactiveAdvice, setProactiveAdvice] = useState<string>("Initializing Neural Shadow...");
  const [syncLevel, setSyncLevel] = useState(0);

  useEffect(() => {
    const saved = localStorage.getItem('life-sync-pro-v4');
    if (saved) setLocalData(JSON.parse(saved));
    else setAppState(AppState.WELCOME);
  }, []);

  const updateDayData = (date: string, updates: Partial<DayData>) => {
    const current = localData[date] || { goals: [], weekly: [], steps: 0, calories: 0, deviceTime: '', studyLogs: [] };

    // Automatic Fuel Burn Calculation: approx 0.045 calories per step
    if (updates.steps !== undefined) {
      updates.calories = Math.round(updates.steps * 0.045);
    }

    const newData = {
      ...localData,
      [date]: {
        ...current,
        ...updates
      }
    };
    setLocalData(newData);
    localStorage.setItem('life-sync-pro-v4', JSON.stringify(newData));
  };

  const currentDay = useMemo(() => localData[selectedDate] || { 
    goals: [], weekly: [], steps: 0, calories: 0, deviceTime: '', studyLogs: [] 
  }, [localData, selectedDate]);

  useEffect(() => {
    const missionPoints = currentDay.goals.filter(g => g.done).length * 15;
    const weeklyPoints = currentDay.weekly.filter(g => g.done).length * 40;
    const vitalityPoints = (currentDay.steps > 5000 ? 20 : 0) + (currentDay.steps > 10000 ? 30 : 0);
    const total = Math.min(100, missionPoints + weeklyPoints + vitalityPoints);
    setSyncLevel(total);
  }, [currentDay]);

  useEffect(() => {
    if (appState === AppState.DASHBOARD) {
      const triggerShadowAnalysis = async () => {
        const shadowPrompt = `Analyze: ${currentDay.steps} steps, ${currentDay.goals.length} goals, ${currentDay.studyLogs.length} logs. Provide a proactive performance insight in one short punchy sentence. Mention if metabolic fuel is optimized.`;
        const stream = askAIArchitectStream(shadowPrompt, currentDay);
        let full = "";
        for await (const chunk of stream) {
          full += chunk;
        }
        setProactiveAdvice(full);
      };
      triggerShadowAnalysis();
    }
  }, [appState, selectedDate, currentDay.goals.length, currentDay.steps]);

  const calculateProgress = (items: Goal[]) => {
    if (items.length === 0) return 0;
    const completed = items.filter(i => i.done).length;
    return Math.round((completed / items.length) * 100);
  };

