          <div className="relative inline-block">
            <div className="absolute -inset-4 bg-indigo-500/20 blur-2xl rounded-full animate-pulse" />
            <div className="w-32 h-32 bg-gradient-to-br from-indigo-600 to-purple-700 rounded-[40px] flex items-center justify-center shadow-2xl relative">
              <BrainCircuit className="w-16 h-16 text-white" />
            </div>
          </div>
          <div className="space-y-4">
            <h1 className="text-7xl font-black tracking-tighter text-white">SYNC <span className="text-indigo-500">PRO</span></h1>
            <p className="text-slate-400 font-medium text-lg leading-relaxed">
              Elevate your existence. A proactive neural operating system for high-achievers.
            </p>
          </div>
          <button 
            onClick={() => setAppState(AppState.ONBOARDING)}
            className="group relative flex items-center gap-4 bg-white text-slate-950 px-12 py-6 rounded-2xl font-black uppercase tracking-widest text-sm hover:scale-105 transition-all shadow-2xl active:scale-95 overflow-hidden"
          >
            <span className="relative z-10">Initialize Neural Link</span>
            <div className="absolute inset-0 bg-indigo-100 translate-y-full group-hover:translate-y-0 transition-transform duration-300" />
            <ArrowRight className="w-5 h-5 relative z-10" />
          </button>
        </div>
      </div>
    );
  }

  if (appState === AppState.ONBOARDING) {
    return <Onboarding onComplete={() => setAppState(AppState.DASHBOARD)} />;
  }

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-100 overflow-hidden">
      <div className="h-1 w-full bg-slate-900 relative z-[70]">
        <div 
          className="h-full bg-gradient-to-r from-indigo-500 via-purple-500 to-cyan-500 transition-all duration-1000 shadow-[0_0_15px_rgba(99,102,241,0.8)]"
          style={{ width: `${syncLevel}%` }}
        />
      </div>

      <header className="p-4 bg-slate-900/40 border-b border-white/5 flex justify-between items-center backdrop-blur-3xl sticky top-0 z-[60]">
        <div className="flex items-center gap-4">
          <div className="relative">
            <div className={`absolute -inset-1 rounded-xl blur-sm transition-opacity duration-500 ${syncLevel > 50 ? 'bg-indigo-500 opacity-50' : 'opacity-0'}`} />
            <div className="w-10 h-10 bg-slate-950 rounded-xl flex items-center justify-center border border-white/10 relative">
              <Zap className={`w-5 h-5 ${syncLevel > 50 ? 'text-indigo-400' : 'text-slate-500'}`} />
            </div>
          </div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">Neural Sync</span>
            <span className="text-sm font-black text-white uppercase">{syncLevel}% Optimized</span>
