        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setShowAI(true)} className="flex items-center gap-2 bg-indigo-600 px-5 py-2.5 rounded-xl hover:bg-indigo-500 transition-all shadow-lg shadow-indigo-600/20 group">
            <Bot className="w-5 h-5 text-white group-hover:rotate-12 transition-transform" />
            <span className="text-[10px] font-black uppercase tracking-widest hidden md:block text-white">Ask Architect</span>
          </button>
