          <div className="relative group animate-in slide-in-from-top-4">
            <div className="absolute -inset-0.5 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-[40px] opacity-10 group-hover:opacity-25 transition-opacity blur" />
            <div className="relative bg-slate-900/60 border border-white/5 rounded-[40px] p-8 flex flex-col md:flex-row items-center gap-8 backdrop-blur-md">
