                <div className="w-16 h-16 bg-indigo-500/10 rounded-2xl flex items-center justify-center border border-indigo-500/20">
                  <Sparkles className="text-indigo-400 animate-pulse" />
                </div>
              </div>
              <div className="flex-1 text-center md:text-left">
                <h2 className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-500 mb-1">Neural Shadow Analysis</h2>
