            </div>
          </div>

          {activeTab === Tab.CALENDAR && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
              <div className="lg:col-span-4 space-y-8 animate-in slide-in-from-left-4">
                <div className="bg-slate-900/40 p-8 rounded-[40px] border border-white/5 shadow-2xl backdrop-blur-sm">
                   <div className="flex items-center gap-3 mb-6">
                     <CalendarIcon className="w-5 h-5 text-indigo-400" />
                     <h3 className="text-xs font-black uppercase tracking-widest text-slate-400">Temporal Index</h3>
                   </div>
                   <input 
                    type="date" 
