                </div>
              </div>
            </div>
          )}

          {activeTab === Tab.PLANNING && (
             <div className="grid grid-cols-1 md:grid-cols-2 gap-10 animate-in fade-in">
                <StrategicHierarchy title="Core Intentions" icon={<Target className="text-indigo-400" />} color="indigo" placeholder="Why do you do what you do?" />
                <StrategicHierarchy title="Peak Values" icon={<Heart className="text-rose-400" />} color="rose" placeholder="What governs your decisions?" />
             </div>
          )}

          {activeTab === Tab.DIGITAL && (
            <div className="space-y-12 animate-in slide-in-from-bottom-6">
               <div className="flex flex-col xl:flex-row gap-8">
                 <div className="flex-1 bg-slate-900/30 p-10 rounded-[48px] border border-white/5 flex flex-col md:flex-row justify-between items-end gap-6 backdrop-blur-md">
                   <div>
                     <h2 className="text-4xl font-black text-white tracking-tighter uppercase">Digital Hub</h2>
                     <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Activity monitoring and cognitive resource logs</p>
                   </div>
                   <div className="bg-cyan-500/5 border border-cyan-500/10 p-8 rounded-[32px] flex items-center gap-8 shadow-2xl">
                      <Smartphone className="w-10 h-10 text-cyan-400 opacity-20" />
                      <div className="flex flex-col">
                        <span className="text-[10px] font-black text-cyan-500 uppercase tracking-widest">Interface Time</span>
                        <input value={currentDay.deviceTime} onChange={e => updateDayData(selectedDate, { deviceTime: e.target.value })} placeholder="0h 0m" className="bg-transparent border-none text-cyan-400 font-black text-3xl outline-none w-32 placeholder:text-cyan-900/40" />
                      </div>
                   </div>
                 </div>

                 {/* Cognitive Energy Matrix */}
                 <div className="xl:w-[450px] bg-indigo-500/5 border border-indigo-500/10 p-10 rounded-[48px] backdrop-blur-md relative overflow-hidden group shadow-xl">
                    <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:rotate-12 transition-transform">
                      <BatteryCharging className="w-16 h-16 text-indigo-400" />
                    </div>
                    <h3 className="text-xs font-black uppercase tracking-[0.3em] text-indigo-400 mb-6 flex items-center gap-2">
                      <BrainCircuit className="w-4 h-4" /> Cognitive Matrix
                    </h3>
                    <div className="space-y-6">
                      <div className="flex items-center justify-between">
                         <span className="text-[10px] font-black uppercase text-slate-500 tracking-widest">Neural Load Level</span>
                         <span className="text-xs font-black text-indigo-400 uppercase">
                           {currentDay.studyLogs.length > 5 ? 'Intense' : 'Balanced'}
                         </span>
                      </div>
                      <div className="h-2 w-full bg-slate-950 rounded-full overflow-hidden border border-white/5 relative">
                        <div 
                          className="h-full bg-gradient-to-r from-indigo-500 to-purple-600 transition-all duration-1000 shadow-[0_0_10px_rgba(99,102,241,0.5)]" 
                          style={{ width: `${Math.min(100, (currentDay.studyLogs.length * 15))}%` }} 
                        />
                      </div>
                      <div className="grid grid-cols-2 gap-3">
                         <div className="flex flex-col items-center justify-center p-4 bg-slate-900/50 rounded-2xl border border-white/5 hover:border-indigo-500/30 transition-all gap-2 cursor-pointer group/node">
                            <Timer className="w-5 h-5 text-indigo-400 group-hover/node:scale-110 transition-transform" />
                            <span className="text-[8px] font-black uppercase tracking-widest">Deep Work</span>
                         </div>
                         <div className="flex flex-col items-center justify-center p-4 bg-slate-900/50 rounded-2xl border border-white/5 hover:border-emerald-500/30 transition-all gap-2 cursor-pointer group/node">
                            <Coffee className="w-5 h-5 text-emerald-400 group-hover/node:scale-110 transition-transform" />
                            <span className="text-[8px] font-black uppercase tracking-widest">Recharge</span>
                         </div>
                      </div>
                    </div>
                 </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {CATEGORIES.map(cat => (
                  <CategoryCard 
                    key={cat.name} cat={cat} logs={currentDay.studyLogs.filter(l => l.category === cat.name)}
                    onAdd={(t, tm, type) => updateDayData(selectedDate, { studyLogs: [...currentDay.studyLogs, { id: Date.now().toString(), category: cat.name, topic: t, time: `${tm} [${type.toUpperCase()}]` }] })}
                    onDelete={id => updateDayData(selectedDate, { studyLogs: currentDay.studyLogs.filter(l => l.id !== id) })}
                  />
                ))}
              </div>
            </div>
          )}

          {activeTab === Tab.ANALYTICS && (
            <div className="bg-slate-900/40 border border-white/5 rounded-[48px] p-12 space-y-12 animate-in zoom-in-95">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-3xl font-black uppercase text-white tracking-widest">Neural Analysis</h2>
                  <p className="text-[10px] text-slate-500 font-black uppercase mt-1">Data-driven performance insights</p>
                </div>
                <div className="p-4 bg-emerald-500/10 rounded-2xl border border-emerald-500/20">
                  <TrendingUp className="text-emerald-500 w-8 h-8" />
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                <StatCard label="Neural Diversity" value={CATEGORIES.length} unit="Types" color="text-indigo-400" />
                <StatCard label="Mission Efficacy" value={`${calculateProgress(currentDay.goals)}%`} unit="Sync" color="text-indigo-400" />
                <StatCard label="Cognitive Assets" value={currentDay.studyLogs.length} unit="Logs" color="text-purple-400" />
              </div>
              <div className="space-y-6">
                <h3 className="text-xs font-black uppercase tracking-widest text-slate-600 ml-4">Historical Activity Stream</h3>
                <div className="grid gap-4">
                  {currentDay.studyLogs.map(l => (
                    <div key={l.id} className="bg-slate-950/50 p-6 rounded-3xl border border-white/5 flex justify-between items-center hover:bg-slate-900/40 transition-all">
                      <div className="flex items-center gap-6">
                        <div className={`w-4 h-4 rounded-full ${l.time.includes('[GAIN]') ? 'bg-emerald-500/40 border-emerald-500' : 'bg-rose-500/40 border-rose-500'} border-2`} />
                        <div>
                          <p className="font-black text-white text-base tracking-tight">{l.topic}</p>
                          <p className="text-[10px] uppercase text-slate-500 font-black tracking-widest">{l.category}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <span className={`font-black ${l.time.includes('[GAIN]') ? 'text-emerald-400 bg-emerald-500/10' : 'text-rose-400 bg-rose-500/10'} px-4 py-2 rounded-xl text-xs`}>{l.time}</span>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {showAI && <AIModal onClose={() => setShowAI(false)} context={currentDay} />}
      <Navigation activeTab={activeTab} setActiveTab={setActiveTab} />
    </div>
  );
};

const Onboarding: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
