    { title: "Self Thinking Protocol", icon: <Lightbulb className="w-14 h-14 text-rose-400" />, desc: "A new dedicated space in the Digital Hub for introspective logs. Track your internal cognitive state alongside your external missions." },
    { title: "Cognitive Matrix", icon: <BrainCircuit className="w-14 h-14 text-indigo-400" />, desc: "Track mental load in the Digital Hub. Distinguish between 'Drain' (energy consuming) and 'Gain' (energy producing) activities to optimize your neural bandwidth and prevent burnout." },
    { title: "Strategic Shadowing", icon: <Bot className="w-14 h-14 text-emerald-400" />, desc: "Our AI Shadowing engine monitors your digital inputs to offer proactive course correction. If your sync levels drop, the Shadow suggests a neural reboot." }
