import { GoogleGenAI } from "@google/genai";

export const askAIArchitectStream = async function* (prompt: string, context?: any) {
  // Use the mandatory initialization pattern
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemPrompt = `You are the "Life Sync Pro" Strategic Architect. 
  Your persona is a high-level performance coach and neural optimization expert.
  Analyze the following context: ${JSON.stringify(context || {})}

  Guidelines:
  1. Be concise, direct, and futuristic.
  2. Use "we" to emphasize partnership.
  3. Focus on "Neural Load" and "Cognitive Energy" since biological tracking is now handled by the system's background protocols.
  4. Provide actionable optimizations for productivity and mental clarity.`;

  try {
    const responseStream = await ai.models.generateContentStream({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.7,
      },
    });

    for await (const chunk of responseStream) {
      const text = chunk.text;
      if (text) {
        yield text;
      }
    }
  } catch (error) {
    console.error("AI Service Error:", error);
    yield "Strategic link unstable. Verify neural connection and retry.";
  }
};

