        </div>
      </div>
      <div className="w-full h-2 bg-slate-950 rounded-full overflow-hidden border border-white/5 relative">
        <div className={`h-full bg-gradient-to-r ${accentClass} transition-all duration-1000 shadow-[0_0_15px_rgba(99,102,241,0.3)]`} style={{ width: `${progress}%` }} />
      </div>
      <div className="space-y-6">
        {!showAdd ? (
          <button onClick={() => setShowAdd(true)} className="w-full py-5 border border-dashed border-white/10 rounded-3xl text-[11px] font-black uppercase tracking-[0.3em] text-slate-500 hover:text-white transition-all flex items-center justify-center gap-3"><Plus className="w-5 h-5" /> New Entry</button>
