    setResponse("");
    try {
      const stream = askAIArchitectStream(prompt, context);
      for await (const chunk of stream) { setResponse(prev => prev + chunk); }
    } catch (err) { setResponse("Fatal error in neural bridge core."); } finally { setLoading(false); }
  };
  return (
    <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4" onClick={onClose}>
