import { GoogleGenAI } from "@google/genai";

export const askAIArchitectStream = async function* (prompt: string, context?: any) {
  // World-class senior engineer practice: direct initialization with environment variable
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemPrompt = `You are the "Life Sync Pro" Strategic Architect. 
  Your persona is a high-level performance coach and neural optimization expert for peak-performers.
  Current Context State: ${JSON.stringify(context || {})}

  Operational Directives:
  1. Be concise, direct, and futuristic.
  2. Use "we" to emphasize partnership and shared growth.
  3. Focus heavily on "Neural Load", "Cognitive Bandwidth", and "Self-Thinking" synthesis.
  4. Provide actionable, high-leverage optimizations based on the user's current logs and mission efficacy.`;

  try {
    const responseStream = await ai.models.generateContentStream({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.8,
        topP: 0.95,
      },
    });

    for await (const chunk of responseStream) {
      const text = chunk.text;
      if (text) {
        yield text;
      }
    }
  } catch (error) {
    console.error("Neural Link Failure:", error);
    yield "Strategic connection unstable. Re-initializing neural bridge...";
  }
};

