const MissionControl: React.FC<{ title: string, items: Goal[], onUpdate: (items: Goal[]) => void, accent: 'indigo' | 'purple', icon: React.ReactNode, progress: number }> = ({ title, items, onUpdate, accent, icon, progress }) => {
  const [val, setVal] = useState('');
  const [intent, setIntent] = useState('');
  const [priority, setPriority] = useState<'critical' | 'standard'>('standard');
  const [showAdd, setShowAdd] = useState(false);
  const add = () => { if(val) { onUpdate([...items, { text: val, intent: intent || 'Growth Focus', priority, id: Date.now().toString(), done: false }]); setVal(''); setIntent(''); setPriority('standard'); setShowAdd(false); } };
  const accentClass = accent === 'indigo' ? 'from-indigo-500 to-blue-600' : 'from-purple-500 to-pink-600';
  return (
    <div className="space-y-12">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-8">
          <div className="p-5 bg-slate-950 rounded-3xl border border-white/5 text-white shadow-2xl">{icon}</div>
          <div><h3 className="text-3xl font-black uppercase tracking-tighter text-white">{title}</h3></div>
        </div>
        <div className="flex flex-col items-end">
          <span className={`text-4xl font-black tracking-tighter ${accent === 'indigo' ? 'text-indigo-400' : 'text-purple-400'}`}>{progress}%</span>
          <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest mt-1">Efficacy Rate</span>
        </div>
      </div>
      <div className="w-full h-2.5 bg-slate-950 rounded-full overflow-hidden border border-white/5 relative">
        <div className={`h-full bg-gradient-to-r ${accentClass} transition-all duration-1000 shadow-[0_0_20px_rgba(99,102,241,0.4)]`} style={{ width: `${progress}%` }} />
      </div>
      <div className="space-y-8">
        {!showAdd ? (
          <button onClick={() => setShowAdd(true)} className="w-full py-6 border border-dashed border-white/10 rounded-[32px] text-xs font-black uppercase tracking-[0.4em] text-slate-500 hover:text-white hover:border-white/20 transition-all flex items-center justify-center gap-4 group">
            <Plus className="w-6 h-6 group-hover:rotate-90 transition-transform duration-500" /> NEW STRATEGIC ENTRY
          </button>
        ) : (
          <div className="bg-slate-950/80 p-10 rounded-[48px] border border-white/10 space-y-8 animate-in zoom-in-95">
             <div className="flex gap-6">
               <input value={val} onChange={e => setVal(e.target.value)} placeholder="State Objective..." className="flex-1 bg-slate-900 border-none rounded-3xl px-8 py-5 text-base font-bold text-white outline-none focus:ring-2 focus:ring-white/10" />
               <button onClick={() => setPriority(p => p === 'critical' ? 'standard' : 'critical')} className={`px-6 rounded-3xl border transition-all ${priority === 'critical' ? 'bg-rose-500/20 border-rose-500 text-rose-500' : 'border-white/10 text-slate-500'}`}><Star className={`w-6 h-6 ${priority === 'critical' ? 'fill-current' : ''}`} /></button>
             </div>
             <input value={intent} onChange={e => setIntent(e.target.value)} placeholder="Mission Intent (The 'Why')..." className="w-full bg-slate-900 border-none rounded-3xl px-8 py-5 text-sm font-bold text-indigo-300 outline-none" />
             <div className="flex gap-4">
               <button onClick={add} className={`flex-1 py-5 rounded-3xl bg-gradient-to-br ${accentClass} text-white font-black uppercase text-xs tracking-widest shadow-2xl active:scale-95 transition-all`}>Synchronize Asset</button>
               <button onClick={() => setShowAdd(false)} className="px-10 py-5 rounded-3xl bg-slate-800 text-slate-400 font-black uppercase text-xs tracking-widest">Cancel</button>
             </div>
          </div>
        )}
        <div className="grid gap-6">
          {items.map(i => (
            <div key={i.id} className={`flex items-center justify-between p-8 rounded-[40px] border transition-all group ${i.done ? 'bg-slate-950/20 opacity-40 grayscale' : 'bg-slate-900/60 border-white/5 hover:border-white/10 hover:bg-slate-900/80'}`}>
               <div className="flex items-center gap-8 cursor-pointer flex-1" onClick={() => onUpdate(items.map(x => x.id === i.id ? {...x, done: !x.done} : x))}>
                  <div className={`w-10 h-10 rounded-2xl border-2 flex items-center justify-center transition-all ${i.done ? `bg-gradient-to-br ${accentClass} border-transparent shadow-xl` : 'border-slate-700'}`}>
                    {i.done && <CheckCircle2 className="w-6 h-6 text-white" />}
                  </div>
                  <div>
                    <span className={`text-xl font-black tracking-tight ${i.done ? 'line-through text-slate-600' : 'text-slate-100'}`}>{i.text}</span>
                    {i.intent && <p className={`text-[11px] font-black uppercase mt-1 italic tracking-widest ${accent === 'indigo' ? 'text-indigo-500/60' : 'text-purple-500/60'}`}>{i.intent}</p>}
                  </div>
               </div>
               <button onClick={() => onUpdate(items.filter(x => x.id !== i.id))} className="text-rose-500/30 hover:text-rose-500 transition-all p-4"><Trash2 className="w-6 h-6" /></button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

