const calculateProgress = (items: Goal[]) => {
  if (items.length === 0) return 0;
  const completed = items.filter(item => item.done).length;
  return Math.round((completed / items.length) * 100);
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [activeTab, setActiveTab] = useState<Tab>(Tab.CALENDAR);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [showAI, setShowAI] = useState(false);
  const [localData, setLocalData] = useState<Record<string, DayData>>({});
  const [categories, setCategories] = useState<Category[]>(DEFAULT_CATEGORIES);
  const [proactiveAdvice, setProactiveAdvice] = useState<string>("Neural Bridge Initializing...");
  const [syncLevel, setSyncLevel] = useState(0);

  useEffect(() => {
    const savedData = localStorage.getItem('lsp_v6_data');
    const savedCats = localStorage.getItem('lsp_v6_cats');
    if (savedData) setLocalData(JSON.parse(savedData));
    if (savedCats) setCategories(JSON.parse(savedCats));
    if (savedData) setAppState(AppState.DASHBOARD);
  }, []);

  const saveToDisk = (data: any, cats: any) => {
    localStorage.setItem('lsp_v6_data', JSON.stringify(data));
    localStorage.setItem('lsp_v6_cats', JSON.stringify(cats));
  };

  const updateDayData = (date: string, updates: Partial<DayData>) => {
    const current = localData[date] || { goals: [], weekly: [], deviceTime: '0', studyLogs: [] };
    const newData = { ...localData, [date]: { ...current, ...updates } };
    setLocalData(newData);
    saveToDisk(newData, categories);
  };

  const currentDay = useMemo(() => localData[selectedDate] || { 
    goals: [], weekly: [], deviceTime: '0', studyLogs: [] 
  }, [localData, selectedDate]);

  const totalStudyMinutes = useMemo(() => {
    return currentDay.studyLogs.reduce((acc, log) => acc + (parseInt(log.time) || 0), 0);
  }, [currentDay.studyLogs]);

  useEffect(() => {
    const p1 = calculateProgress(currentDay.goals);
    const p2 = calculateProgress(currentDay.weekly);
    setSyncLevel(Math.round((p1 + p2) / 2) || 0);
  }, [currentDay]);

  useEffect(() => {
    if (appState === AppState.DASHBOARD) {
      const runAI = async () => {
        const prompt = `User Stats: ${currentDay.goals.length} missions, ${totalStudyMinutes} mins neural work, ${currentDay.deviceTime}h screen time. Provide 1 sharp coaching sentence.`;
        const stream = askAIArchitectStream(prompt, currentDay);
        let text = "";
        for await (const chunk of stream) {
          text += chunk;
          setProactiveAdvice(text);
        }
      };
      const timer = setTimeout(runAI, 1500);
      return () => clearTimeout(timer);
    }
  }, [appState, selectedDate, currentDay.goals.length, totalStudyMinutes]);

  const addNewCategory = () => {
    const name = prompt("Enter new segment name:");
    if (!name) return;
    const newCats = [...categories, { 
      id: Date.now().toString(), 
      name, 
      icon: 'Settings2', 
      color: 'from-slate-500 to-indigo-700' 
    }];
    setCategories(newCats);
    saveToDisk(localData, newCats);
  };

  const removeCategory = (id: string) => {
    if (confirm("Delete this segment? Data for this segment will remain in history.")) {
      const newCats = categories.filter(c => c.id !== id);
      setCategories(newCats);
      saveToDisk(localData, newCats);
    }
  };

  if (appState === AppState.WELCOME) {
    return (
      <div className="h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-center">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,_#1e1b4b_0%,_#020617_100%)] opacity-70" />
        <div className="relative z-10 space-y-12 max-w-lg w-full">
          <div className="w-32 h-32 md:w-44 md:h-44 bg-gradient-to-br from-indigo-600 to-purple-900 rounded-[48px] flex items-center justify-center shadow-2xl mx-auto border border-white/10 animate-pulse">
            <BrainCircuit className="w-16 h-16 md:w-24 md:h-24 text-white" />
          </div>
          <div className="space-y-4">
            <h1 className="text-6xl md:text-8xl font-black tracking-tighter text-white">SYNC <span className="text-indigo-500">PRO</span></h1>
            <p className="text-slate-400 font-medium text-lg md:text-xl">Next-Gen Cognitive OS • v6.0</p>
          </div>
          <button onClick={() => setAppState(AppState.ONBOARDING)} className="bg-white text-slate-950 px-12 py-6 rounded-[32px] font-black uppercase tracking-widest text-xs hover:scale-105 active:scale-95 transition-all shadow-2xl">Initialize Link</button>
        </div>
      </div>
    );
  }

  if (appState === AppState.ONBOARDING) {
    return <Onboarding onComplete={() => setAppState(AppState.DASHBOARD)} />;
  }

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-100 overflow-hidden font-['Inter']">
      <div className="h-1 w-full bg-slate-900/50 relative z-[70]">
        <div className="h-full bg-indigo-500 shadow-[0_0_15px_#6366f1]" style={{ width: `${syncLevel}%` }} />
      </div>

      <header className="px-6 py-4 md:px-8 bg-slate-950/80 border-b border-white/5 flex justify-between items-center backdrop-blur-3xl sticky top-0 z-[60]">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center border border-white/10">
            <Cpu className="w-5 h-5 text-indigo-400" />
          </div>
          <div>
            <span className="text-[10px] font-black uppercase text-slate-500 tracking-widest block">Neural State</span>
            <span className="text-xs font-black text-white">{syncLevel}% SYNCED</span>
