const AIModal: React.FC<{ onClose: () => void, context: DayData }> = ({ onClose, context }) => {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);
  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true);
    setResponse("");
    try {
      const stream = askAIArchitectStream(prompt, context);
      for await (const chunk of stream) { setResponse(prev => prev + chunk); }
    } catch (err) { setResponse("Neural Bridge Failure. Check API Key configuration."); } finally { setLoading(false); }
  };
  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[100] flex items-center justify-center md:p-6 animate-in" onClick={onClose}>
      <div className="bg-slate-950 border border-white/10 w-full h-full md:h-auto md:max-w-4xl md:rounded-[64px] overflow-hidden flex flex-col shadow-[0_0_100px_rgba(79,70,229,0.2)]" onClick={e => e.stopPropagation()}>
        <div className="p-8 md:p-12 bg-indigo-600 flex justify-between items-center relative overflow-hidden">
          <div className="absolute inset-0 bg-[linear-gradient(45deg,transparent_25%,rgba(255,255,255,0.05)_50%,transparent_75%)] bg-[length:250px_250px] animate-[pulse_5s_infinite]" />
          <div className="flex items-center gap-6 relative z-10">
            <Bot className="text-white w-10 h-10 md:w-12 md:h-12" />
            <div>
              <h2 className="text-2xl md:text-5xl font-black text-white uppercase tracking-tighter">Strategic Oracle</h2>
              <p className="text-[10px] font-black text-indigo-200 uppercase tracking-widest mt-1">Direct Neural Interface</p>
            </div>
          </div>
          <button onClick={onClose} className="p-4 hover:bg-white/10 rounded-2xl text-white transition-all relative z-10 border border-white/20"><X className="w-8 h-8"/></button>
        </div>
        <div className="flex-1 p-8 md:p-20 space-y-8 md:space-y-12 overflow-y-auto custom-scroll">
          <textarea value={prompt} onChange={e => setPrompt(e.target.value)} placeholder="Analyze my current cognitive bottlenecks..." className="w-full bg-slate-900 border border-white/5 rounded-3xl p-8 text-lg font-bold text-white h-48 md:h-64 resize-none outline-none focus:ring-4 focus:ring-indigo-500/10 placeholder:text-slate-800 transition-all" />
          <button onClick={handleAsk} disabled={loading} className="w-full py-6 md:py-8 bg-indigo-600 rounded-3xl font-black uppercase tracking-[0.4em] text-xs shadow-2xl transition-all flex items-center justify-center gap-5 hover:bg-indigo-500 text-white disabled:opacity-50">
            {loading ? <div className="w-6 h-6 border-4 border-white/20 border-t-white rounded-full animate-spin" /> : <Wand2 className="w-6 h-6"/>}
            {loading ? "Analyzing..." : "Sync Request"}
          </button>
          {response && <div className="bg-indigo-500/5 border border-indigo-500/10 rounded-3xl p-8 md:p-12 animate-in"><p className="text-lg font-medium leading-relaxed text-indigo-100 italic whitespace-pre-wrap">{response}</p></div>}
        </div>
      </div>
    </div>
  );
};

