    if (savedCats) setCategories(JSON.parse(savedCats));
    if (savedData) setAppState(AppState.DASHBOARD);
  }, []);

  const saveToDisk = (data: any, cats: any) => {
    localStorage.setItem('lsp_v6_data', JSON.stringify(data));
    localStorage.setItem('lsp_v6_cats', JSON.stringify(cats));
  };

  const updateDayData = (date: string, updates: Partial<DayData>) => {
    const current = localData[date] || { goals: [], weekly: [], deviceTime: '0', studyLogs: [] };
