}

export interface DayData {
  goals: Goal[];
  deviceTime: string;
  studyLogs: StudyLog[];
}

export enum AppState {
  WELCOME = 'welcome',
  DASHBOARD = 'dashboard'
}

export enum Tab {
  INBOX = 'inbox',
  TODAY = 'today',
  UPCOMING = 'upcoming',
