import { askAIArchitectStream } from './geminiService';

const COLORS = {
  default: 'indigo-500',
  teal: 'teal-400',
  sunshine: 'orange-400',
  peach: 'pink-400',
  lilac: 'purple-400',
  pearl: 'slate-200'
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TODAY);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [localData, setLocalData] = useState<Record<string, DayData>>({});
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [theme, setTheme] = useState<keyof typeof COLORS>('default');

  const [userProfile] = useState<UserProfile>({
    name: "Amsaimum",
    email: "amsaimum18@gmail.com",
    level: 1,
    karma: 100,
    streak: 0
  });

  useEffect(() => {
    const saved = localStorage.getItem('lsp_v7_data');
    if (saved) {
      setLocalData(JSON.parse(saved));
      setAppState(AppState.DASHBOARD);
    }
  }, []);

  const save = (data: any) => {
    localStorage.setItem('lsp_v7_data', JSON.stringify(data));
    setLocalData(data);
  };

  const currentDay = useMemo(() => localData[selectedDate] || { 
    goals: [], deviceTime: '0', studyLogs: [] 
  }, [localData, selectedDate]);

  const addTask = (text: string, date: string) => {
    const day = localData[date] || { goals: [], deviceTime: '0', studyLogs: [] };
    const newGoals = [...day.goals, { id: Date.now().toString(), text, priority: 'standard', done: false, date }];
    save({ ...localData, [date]: { ...day, goals: newGoals } });
  };

  const toggleTask = (id: string, date: string) => {
    const day = localData[date];
    const newGoals = day.goals.map(g => g.id === id ? { ...g, done: !g.done } : g);
    save({ ...localData, [date]: { ...day, goals: newGoals } });
  };

  if (appState === AppState.WELCOME) {
    return (
      <div className="h-screen bg-[#000000] flex flex-col items-center justify-center p-8 text-center">
        <div className="w-24 h-24 bg-indigo-600 rounded-3xl flex items-center justify-center shadow-2xl mb-8">
          <BrainCircuit className="w-12 h-12 text-white" />
        </div>
        <h1 className="text-4xl font-black text-white mb-2">Life Sync Pro</h1>
        <p className="text-slate-500 mb-12">Your second brain, simplified.</p>
        <button 
          onClick={() => setAppState(AppState.DASHBOARD)}
          className="bg-indigo-600 text-white w-full max-w-xs py-4 rounded-2xl font-bold transition-transform active:scale-95"
        >
          Get Started
        </button>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-[#000000] text-slate-100 overflow-hidden select-none">
      {/* Dynamic Header based on Tab */}
      <Header activeTab={activeTab} selectedDate={selectedDate} onSearch={() => {}} />

      <main className="flex-1 overflow-y-auto custom-scroll pb-24">
        {activeTab === Tab.TODAY && (
          <TodayView 
            data={currentDay} 
            onToggle={(id) => toggleTask(id, selectedDate)} 
            onDelete={(id) => {
              const newGoals = currentDay.goals.filter(g => g.id !== id);
              save({ ...localData, [selectedDate]: { ...currentDay, goals: newGoals } });
            }}
          />
        )}
        {activeTab === Tab.UPCOMING && (
          <UpcomingView 
            localData={localData} 
            onToggle={toggleTask} 
          />
        )}
        {activeTab === Tab.INBOX && <InboxView data={currentDay} />}
        {activeTab === Tab.BROWSE && (
          <BrowseView 
            profile={userProfile} 
            localData={localData} 
            theme={theme} 
            setTheme={setTheme} 
          />
        )}
      </main>

      {/* Quick Add FAB */}
      {activeTab !== Tab.BROWSE && (
        <button 
          onClick={() => setShowQuickAdd(true)}
          className="fixed right-6 bottom-28 w-14 h-14 bg-rose-500 rounded-2xl shadow-2xl flex items-center justify-center text-white active:scale-90 transition-all z-40"
        >
          <Plus className="w-8 h-8" />
        </button>
      )}

      {/* Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 bg-[#0a0a0a] border-t border-white/5 px-6 py-4 flex justify-between items-center z-50">
        <NavBtn icon={Inbox} label="Inbox" active={activeTab === Tab.INBOX} onClick={() => setActiveTab(Tab.INBOX)} />
        <NavBtn icon={CalendarDays} label="Today" active={activeTab === Tab.TODAY} onClick={() => setActiveTab(Tab.TODAY)} />
        <NavBtn icon={Layers} label="Upcoming" active={activeTab === Tab.UPCOMING} onClick={() => setActiveTab(Tab.UPCOMING)} />
        <NavBtn icon={LayoutGrid} label="Browse" active={activeTab === Tab.BROWSE} onClick={() => setActiveTab(Tab.BROWSE)} />
      </nav>

      {showQuickAdd && (
        <QuickAddModal 
          onClose={() => setShowQuickAdd(false)} 
          onAdd={(val) => {
            addTask(val, selectedDate);
            setShowQuickAdd(false);
          }} 
        />
      )}
    </div>
  );
};

