const SegmentCard: React.FC<{ cat: any, logs: StudyLog[], onAdd: (t: string, m: number) => void, onDelete: (id: string) => void }> = ({ cat, logs, onAdd, onDelete }) => {
  const [topic, setTopic] = useState('');
  const [h, setH] = useState('');
  const [m, setM] = useState('');
  const total = logs.reduce((acc, l) => acc + (parseInt(l.time) || 0), 0);

  const submit = () => {
    if (topic && (h || m)) {
      onAdd(topic, (parseInt(h) || 0) * 60 + (parseInt(m) || 0));
      setTopic(''); setH(''); setM('');
    }
  };

  return (
    <div className="bg-[#111111] p-6 rounded-[32px] border border-white/5 flex flex-col gap-6 h-[500px] shadow-lg">
      <div className="flex items-center gap-4">
        <div className={`p-3 rounded-2xl bg-gradient-to-br ${cat.color} text-white`}>{cat.icon}</div>
        <div>
          <h4 className="text-sm font-black text-white uppercase">{cat.name}</h4>
          <span className="text-[9px] font-black text-slate-500 uppercase">{formatMins(total)}</span>
        </div>
      </div>

      <div className="space-y-3">
        <textarea value={topic} onChange={e => setTopic(e.target.value)} placeholder="Session description..." className="w-full bg-black border border-white/5 rounded-xl p-4 text-xs font-bold text-white outline-none resize-none h-20" />
        <div className="flex gap-2">
          <input type="number" value={h} onChange={e => setH(e.target.value)} placeholder="H" className="w-16 bg-black border border-white/5 rounded-xl px-3 py-2 text-xs font-bold text-white" />
          <input type="number" value={m} onChange={e => setM(e.target.value)} placeholder="M" className="w-16 bg-black border border-white/5 rounded-xl px-3 py-2 text-xs font-bold text-white" />
          <button onClick={submit} className={`flex-1 rounded-xl bg-gradient-to-br ${cat.color} text-white font-black uppercase text-[10px] tracking-widest`}>Sync</button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-3 custom-scroll">
        {logs.map(log => (
