const AIModal: React.FC<{ onClose: () => void, context: DayData }> = ({ onClose, context }) => {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);
  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true); setResponse("");
    const stream = askAIArchitectStream(prompt, context);
    for await (const chunk of stream) { setResponse(prev => prev + chunk); }
    setLoading(false);
  };
  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[100] flex items-center justify-center p-0 md:p-6" onClick={onClose}>
      <div className="bg-[#050505] w-full h-full md:h-auto md:max-w-4xl md:rounded-[48px] border border-white/10 overflow-hidden flex flex-col shadow-2xl" onClick={e => e.stopPropagation()}>
        <div className="p-8 bg-indigo-600 flex justify-between items-center">
          <div className="flex items-center gap-4"><Bot className="w-10 h-10 text-white"/><h2 className="text-3xl font-black text-white tracking-tighter uppercase">Strategic Oracle</h2></div>
          <button onClick={onClose} className="p-4 bg-white/10 rounded-2xl text-white"><X className="w-8 h-8"/></button>
        </div>
        <div className="flex-1 p-8 md:p-16 space-y-10 overflow-y-auto custom-scroll">
          <textarea value={prompt} onChange={e => setPrompt(e.target.value)} placeholder="Analyze performance bottlenecks..." className="w-full bg-black border border-white/5 rounded-[32px] p-8 text-xl font-bold text-white h-64 outline-none focus:ring-2 focus:ring-indigo-500/20" />
          <button onClick={handleAsk} disabled={loading} className="w-full py-8 bg-indigo-600 rounded-[32px] font-black uppercase tracking-[0.4em] text-xs text-white shadow-2xl hover:bg-indigo-500 transition-all flex items-center justify-center gap-4">
            {loading ? <div className="w-6 h-6 border-4 border-white/20 border-t-white rounded-full animate-spin" /> : <Wand2 className="w-6 h-6" />}
            {loading ? "Calculating..." : "Sync Request"}
          </button>
          {response && <div className="p-8 bg-indigo-500/5 border border-indigo-500/10 rounded-[32px]"><p className="text-lg italic text-indigo-100 whitespace-pre-wrap">{response}</p></div>}
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Plus, Trash2, Zap, Smartphone, GraduationCap, BookOpen, Briefcase, 
  UserPlus, Moon, Trophy, Heart, Sparkles, Target, BrainCircuit, 
  Lightbulb, Activity, Cpu, Check, Settings2, Clock, Inbox, 
  CalendarDays, LayoutGrid, ChevronRight, User, Palette, Bell, 
  Layers, HelpCircle, Share2, Info, Search, MoreVertical,
  CheckCircle2, Menu, X, Wand2, Bot, LogOut, TrendingUp, Award,
  ChevronLeft
} from 'lucide-react';
import { AppState, Tab, DayData, Goal, StudyLog, UserProfile } from './types';
import { askAIArchitectStream } from './geminiService';

const CATEGORIES = [
  { id: '1', name: 'Academic', icon: <GraduationCap />, color: 'from-blue-500 to-cyan-500' },
  { id: '2', name: 'Tuition', icon: <BookOpen />, color: 'from-emerald-500 to-teal-500' },
  { id: '3', name: 'Career', icon: <Briefcase />, color: 'from-amber-500 to-orange-500' },
  { id: '4', name: 'Self Growth', icon: <UserPlus />, color: 'from-purple-500 to-pink-500' },
  { id: '5', name: 'Islamic', icon: <Moon />, color: 'from-indigo-500 to-blue-500' },
  { id: '6', name: 'Self Thinking', icon: <Lightbulb />, color: 'from-rose-500 to-orange-500' }
];

const formatMins = (totalMins: number) => {
  const h = Math.floor(totalMins / 60);
  const m = totalMins % 60;
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TODAY);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [localData, setLocalData] = useState<Record<string, DayData>>({});
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [showSidebar, setShowSidebar] = useState(false);
  const [showAI, setShowAI] = useState(false);

  const [userName, setUserName] = useState<string>("");
  const [isNewUser, setIsNewUser] = useState(true);

  // Performance Goals
  const [dailyGoalTarget, setDailyGoalTarget] = useState(5);
  const [weeklyGoalTarget, setWeeklyGoalTarget] = useState(30);
  const [karma, setKarma] = useState(100);

  useEffect(() => {
    const saved = localStorage.getItem('lsp_v7_data');
    const savedName = localStorage.getItem('lsp_user_name');
    const savedKarma = localStorage.getItem('lsp_karma');

    if (saved) setLocalData(JSON.parse(saved));
    if (savedName) {
      setUserName(savedName);
      setIsNewUser(false);
      setAppState(AppState.DASHBOARD);
    }
    if (savedKarma) setKarma(parseInt(savedKarma));
  }, []);

  const save = (data: any) => {
    localStorage.setItem('lsp_v7_data', JSON.stringify(data));
    setLocalData(data);
  };

  const saveKarma = (newKarma: number) => {
    const clampedKarma = Math.max(0, newKarma);
    localStorage.setItem('lsp_karma', clampedKarma.toString());
    setKarma(clampedKarma);
  };

  const handleOnboarding = (name: string) => {
    if (!name.trim()) return;
    localStorage.setItem('lsp_user_name', name.trim());
    setUserName(name.trim());
    setIsNewUser(false);
    setAppState(AppState.DASHBOARD);
  };

  const currentDay = useMemo(() => localData[selectedDate] || { 
    goals: [], deviceTime: '0', studyLogs: [] 
  }, [localData, selectedDate]);

  const addTask = (text: string, date: string) => {
    const day = localData[date] || { goals: [], deviceTime: '0', studyLogs: [] };
    const newGoals = [...day.goals, { id: Date.now().toString(), text, priority: 'standard', done: false, date }];
    save({ ...localData, [date]: { ...day, goals: newGoals } });
  };

  const updateDayData = (date: string, updates: Partial<DayData>) => {
    const day = localData[date] || { goals: [], deviceTime: '0', studyLogs: [] };
    save({ ...localData, [date]: { ...day, ...updates } });
  };

  if (appState === AppState.WELCOME) {
    return (
      <div className="h-screen bg-[#000000] flex flex-col items-center justify-center p-8 text-center">
        <div className="w-24 h-24 bg-indigo-600 rounded-[32px] flex items-center justify-center shadow-2xl mb-8 animate-pulse">
          <BrainCircuit className="w-12 h-12 text-white" />
        </div>
        {isNewUser ? (
          <div className="w-full max-w-xs space-y-6 animate-in">
            <h1 className="text-3xl font-black text-white">Establish Link</h1>
            <p className="text-slate-500 text-xs uppercase tracking-widest leading-relaxed">Identity recognition required for neural synchronization</p>
            <input 
              autoFocus
              className="w-full bg-[#0a0a0a] border border-white/10 p-5 rounded-2xl text-center text-white font-bold outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
              placeholder="ENTER NAME"
              onKeyDown={(e) => {
                if (e.key === 'Enter' && e.currentTarget.value) handleOnboarding(e.currentTarget.value);
              }}
            />
            <button 
              onClick={(e) => {
                const input = (e.currentTarget.previousSibling as HTMLInputElement).value;
                if (input) handleOnboarding(input);
              }}
              className="text-[10px] text-indigo-400 font-black uppercase tracking-[0.3em] mt-4 hover:text-white transition-colors"
            >
              Sync Identity
            </button>
          </div>
        ) : (
          <>
            <h1 className="text-4xl font-black text-white mb-2">LIFE SYNC PRO</h1>
            <p className="text-slate-500 mb-12 uppercase tracking-widest text-[10px]">Neural Management System v7.0</p>
            <button 
              onClick={() => setAppState(AppState.DASHBOARD)}
              className="bg-white text-black w-full max-w-xs py-5 rounded-2xl font-black uppercase text-xs tracking-widest transition-transform active:scale-95 shadow-xl"
            >
              Initialize Sync
            </button>
          </>
        )}
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-[#000000] text-slate-100 overflow-hidden font-['Inter']">
      <Header 
        activeTab={activeTab} 
        onMenu={() => setShowSidebar(true)} 
        onAI={() => setShowAI(true)}
      />

      <main className="flex-1 overflow-y-auto custom-scroll pb-28">
        {activeTab === Tab.TODAY && (
          <TodayView 
            data={currentDay} 
            onToggle={(id) => {
              const goal = currentDay.goals.find(g => g.id === id);
              const newGoals = currentDay.goals.map(g => g.id === id ? { ...g, done: !g.done } : g);
              updateDayData(selectedDate, { goals: newGoals });
              saveKarma(goal?.done ? karma - 5 : karma + 10);
            }}
            onDelete={(id) => {
              const newGoals = currentDay.goals.filter(g => g.id !== id);
              updateDayData(selectedDate, { goals: newGoals });
              saveKarma(karma - 5);
            }}
          />
        )}
        {activeTab === Tab.INBOX && <InboxView />}
        {activeTab === Tab.UPCOMING && (
          <ProductivityHub 
            userName={userName}
            karma={karma}
            localData={localData} 
            dailyGoal={dailyGoalTarget}
            weeklyGoal={weeklyGoalTarget}
            setDailyGoal={setDailyGoalTarget}
            setWeeklyGoal={setWeeklyGoalTarget}
          />
        )}
        {activeTab === Tab.BROWSE && (
          <PerformanceView 
            currentDay={currentDay} 
            totalMins={currentDay.studyLogs.reduce((acc, log) => acc + (parseInt(log.time) || 0), 0)}
            onUpdate={(updates) => updateDayData(selectedDate, updates)}
          />
        )}
      </main>

      <Sidebar 
        isOpen={showSidebar} 
        onClose={() => setShowSidebar(false)} 
        userName={userName}
        karma={karma}
        setActiveTab={setActiveTab}
      />

      {/* Quick Add FAB */}
      <button 
        onClick={() => setShowQuickAdd(true)}
        className="fixed right-6 bottom-24 w-14 h-14 bg-rose-500 rounded-2xl shadow-2xl flex items-center justify-center text-white active:scale-90 transition-all z-40"
      >
        <Plus className="w-8 h-8" />
      </button>

      {/* Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 bg-[#0a0a0a]/90 backdrop-blur-xl border-t border-white/5 px-6 py-4 flex justify-between items-center z-50">
        <NavBtn icon={Inbox} label="Inbox" active={activeTab === Tab.INBOX} onClick={() => setActiveTab(Tab.INBOX)} />
        <NavBtn icon={CalendarDays} label="Today" active={activeTab === Tab.TODAY} onClick={() => setActiveTab(Tab.TODAY)} />
        <NavBtn icon={Trophy} label="Productivity" active={activeTab === Tab.UPCOMING} onClick={() => setActiveTab(Tab.UPCOMING)} />
        <NavBtn icon={Activity} label="Performance" active={activeTab === Tab.BROWSE} onClick={() => setActiveTab(Tab.BROWSE)} />
      </nav>

      {showQuickAdd && (
        <QuickAddModal 
          onClose={() => setShowQuickAdd(false)} 
          onAdd={(val) => {
            addTask(val, selectedDate);
            setShowQuickAdd(false);
          }} 
        />
      )}

      {showAI && <AIModal onClose={() => setShowAI(false)} context={currentDay} />}
    </div>
  );
};

const Header: React.FC<{ activeTab: Tab, onMenu: () => void, onAI: () => void }> = ({ activeTab, onMenu, onAI }) => (
  <header className="px-6 pt-12 pb-4 flex justify-between items-center bg-black/50 backdrop-blur-md sticky top-0 z-30">
