const ProductivityHub: React.FC<{ 
  userName: string,
  karma: number,
  localData: Record<string, DayData>,
  dailyGoal: number,
  weeklyGoal: number,
  setDailyGoal: (n: number) => void,
  setWeeklyGoal: (n: number) => void
}> = ({ userName, karma, localData, dailyGoal, weeklyGoal, setDailyGoal, setWeeklyGoal }) => {
  const [activeSubTab, setActiveSubTab] = useState<'daily' | 'weekly' | 'karma'>('daily');

  const todayStr = new Date().toISOString().split('T')[0];
  const goalsToday = localData[todayStr]?.goals || [];
  const completedToday = goalsToday.filter(g => g.done).length;

  const weeklyData = useMemo(() => {
    return Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const ds = d.toISOString().split('T')[0];
      return (localData[ds]?.goals || []).filter(g => g.done).length;
    }).reverse();
  }, [localData]);

  const totalWeeklyCompleted = weeklyData.reduce((a, b) => a + b, 0);

  // Karma Level calculation
  const getKarmaLevel = (points: number) => {
    if (points < 200) return "Beginner";
    if (points < 500) return "Novice";
    if (points < 1000) return "Pro";
    if (points < 2500) return "Elite";
    return "Master";
  };

  return (
    <div className="px-6 space-y-8 animate-in">
      {/* Header Profile Section */}
      <div className="flex items-center gap-4 bg-[#0a0a0a] p-4 rounded-[32px] border border-white/5">
        <div className="w-16 h-16 bg-gradient-to-br from-rose-500 to-rose-700 rounded-full flex items-center justify-center text-white text-2xl font-black shadow-lg shadow-rose-500/20">
          {userName.charAt(0).toUpperCase()}
        </div>
        <div>
          <h3 className="text-lg font-black text-white leading-tight">{userName}</h3>
          <p className="text-[10px] text-rose-500 font-black uppercase tracking-widest mt-1">
            {completedToday} Missions Complete Today
          </p>
        </div>
      </div>

      {/* Segmented Controller */}
      <div className="flex bg-[#0a0a0a] p-1.5 rounded-2xl border border-white/5">
        {['daily', 'weekly', 'karma'].map(t => (
          <button 
            key={t}
            onClick={() => setActiveSubTab(t as any)}
            className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeSubTab === t ? 'bg-rose-500 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
          >
            {t}
          </button>
        ))}
      </div>

      <div className="min-h-[400px]">
        {activeSubTab === 'daily' && (
          <div className="space-y-10 animate-in">
            <div className="flex justify-between items-center bg-[#0a0a0a] p-8 rounded-[40px] border border-white/5 shadow-xl">
              <div className="space-y-2">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Temporal Goal</h4>
                <p className="text-4xl font-black text-white">{completedToday}<span className="text-slate-800 mx-1">/</span>{dailyGoal}</p>
                <button 
                  onClick={() => setDailyGoal(Math.max(1, dailyGoal + (completedToday >= dailyGoal ? 1 : -1)))} 
                  className="flex items-center gap-2 text-[10px] text-rose-500 font-black uppercase tracking-widest pt-2 hover:opacity-80 transition-opacity"
                >
                  <Settings2 className="w-3 h-3" /> Edit Goal
                </button>
              </div>
              <div className="relative w-28 h-28">
                <svg className="w-full h-full transform -rotate-90">
                  <circle cx="56" cy="56" r="48" fill="transparent" stroke="#111" strokeWidth="8" />
                  <circle 
                    cx="56" cy="56" r="48" 
                    fill="transparent" 
                    stroke="#f43f5e" 
                    strokeWidth="8" 
                    strokeDasharray={301.6} 
                    strokeDashoffset={301.6 - (301.6 * Math.min(1, completedToday / dailyGoal))} 
                    strokeLinecap="round" 
                    className="transition-all duration-1000 ease-out" 
                  />
                </svg>
                <div className="absolute inset-0 flex items-center justify-center">
                  <Award className="w-8 h-8 text-rose-500/40" />
                </div>
              </div>
            </div>

            <div className="space-y-4 px-2">
              <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">7-Day Momentum</h4>
              <div className="flex items-end gap-3 h-32 pt-8">
                {weeklyData.map((v, i) => (
                  <div key={i} className="flex-1 flex flex-col items-center gap-3 group">
                    <div className="w-full bg-slate-900/50 rounded-xl relative overflow-hidden h-full">
                      <div 
                        className="absolute bottom-0 left-0 right-0 bg-rose-500/80 transition-all duration-1000 delay-300" 
                        style={{ height: `${Math.min(100, (v / dailyGoal) * 100)}%` }} 
                      />
                    </div>
                    <span className="text-[8px] font-black text-slate-700 uppercase group-hover:text-rose-500 transition-colors">
                      {['T','W','T','F','S','S','M'][(new Date().getDay() + i + 1) % 7]}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeSubTab === 'weekly' && (
          <div className="space-y-10 animate-in">
            <div className="flex justify-between items-center bg-[#0a0a0a] p-8 rounded-[40px] border border-white/5 shadow-xl">
              <div className="space-y-2">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Weekly Threshold</h4>
                <p className="text-4xl font-black text-white">{totalWeeklyCompleted}<span className="text-slate-800 mx-1">/</span>{weeklyGoal}</p>
