              <div className="relative w-28 h-28">
                <svg className="w-full h-full transform -rotate-90">
                  <circle cx="56" cy="56" r="48" fill="transparent" stroke="#111" strokeWidth="8" />
                  <circle 
                    cx="56" cy="56" r="48" 
                    fill="transparent" 
                    stroke="#f43f5e" 
                    strokeWidth="8" 
                    strokeDasharray={301.6} 
                    strokeDashoffset={301.6 - (301.6 * Math.min(1, totalWeeklyCompleted / weeklyGoal))} 
                    strokeLinecap="round" 
                    className="transition-all duration-1000 ease-out" 
                  />
                </svg>
                <div className="absolute inset-0 flex items-center justify-center">
                  <Trophy className="w-8 h-8 text-amber-500/30" />
                </div>
              </div>
            </div>

            <div className="p-8 bg-rose-500/5 rounded-[32px] border border-rose-500/10 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <Zap className="w-8 h-8 text-rose-500" />
                <div>
                  <p className="text-xs font-black text-white uppercase">Consistency Streak</p>
                  <p className="text-2xl font-black text-rose-500 tracking-tighter">0 WEEKS</p>
                </div>
              </div>
              <ChevronRight className="w-5 h-5 text-slate-800" />
            </div>
          </div>
        )}

        {activeSubTab === 'karma' && (
          <div className="space-y-10 animate-in">
            <div className="bg-[#0a0a0a] p-8 rounded-[40px] border border-white/5 shadow-xl relative overflow-hidden">
              <div className="absolute top-0 right-0 p-8 opacity-5"><Sparkles className="w-32 h-32" /></div>
              <div className="relative z-10 flex justify-between items-center">
                <div className="space-y-1">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Neural Integrity</h4>
                  <p className="text-3xl font-black text-white">{getKarmaLevel(karma)}</p>
                  <p className="text-[10px] text-rose-500 font-black uppercase mt-1">{karma} Karma Points</p>
                </div>
                <div className="w-16 h-16 bg-slate-900 rounded-full flex items-center justify-center border border-white/5">
                  <TrendingUp className="w-6 h-6 text-rose-500" />
                </div>
              </div>
            </div>

            <div className="space-y-6 px-2">
              <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Karma Trend</h4>
              <div className="h-40 w-full relative group">
                <svg className="w-full h-full overflow-visible">
                  <defs>
                    <linearGradient id="lineGrad" x1="0%" y1="0%" x2="100%" y2="0%">
                      <stop offset="0%" stopColor="#f43f5e" stopOpacity="0.2" />
                      <stop offset="100%" stopColor="#f43f5e" stopOpacity="1" />
                    </linearGradient>
                  </defs>
                  <path 
                    d="M 0 120 Q 50 100 100 110 T 200 80 T 300 60 T 400 50" 
                    fill="none" 
                    stroke="url(#lineGrad)" 
                    strokeWidth="4" 
                    strokeLinecap="round"
                    className="animate-[dash_2s_ease-out]"
                  />
                  {[0, 1, 2, 3, 4, 5, 6].map(i => (
                    <circle 
                      key={i} 
                      cx={`${(i / 6) * 100}%`} 
                      cy={120 - (i * 12)} 
                      r="4" 
                      fill="#f43f5e" 
                      className="transition-transform hover:scale-150 cursor-pointer" 
                    />
                  ))}
                </svg>
                <div className="flex justify-between mt-6">
                  {['T','F','S','S','M','T','W'].map(d => <span key={d} className="text-[8px] font-black text-slate-700">{d}</span>)}
                </div>
              </div>
            </div>

            <div className="p-6 bg-[#0a0a0a] rounded-3xl border border-white/5 space-y-3">
              <h5 className="text-[9px] font-black text-white uppercase tracking-widest flex items-center gap-2">
                <Info className="w-3 h-3" /> System Logic
              </h5>
              <p className="text-[10px] text-slate-500 leading-relaxed font-medium">
                Karma reflects your cognitive consistency. +10 for mission completion, +5 for neural sync sessions. -5 for target deletions. 
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

