const PerformanceView: React.FC<{ currentDay: DayData, totalMins: number, onUpdate: (u: Partial<DayData>) => void }> = ({ currentDay, totalMins, onUpdate }) => {
  const deviceMins = parseInt(currentDay.deviceTime) || 0;
  const dH = Math.floor(deviceMins / 60);
  const dM = deviceMins % 60;

  const handleDeviceChange = (type: 'h' | 'm', val: string) => {
    const v = parseInt(val) || 0;
    const newTotal = type === 'h' ? v * 60 + dM : dH * 60 + v;
    onUpdate({ deviceTime: newTotal.toString() });
  };

  return (
    <div className="px-6 space-y-10 animate-in">
      <div className="bg-[#0a0a0a] p-8 rounded-[40px] border border-white/5 flex flex-col md:flex-row gap-8 justify-between items-center shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-5"><Smartphone className="w-32 h-32" /></div>
        <div className="space-y-4 relative z-10 w-full md:max-w-xs">
          <h2 className="text-3xl font-black text-white tracking-tighter uppercase">Digital Hub</h2>
          <div className="flex gap-4">
            <div className="flex-1 bg-black p-4 rounded-2xl border border-white/5">
              <span className="text-[8px] font-black text-slate-600 uppercase block mb-1">Hours</span>
              <input type="number" value={dH} onChange={e => handleDeviceChange('h', e.target.value)} className="w-full bg-transparent border-none text-2xl font-black text-white outline-none" />
            </div>
            <div className="flex-1 bg-black p-4 rounded-2xl border border-white/5">
              <span className="text-[8px] font-black text-slate-600 uppercase block mb-1">Mins</span>
              <input type="number" value={dM} onChange={e => handleDeviceChange('m', e.target.value)} className="w-full bg-transparent border-none text-2xl font-black text-white outline-none" />
            </div>
          </div>
        </div>
        <div className="w-full md:w-auto text-center md:text-right">
          <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Neural Load</p>
          <p className="text-4xl font-black text-white">{formatMins(totalMins)}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {CATEGORIES.map(cat => (
          <SegmentCard 
            key={cat.id} 
            cat={cat} 
            logs={currentDay.studyLogs.filter(l => l.category === cat.name)} 
            onAdd={(t, m) => onUpdate({ studyLogs: [...currentDay.studyLogs, { id: Date.now().toString(), category: cat.name, topic: t, time: m.toString() }] })} 
            onDelete={id => onUpdate({ studyLogs: currentDay.studyLogs.filter(l => l.id !== id) })}
          />
        ))}
      </div>
    </div>
  );
};

const SegmentCard: React.FC<{ cat: any, logs: StudyLog[], onAdd: (t: string, m: number) => void, onDelete: (id: string) => void }> = ({ cat, logs, onAdd, onDelete }) => {
  const [topic, setTopic] = useState('');
  const [h, setH] = useState('');
  const [m, setM] = useState('');
  const total = logs.reduce((acc, l) => acc + (parseInt(l.time) || 0), 0);

  const submit = () => {
    if (topic && (h || m)) {
      onAdd(topic, (parseInt(h) || 0) * 60 + (parseInt(m) || 0));
      setTopic(''); setH(''); setM('');
    }
  };

  return (
    <div className="bg-[#0a0a0a] p-6 rounded-[32px] border border-white/5 flex flex-col gap-6 h-[500px] shadow-lg transition-all hover:border-white/10">
      <div className="flex items-center gap-4">
        <div className={`p-3 rounded-2xl bg-gradient-to-br ${cat.color} text-white shadow-lg`}>{cat.icon}</div>
        <div>
          <h4 className="text-sm font-black text-white uppercase">{cat.name}</h4>
          <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">{formatMins(total)} Sync</span>
        </div>
      </div>

      <div className="space-y-3">
        <textarea value={topic} onChange={e => setTopic(e.target.value)} placeholder="Neural target description..." className="w-full bg-black border border-white/5 rounded-2xl p-4 text-xs font-bold text-white outline-none resize-none h-20 placeholder:text-slate-800 focus:border-indigo-500 transition-colors" />
        <div className="flex gap-2">
          <input type="number" value={h} onChange={e => setH(e.target.value)} placeholder="H" className="w-16 bg-black border border-white/5 rounded-xl px-3 py-2 text-xs font-bold text-white outline-none" />
          <input type="number" value={m} onChange={e => setM(e.target.value)} placeholder="M" className="w-16 bg-black border border-white/5 rounded-xl px-3 py-2 text-xs font-bold text-white outline-none" />
          <button onClick={submit} className={`flex-1 rounded-xl bg-gradient-to-br ${cat.color} text-white font-black uppercase text-[10px] tracking-widest active:scale-95 transition-transform`}>Synchronize</button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-3 custom-scroll">
        {logs.map(log => (
          <div key={log.id} className="p-4 bg-black/40 rounded-2xl border border-white/5 flex justify-between items-start group/item hover:bg-black transition-colors">
            <div className="flex-1">
              <p className="text-xs font-bold text-slate-200">{log.topic}</p>
              <span className="text-[8px] font-black text-slate-600 uppercase mt-1 block tracking-widest">{formatMins(parseInt(log.time))} Duration</span>
            </div>
            <button onClick={() => onDelete(log.id)} className="opacity-0 group-hover/item:opacity-100 text-rose-500/30 hover:text-rose-500 transition-all ml-2"><Trash2 className="w-4 h-4" /></button>
          </div>
        ))}
      </div>
    </div>
  );
};

