          onChange={e => setVal(e.target.value)} 
          placeholder="What's the next objective?" 
          className="w-full bg-transparent border-none text-2xl font-black text-white outline-none placeholder:text-slate-900" 
          onKeyDown={e => e.key === 'Enter' && val && onAdd(val)} 
        />
        <div className="flex justify-between items-center pt-6 border-t border-white/5">
          <div className="flex gap-6 text-slate-800">
            <CalendarDays className="w-5 h-5 cursor-pointer hover:text-indigo-400 transition-colors"/>
            <Bell className="w-5 h-5 cursor-pointer hover:text-indigo-400 transition-colors"/>
            <Target className="w-5 h-5 cursor-pointer hover:text-indigo-400 transition-colors"/>
          </div>
          <button 
            onClick={() => val && onAdd(val)} 
            className="bg-indigo-600 text-white px-10 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest disabled:opacity-20 shadow-lg shadow-indigo-600/20 active:scale-95 transition-all" 
            disabled={!val}
          >
            Deploy mission
          </button>
        </div>
      </div>
    </div>
  );
};

const AIModal: React.FC<{ onClose: () => void, context: DayData }> = ({ onClose, context }) => {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);
  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true); setResponse("");
    const stream = askAIArchitectStream(prompt, context);
    for await (const chunk of stream) { setResponse(prev => prev + chunk); }
    setLoading(false);
  };
  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[100] flex items-center justify-center p-0 md:p-6" onClick={onClose}>
      <div className="bg-[#050505] w-full h-full md:h-auto md:max-w-4xl md:rounded-[48px] border border-white/10 overflow-hidden flex flex-col shadow-2xl animate-in" onClick={e => e.stopPropagation()}>
        <div className="p-8 bg-indigo-600 flex justify-between items-center">
          <div className="flex items-center gap-4">
            <Bot className="w-10 h-10 text-white"/>
            <div>
              <h2 className="text-3xl font-black text-white tracking-tighter uppercase">Strategic Oracle</h2>
              <p className="text-[10px] text-indigo-200 font-bold uppercase tracking-widest">Neuro-Logical Strategy Unit</p>
            </div>
          </div>
          <button onClick={onClose} className="p-4 bg-white/10 rounded-2xl text-white hover:bg-white/20 transition-all"><X className="w-6 h-6"/></button>
        </div>
        <div className="flex-1 p-8 md:p-12 space-y-10 overflow-y-auto custom-scroll">
          <div className="space-y-4">
            <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-4">Consultation Request</h4>
            <textarea 
              value={prompt} 
              onChange={e => setPrompt(e.target.value)} 
              placeholder="Analyze current performance bottleneck and suggest ROI optimization..." 
              className="w-full bg-black border border-white/5 rounded-[32px] p-8 text-xl font-bold text-white h-56 outline-none focus:ring-2 focus:ring-indigo-500/20 placeholder:text-slate-900 transition-all" 
            />
          </div>
          <button 
            onClick={handleAsk} 
            disabled={loading} 
            className="w-full py-8 bg-indigo-600 rounded-[32px] font-black uppercase tracking-[0.4em] text-xs text-white shadow-2xl hover:bg-indigo-500 active:scale-[0.98] transition-all flex items-center justify-center gap-4 disabled:opacity-50"
          >
            {loading ? <div className="w-6 h-6 border-4 border-white/20 border-t-white rounded-full animate-spin" /> : <Wand2 className="w-6 h-6" />}
            {loading ? "Establishing Bridge..." : "Submit Sync Request"}
          </button>
          {response && (
            <div className="p-10 bg-indigo-500/5 border border-indigo-500/10 rounded-[32px] animate-in">
               <div className="flex items-center gap-3 mb-4">
                  <Sparkles className="w-4 h-4 text-indigo-400" />
                  <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Architect response</span>
               </div>
               <p className="text-lg italic text-indigo-100 whitespace-pre-wrap leading-relaxed">{response}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default App;

