              <Zap className="w-5 h-5 text-rose-500" />
              <p className="text-[8px] text-slate-400 font-black uppercase tracking-wider leading-relaxed">System prediction: You are on track for a 15% efficiency increase this week.</p>
            </div>
          </div>
        )}

        {activeSubTab === 'karma' && (
          <div className="space-y-6 animate-in">
            <div className="bg-[#0a0a0a] p-6 rounded-3xl border border-white/5 flex justify-between items-center relative overflow-hidden">
              <div className="relative z-10">
                <h4 className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Neural Standing</h4>
