              <div className="bg-[#0a0a0a] p-4 rounded-2xl border border-white/5">
                <p className="text-[7px] font-black text-slate-600 uppercase mb-1">ROI Focus</p>
                <p className="text-xs font-black text-white">+12pts</p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
