const PerformanceView: React.FC<{ currentDay: DayData, totalMins: number, onUpdate: (u: Partial<DayData>) => void }> = ({ currentDay, totalMins, onUpdate }) => {
  const deviceMins = parseInt(currentDay.deviceTime) || 0;
  const dH = Math.floor(deviceMins / 60);
  const dM = deviceMins % 60;

  const handleDeviceChange = (type: 'h' | 'm', val: string) => {
    const v = Math.min(type === 'h' ? 24 : 59, parseInt(val) || 0);
    const newTotal = type === 'h' ? v * 60 + dM : dH * 60 + v;
    onUpdate({ deviceTime: newTotal.toString() });
  };

  return (
    <div className="px-6 space-y-8 animate-in">
      {/* EMERALD THEME FOR PERFORMANCE */}
      <div className="bg-emerald-500/10 p-6 rounded-3xl border border-emerald-500/20 shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 -mr-4 -mt-4 opacity-5"><Activity className="w-24 h-24" /></div>
        <div className="flex justify-between items-start mb-6 relative z-10">
          <div className="space-y-1">
            <h2 className="text-lg font-black text-white uppercase tracking-tight">Focus Matrix</h2>
            <p className="text-[8px] text-emerald-400 font-black uppercase tracking-widest">Total Deep Sync: {formatMins(totalMins)}</p>
          </div>
          <Cpu className="w-5 h-5 text-emerald-500/40" />
        </div>
        <div className="flex gap-3 relative z-10">
          <div className="flex-1 bg-black/60 p-3 rounded-xl border border-white/5 focus-within:border-emerald-500/50 transition-all">
            <span className="text-[7px] font-black text-slate-600 uppercase block mb-1">HOURS</span>
            <input type="number" value={dH} onChange={e => handleDeviceChange('h', e.target.value)} className="w-full bg-transparent border-none text-xl font-black text-white outline-none" />
          </div>
          <div className="flex-1 bg-black/60 p-3 rounded-xl border border-white/5 focus-within:border-emerald-500/50 transition-all">
            <span className="text-[7px] font-black text-slate-600 uppercase block mb-1">MINS</span>
            <input type="number" value={dM} onChange={e => handleDeviceChange('m', e.target.value)} className="w-full bg-transparent border-none text-xl font-black text-white outline-none" />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {CATEGORIES.map(cat => (
          <div key={cat.id} className="bg-[#0a0a0a] p-5 rounded-3xl border border-white/5 flex flex-col gap-4 transition-all hover:border-white/10 active:scale-[0.99]">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-xl bg-gradient-to-br ${cat.color} text-white shadow-md`}>{cat.icon}</div>
                <h4 className="text-[10px] font-black text-white uppercase tracking-widest">{cat.name}</h4>
              </div>
              <span className={`text-[8px] font-black uppercase ${cat.color.split(' ')[0].replace('from-', 'text-')}`}>{formatMins(currentDay.studyLogs.filter(l => l.category === cat.name).reduce((a, b) => a + (parseInt(b.time) || 0), 0))}</span>
            </div>
            <SegmentMiniForm onAdd={(t, m) => onUpdate({ studyLogs: [...currentDay.studyLogs, { id: Date.now().toString(), category: cat.name, topic: t, time: m.toString() }] })} color={cat.color} />
            <div className="space-y-2 max-h-32 overflow-y-auto custom-scroll pr-1">
              {currentDay.studyLogs.filter(l => l.category === cat.name).map(log => (
                <div key={log.id} className="flex justify-between items-center p-2.5 bg-white/5 rounded-xl border border-white/5 text-[9px] hover:bg-white/10 transition-colors">
                  <span className="font-bold text-slate-300 truncate max-w-[140px]">{log.topic}</span>
                  <div className="flex items-center gap-2">
                    <span className="font-black text-slate-600 uppercase">{formatMins(parseInt(log.time))}</span>
                    <button onClick={() => onUpdate({ studyLogs: currentDay.studyLogs.filter(l => l.id !== log.id) })} className="text-rose-500/30 hover:text-rose-500"><Trash2 className="w-3 h-3"/></button>
