        </div>
        <div className="p-6 space-y-6 overflow-y-auto custom-scroll max-h-[70vh]">
          <textarea 
            value={prompt} 
            onChange={e => setPrompt(e.target.value)} 
            placeholder="Query the architect..." 
            className="w-full bg-black border border-white/5 rounded-2xl p-4 text-sm font-bold text-white h-40 outline-none focus:border-indigo-500 transition-all placeholder:text-slate-800" 
          />
          <button 
            onClick={handleAsk} 
            disabled={loading} 
