          >
            {loading && <div className="w-3 h-3 border-2 border-white/20 border-t-white rounded-full animate-spin" />}
            {loading ? "BRIDGING..." : "SUBMIT REQUEST"}
          </button>
          {response && (
            <div className="p-4 bg-indigo-500/5 border border-indigo-500/10 rounded-2xl animate-in">
              <div className="flex items-center gap-2 mb-2">
                 <Sparkles className="w-3 h-3 text-indigo-400" />
                 <span className="text-[7px] font-black text-indigo-400 uppercase tracking-widest">Architect Response</span>
              </div>
              <p className="text-sm italic text-indigo-100 whitespace-pre-wrap leading-relaxed">{response}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

