const AIModal: React.FC<{ onClose: () => void, context: DayData }> = ({ onClose, context }) => {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);
  const handleAsk = async () => {
    if (!prompt) return;
    setLoading(true); setResponse("");
    const stream = askAIArchitectStream(prompt, context);
    for await (const chunk of stream) { setResponse(prev => prev + chunk); }
    setLoading(false);
  };
  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-[#050505] w-full max-w-md rounded-[40px] border border-white/10 overflow-hidden flex flex-col shadow-2xl animate-in" onClick={e => e.stopPropagation()}>
        <div className="p-6 bg-indigo-600 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <Bot className="w-8 h-8 text-white"/>
            <div>
              <h2 className="text-xl font-black text-white tracking-tighter uppercase leading-none">Oracle</h2>
              <p className="text-[7px] text-indigo-300 font-bold uppercase tracking-widest mt-1">v3.1 Strategic Core</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 text-white/50 hover:text-white"><X className="w-5 h-5"/></button>
        </div>
        <div className="p-6 space-y-6 overflow-y-auto custom-scroll max-h-[70vh]">
          <textarea 
            value={prompt} 
            onChange={e => setPrompt(e.target.value)} 
            placeholder="Consult the strategic architect..." 
            className="w-full bg-black border border-white/5 rounded-2xl p-4 text-sm font-bold text-white h-40 outline-none focus:border-indigo-500 transition-all placeholder:text-slate-800" 
          />
          <button 
            onClick={handleAsk} 
            disabled={loading} 
            className="w-full py-4 bg-indigo-600 rounded-2xl font-black uppercase tracking-[0.25em] text-[10px] text-white disabled:opacity-50 shadow-lg shadow-indigo-600/30 flex items-center justify-center gap-3"
          >
            {loading && <div className="w-3 h-3 border-2 border-white/20 border-t-white rounded-full animate-spin" />}
            {loading ? "BRIDGING..." : "SUBMIT REQUEST"}
          </button>
          {response && (
            <div className="p-4 bg-indigo-500/5 border border-indigo-500/10 rounded-2xl animate-in">
              <div className="flex items-center gap-2 mb-2">
                 <Sparkles className="w-3 h-3 text-indigo-400" />
                 <span className="text-[7px] font-black text-indigo-400 uppercase tracking-widest">Architect response</span>
              </div>
              <p className="text-sm italic text-indigo-100 whitespace-pre-wrap leading-relaxed">{response}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

