  GraduationCap: <GraduationCap />,
  BookOpen: <BookOpen />,
  Briefcase: <Briefcase />,
  UserPlus: <UserPlus />,
  Moon: <Moon />,
  Lightbulb: <Lightbulb />,
  Target: <Target />,
  Activity: <Activity />,
  Cpu: <Cpu />,
  Heart: <Heart />,
  Zap: <Zap />
};

const COLOR_OPTIONS = [
  'from-blue-500 to-cyan-500',
  'from-emerald-500 to-teal-500',
  'from-amber-500 to-orange-500',
  'from-purple-500 to-pink-500',
