  Sun, CloudRain, Snowflake, Monitor
} from 'lucide-react';
import { AppState, Tab, DayData, Goal, StudyLog, UserProfile } from './types';
import { askAIArchitectStream } from './geminiService';

// --- THEME ENGINE CONFIG ---
const THEMES: Record<string, any> = {
  Night: { bg: '#000000', card: '#0a0a0a', accent: '#6366f1', text: '#f8fafc' },
  Forest: { bg: '#051205', card: '#0a1a0a', accent: '#22c55e', text: '#ecfdf5' },
  Sky: { bg: '#f0f9ff', card: '#ffffff', accent: '#0ea5e9', text: '#0c4a6e' },
  Sea: { bg: '#021013', card: '#051c22', accent: '#06b6d4', text: '#ecfeff' },
  Sunset: { bg: '#1a0d0d', card: '#2d1616', accent: '#f97316', text: '#fff7ed' },
  Sunrise: { bg: '#1e1b2e', card: '#2a2542', accent: '#f472b6', text: '#fdf2f8' },
  Rainy: { bg: '#0f172a', card: '#1e293b', accent: '#94a3b8', text: '#f1f5f9' },
  Winter: { bg: '#f8fafc', card: '#ffffff', accent: '#38bdf8', text: '#1e293b' }
};

// --- TYPES & DEFAULTS ---
const DEFAULT_CATEGORIES = [
  { id: '1', name: 'Academic', icon: 'GraduationCap', color: 'from-blue-500 to-cyan-500' },
  { id: '2', name: 'Tuition', icon: 'BookOpen', color: 'from-emerald-500 to-teal-500' },
  { id: '3', name: 'Career', icon: 'Briefcase', color: 'from-amber-500 to-orange-500' }
];

const ICON_MAP: Record<string, any> = {
  GraduationCap: <GraduationCap />, BookOpen: <BookOpen />, Briefcase: <Briefcase />,
  UserPlus: <UserPlus />, Moon: <Moon />, Lightbulb: <Lightbulb />,
  Target: <Target />, Activity: <Activity />, Cpu: <Cpu />, Heart: <Heart />, Zap: <Zap />
};

const COLOR_OPTIONS = [
  'from-blue-500 to-cyan-500', 'from-emerald-500 to-teal-500', 'from-amber-500 to-orange-500',
  'from-purple-500 to-pink-500', 'from-indigo-500 to-blue-500', 'from-rose-500 to-orange-500'
];

// --- MAIN COMPONENT ---
const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TODAY);
  const [sidebarView, setSidebarView] = useState<string | null>(null);
  const [theme, setTheme] = useState('Night');
  const [localData, setLocalData] = useState<Record<string, DayData>>({});
  const [categories, setCategories] = useState(DEFAULT_CATEGORIES);
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [showSidebar, setShowSidebar] = useState(false);
  const [showAI, setShowAI] = useState(false);
  const [userName, setUserName] = useState("");
  const [karma, setKarma] = useState(100);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('lsp_v7_data');
    const savedName = localStorage.getItem('lsp_user_name');
    const savedTheme = localStorage.getItem('lsp_theme');
    const savedCats = localStorage.getItem('lsp_categories');

    if (saved) setLocalData(JSON.parse(saved));
    if (savedCats) setCategories(JSON.parse(savedCats));
    if (savedName) { setUserName(savedName); setAppState(AppState.DASHBOARD); }
    if (savedTheme) { setTheme(savedTheme); applyTheme(savedTheme); }
  }, []);

  const applyTheme = (name: string) => {
    const t = THEMES[name];
    const root = document.documentElement;
    root.style.setProperty('--app-bg', t.bg);
    root.style.setProperty('--card-bg', t.card);
    root.style.setProperty('--accent-primary', t.accent);
    root.style.setProperty('--text-main', t.text);
    root.style.setProperty('--border-color', name === 'Sky' || name === 'Winter' ? 'rgba(0,0,0,0.05)' : 'rgba(255,255,255,0.05)');
    localStorage.setItem('lsp_theme', name);
    setTheme(name);
  };

  const updateDayData = (date: string, updates: Partial<DayData>) => {
    const day = localData[date] || { goals: [], deviceTime: '0', studyLogs: [] };
    const newData = { ...localData, [date]: { ...day, ...updates } };
    localStorage.setItem('lsp_v7_data', JSON.stringify(newData));
    setLocalData(newData);
  };

  const currentDay = localData[new Date().toISOString().split('T')[0]] || { goals: [], deviceTime: '0', studyLogs: [] };

  if (appState === AppState.WELCOME) {
    return (
      <div className="h-screen flex flex-col items-center justify-center p-8 text-center bg-black">
        <BrainCircuit className="w-16 h-16 text-indigo-500 mb-8 animate-pulse" />
        <h1 className="text-2xl font-black text-white tracking-tighter mb-4">NEURAL SYNC REQUIRED</h1>
        <input 
          autoFocus 
          className="bg-zinc-900 border border-white/5 p-4 rounded-2xl text-center text-white font-bold outline-none focus:ring-2 focus:ring-indigo-500" 
          placeholder="ENTER IDENTITY"
          onKeyDown={e => { if(e.key === 'Enter' && e.currentTarget.value) { setUserName(e.currentTarget.value); localStorage.setItem('lsp_user_name', e.currentTarget.value); setAppState(AppState.DASHBOARD); }}}
        />
      </div>
    );
  }

  return (
    <div className="flex h-screen overflow-hidden font-['Inter']">
      <Sidebar 
        isOpen={showSidebar} 
        onClose={() => setShowSidebar(false)} 
        onSelectView={setSidebarView} 
        onThemeChange={applyTheme}
        activeTheme={theme}
      />

      <div className="flex-1 flex flex-col relative overflow-hidden">
        <Header activeTab={activeTab} onMenu={() => setShowSidebar(true)} onAI={() => setShowAI(true)} />

        <main className="flex-1 overflow-y-auto custom-scroll pb-32">
          {sidebarView ? (
            <div className="px-6 py-4 animate-in">
              <button onClick={() => setSidebarView(null)} className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-500 mb-6 hover:text-white">
                <ChevronLeft size={14}/> Return to Sync
              </button>
              <SidebarView view={sidebarView} />
            </div>
          ) : (
            <>
              {activeTab === Tab.TODAY && (
                <TodayView 
                  data={currentDay.goals} 
                  onToggle={id => {
                    const newGoals = currentDay.goals.map(g => g.id === id ? { ...g, done: !g.done } : g);
                    updateDayData(new Date().toISOString().split('T')[0], { goals: newGoals });
                  }}
                  onDelete={id => {
                    const newGoals = currentDay.goals.filter(g => g.id !== id);
                    updateDayData(new Date().toISOString().split('T')[0], { goals: newGoals });
                  }}
                />
              )}
              {activeTab === Tab.UPCOMING && (
                <ProductivityHub userName={userName} karma={karma} localData={localData} />
              )}
              {activeTab === Tab.BROWSE && (
                <PerformanceView 
                  currentDay={currentDay} 
                  categories={categories}
                  onUpdate={updates => updateDayData(new Date().toISOString().split('T')[0], updates)}
                />
              )}
            </>
          )}
        </main>

        <button onClick={() => setShowQuickAdd(true)} className="fixed right-6 bottom-28 w-14 h-14 bg-indigo-600 rounded-full shadow-2xl flex items-center justify-center text-white z-40 active:scale-95 transition-all">
          <Plus size={28} />
        </button>

        <nav className="fixed bottom-0 left-0 right-0 bg-black/80 backdrop-blur-xl border-t border-white/5 px-8 pt-4 pb-8 flex justify-between items-center z-50">
          <NavBtn icon={CalendarDays} label="Today" active={activeTab === Tab.TODAY && !sidebarView} onClick={() => {setActiveTab(Tab.TODAY); setSidebarView(null);}} color="text-indigo-500" />
          <NavBtn icon={Trophy} label="Focus" active={activeTab === Tab.UPCOMING && !sidebarView} onClick={() => {setActiveTab(Tab.UPCOMING); setSidebarView(null);}} color="text-rose-500" />
          <NavBtn icon={Activity} label="Pulse" active={activeTab === Tab.BROWSE && !sidebarView} onClick={() => {setActiveTab(Tab.BROWSE); setSidebarView(null);}} color="text-emerald-500" />
        </nav>
      </div>

      {showQuickAdd && <QuickAddModal onClose={() => setShowQuickAdd(false)} onAdd={val => {
        const date = new Date().toISOString().split('T')[0];
        const day = localData[date] || { goals: [], deviceTime: '0', studyLogs: [] };
        updateDayData(date, { goals: [...day.goals, { id: Date.now().toString(), text: val, priority: 'standard', done: false, date }] });
        setShowQuickAdd(false);
      }} />}
      {showAI && <AIModal onClose={() => setShowAI(false)} context={currentDay} />}
    </div>
  );
};

