const PomodoroModule = () => {
  const [mode, setMode] = useState<'pomo' | 'stop'>('pomo');
  const [time, setTime] = useState(25 * 60);
  const [active, setActive] = useState(false);
  const timerRef = useRef<any>(null);

  useEffect(() => {
    if (active) {
      timerRef.current = setInterval(() => setTime(t => Math.max(0, mode === 'pomo' ? t - 1 : t + 1)), 1000);
    } else {
      clearInterval(timerRef.current);
    }
    return () => clearInterval(timerRef.current);
  }, [active, mode]);

  const fmt = (s: number) => `${Math.floor(s / 60)}:${(s % 60).toString().padStart(2, '0')}`;

  return (
    <div className="bg-zinc-950 p-8 rounded-[40px] border border-white/5 text-center space-y-8">
      <div className="flex bg-black p-1 rounded-2xl border border-white/5 mx-auto w-fit">
        <button onClick={() => {setMode('pomo'); setTime(25*60); setActive(false);}} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'pomo' ? 'bg-indigo-600 text-white' : 'text-slate-600'}`}>Pomodoro</button>
        <button onClick={() => {setMode('stop'); setTime(0); setActive(false);}} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'stop' ? 'bg-indigo-600 text-white' : 'text-slate-600'}`}>Stopwatch</button>
      </div>
      <div className="text-7xl font-black text-white tracking-tighter">{fmt(time)}</div>
      <div className="flex gap-4 justify-center">
        <button onClick={() => setActive(!active)} className={`w-20 h-20 rounded-full flex items-center justify-center transition-all ${active ? 'bg-rose-500 shadow-lg shadow-rose-500/20' : 'bg-indigo-600 shadow-lg shadow-indigo-600/20'}`}>
          {active ? <X size={32} className="text-white"/> : <Zap size={32} className="text-white"/>}
        </button>
        <button onClick={() => {setActive(false); setTime(mode === 'pomo' ? 25*60 : 0);}} className="w-20 h-20 rounded-full bg-white/5 border border-white/5 flex items-center justify-center text-slate-500 hover:text-white">
          <Clock size={32}/>
        </button>
      </div>
    </div>
  );
};

