const OverlayRouter: React.FC<{ view: string }> = ({ view }) => {
  switch (view) {
    case 'matrix': return <EisenhowerMatrix />;
    case 'pomodoro': return <PomodoroModule />;
    case 'habits': return <HabitTracker />;
    case 'notes': return <NoteSystem />;
    case 'countdown': return <CountdownProtocol />;
    default: return null;
  }
};

const EisenhowerMatrix = () => {
  const [items, setItems] = useState<Record<string, string[]>>(() => {
    const saved = localStorage.getItem('lsp_matrix');
    return saved ? JSON.parse(saved) : { do: [], plan: [], delegate: [], drop: [] };
  });

  useEffect(() => {
    localStorage.setItem('lsp_matrix', JSON.stringify(items));
  }, [items]);

  const addItem = (quadrant: string) => {
    const task = prompt(`Strategic input for ${quadrant.toUpperCase()} quadrant:`);
    if (task) {
      setItems(prev => ({ ...prev, [quadrant]: [...prev[quadrant], task] }));
    }
  };

  const removeTask = (quadrant: string, index: number) => {
    setItems(prev => ({
      ...prev,
      [quadrant]: prev[quadrant].filter((_, i) => i !== index)
    }));
  };

  return (
    <div className="space-y-6">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-[var(--accent-primary)]/20">
        <div className="flex items-center gap-3 mb-3">
          <BrainCircuit className="text-[var(--accent-primary)]" size={20} />
          <h2 className="text-sm font-black uppercase tracking-widest text-white">Neural Briefing: The Matrix</h2>
        </div>
        <p className="text-[11px] text-[var(--text-dim)] leading-relaxed font-medium">
          The Eisenhower Matrix optimizes your <span className="text-white font-bold">Cognitive ROI</span> by categorizing tasks by <span className="text-rose-500">Urgency</span> and <span className="text-emerald-500">Importance</span>. 
          Focus your peak energy on <span className="text-white underline italic">Do Now</span> tasks. Use <span className="text-white underline italic">Plan</span> for long-term growth. 
          Delegate what drains you, and eliminate what distracts you.
        </p>
      </div>

      <div className="grid grid-cols-2 gap-3 h-[450px]">
        <MatrixBox 
          title="DO NOW" 
          desc="Urgent & Important" 
          color="border-rose-500/30 bg-rose-500/5" 
          items={items.do} 
          icon={Zap}
          onAdd={() => addItem('do')} 
          onRemove={(i) => removeTask('do', i)} 
        />
        <MatrixBox 
          title="PLAN" 
          desc="Important, Not Urgent" 
          color="border-indigo-500/30 bg-indigo-500/5" 
          items={items.plan} 
          icon={Clock}
          onAdd={() => addItem('plan')} 
          onRemove={(i) => removeTask('plan', i)} 
        />
        <MatrixBox 
          title="DELEGATE" 
          desc="Urgent, Not Important" 
          color="border-amber-500/30 bg-amber-500/5" 
          items={items.delegate} 
          icon={Users}
          onAdd={() => addItem('delegate')} 
          onRemove={(i) => removeTask('delegate', i)} 
        />
        <MatrixBox 
          title="ELIMINATE" 
          desc="Neither" 
          color="border-slate-800 bg-slate-900/40" 
          items={items.drop} 
          icon={Trash2}
          onAdd={() => addItem('drop')} 
          onRemove={(i) => removeTask('drop', i)} 
        />
      </div>
    </div>
  );
};

const MatrixBox: React.FC<{ 
  title: string, 
  desc: string, 
  color: string, 
  items: string[], 
  icon: any,
  onAdd: () => void, 
  onRemove: (i: number) => void 
}> = ({ title, desc, color, items, icon: Icon, onAdd, onRemove }) => (
  <div className={`p-5 rounded-[32px] border ${color} flex flex-col group/box relative`}>
    <div className="flex justify-between items-center mb-1">
      <div className="flex items-center gap-2">
        <Icon size={12} className="text-inherit opacity-70" />
        <span className="text-[10px] font-black text-white">{title}</span>
      </div>
      <button onClick={onAdd} className="p-1.5 bg-white/5 hover:bg-white/20 rounded-xl transition-all active:scale-90">
        <Plus size={14} className="text-white" />
      </button>
    </div>
    <span className="text-[7px] font-bold text-slate-500 uppercase tracking-widest mb-4">{desc}</span>
    <div className="flex-1 bg-black/20 rounded-2xl border border-white/5 p-2 overflow-y-auto custom-scroll">
      {items.length === 0 ? (
        <div className="h-full flex flex-col items-center justify-center opacity-10 space-y-2">
          <Target size={24} />
          <span className="text-[8px] font-black uppercase">Clear</span>
