      ) : (
        items.map((item, idx) => (
          <div key={idx} className="flex justify-between items-start text-[9px] mb-2 bg-white/5 p-2.5 rounded-xl border border-white/5 group transition-all hover:bg-white/10">
            <span className="flex-1 leading-snug pr-2 text-slate-200">{item}</span>
            <button onClick={() => onRemove(idx)} className="text-slate-500 hover:text-rose-500 transition-colors p-0.5">
              <X size={10}/>
            </button>
          </div>
        ))
      )}
