        items.map((item, idx) => (
          <div key={idx} className="flex justify-between items-start text-[9px] bg-white/5 p-2 rounded-lg border border-white/5 group transition-all hover:bg-white/10 animate-in">
            <span className="flex-1 leading-tight pr-2 text-slate-200 font-medium break-words">{item}</span>
            <button onClick={() => onRemove(idx)} className="text-slate-600 hover:text-rose-500 transition-colors p-0.5 mt-0.5">
