const EisenhowerMatrix = () => {
  const [items, setItems] = useState<Record<string, string[]>>(() => {
    const saved = localStorage.getItem('lsp_matrix');
    return saved ? JSON.parse(saved) : { do: [], plan: [], delegate: [], drop: [] };
  });

  useEffect(() => {
    localStorage.setItem('lsp_matrix', JSON.stringify(items));
  }, [items]);

  const addItem = (quadrant: string) => {
    const task = prompt(`Define strategic topic for ${quadrant.toUpperCase()} quadrant:`);
    if (task && task.trim()) {
      setItems(prev => ({ 
        ...prev, 
        [quadrant]: [...prev[quadrant], task.trim()] 
      }));
    }
  };

  const removeTask = (quadrant: string, index: number) => {
    setItems(prev => {
      const newQuadrant = [...prev[quadrant]];
      newQuadrant.splice(index, 1);
      return { ...prev, [quadrant]: newQuadrant };
    });
  };

  return (
    <div className="space-y-6">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-[var(--accent-primary)]/20 animate-in">
        <div className="flex items-center gap-3 mb-3">
          <BrainCircuit className="text-[var(--accent-primary)]" size={20} />
          <h2 className="text-sm font-black uppercase tracking-widest text-white">Neural Briefing: The Matrix</h2>
        </div>
        <p className="text-[11px] text-[var(--text-dim)] leading-relaxed font-medium">
          Categorize by <span className="text-rose-500">Urgency</span> and <span className="text-emerald-500">Importance</span>. 
          Focus on <span className="text-white font-bold italic">Do Now</span>. Use <span className="text-white font-bold italic">Plan</span> for growth. 
          Delegate what drains you, and eliminate what distracts you.
        </p>
      </div>

      <div className="grid grid-cols-2 gap-3 h-[450px]">
        <MatrixBox 
          title="DO NOW" 
          desc="Urgent & Important" 
          color="border-rose-500/30 bg-rose-500/5 text-rose-500" 
          items={items.do} 
          icon={Zap}
          onAdd={() => addItem('do')} 
          onRemove={(i) => removeTask('do', i)} 
        />
        <MatrixBox 
          title="PLAN" 
          desc="Important, Not Urgent" 
          color="border-emerald-500/30 bg-emerald-500/5 text-emerald-500" 
          items={items.plan} 
          icon={Clock}
          onAdd={() => addItem('plan')} 
          onRemove={(i) => removeTask('plan', i)} 
        />
        <MatrixBox 
          title="DELEGATE" 
          desc="Urgent, Not Important" 
          color="border-amber-500/30 bg-amber-500/5 text-amber-500" 
          items={items.delegate} 
          icon={Users}
          onAdd={() => addItem('delegate')} 
          onRemove={(i) => removeTask('delegate', i)} 
        />
        <MatrixBox 
          title="ELIMINATE" 
          desc="Neither" 
          color="border-slate-800 bg-slate-900/40 text-slate-500" 
          items={items.drop} 
          icon={Trash2}
          onAdd={() => addItem('drop')} 
          onRemove={(i) => removeTask('drop', i)} 
        />
      </div>
    </div>
  );
};

