const EisenhowerMatrix = () => {
  const [items, setItems] = useState<Record<string, string[]>>(() => {
    const saved = localStorage.getItem('lsp_matrix_v2');
    return saved ? JSON.parse(saved) : { do: [], plan: [], delegate: [], drop: [] };
  });

  useEffect(() => {
    localStorage.setItem('lsp_matrix_v2', JSON.stringify(items));
  }, [items]);

  // FIXED LOGIC: Ensures topic addition is robust and triggers re-render
  const handleAddItem = (quadrant: string) => {
    const topic = window.prompt(`Strategic Topic for ${quadrant.toUpperCase()} quadrant:`);
    if (topic && topic.trim().length > 0) {
      setItems(prev => {
        const newQuadrantItems = [...(prev[quadrant] || []), topic.trim()];
        return {
          ...prev,
          [quadrant]: newQuadrantItems
        };
      });
    }
  };

  const handleRemoveTask = (quadrant: string, index: number) => {
    setItems(prev => {
      const newQuadrantItems = [...(prev[quadrant] || [])];
      newQuadrantItems.splice(index, 1);
      return {
        ...prev,
        [quadrant]: newQuadrantItems
      };
    });
  };

  return (
    <div className="space-y-6">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-[var(--accent-primary)]/20 animate-in shadow-xl">
        <div className="flex items-center gap-3 mb-3">
          <BrainCircuit className="text-[var(--accent-primary)] animate-pulse" size={20} />
          <h2 className="text-sm font-black uppercase tracking-widest text-white">Neural Briefing: The Matrix</h2>
        </div>
        <p className="text-[11px] text-[var(--text-dim)] leading-relaxed font-medium">
          The Eisenhower Matrix is a productivity framework that categorizes tasks by <span className="text-rose-500 font-bold">Urgency</span> and <span className="text-emerald-500 font-bold">Importance</span>. 
          It improves goals by filtering noise from signal. Use <span className="text-white italic">Do Now</span> for immediate ROI, <span className="text-white italic">Plan</span> for long-term growth, <span className="text-white italic">Delegate</span> to save energy, and <span className="text-white italic">Eliminate</span> to reclaim focus.
        </p>
      </div>

      <div className="grid grid-cols-2 gap-3 h-[450px]">
        <MatrixBox 
          title="DO NOW" 
          desc="Urgent & Important" 
          color="border-rose-500/30 bg-rose-500/5 text-rose-500" 
          items={items.do} 
          icon={Zap}
          onAdd={() => handleAddItem('do')} 
          onRemove={(i) => handleRemoveTask('do', i)} 
        />
        <MatrixBox 
          title="PLAN" 
          desc="Important, Not Urgent" 
          color="border-emerald-500/30 bg-emerald-500/5 text-emerald-500" 
          items={items.plan} 
          icon={CalendarDays}
          onAdd={() => handleAddItem('plan')} 
          onRemove={(i) => handleRemoveTask('plan', i)} 
        />
        <MatrixBox 
          title="DELEGATE" 
          desc="Urgent, Not Important" 
          color="border-amber-500/30 bg-amber-500/5 text-amber-500" 
          items={items.delegate} 
          icon={UserPlus}
          onAdd={() => handleAddItem('delegate')} 
          onRemove={(i) => handleRemoveTask('delegate', i)} 
        />
        <MatrixBox 
          title="ELIMINATE" 
          desc="Neither" 
          color="border-slate-800 bg-slate-900/40 text-slate-500" 
          items={items.drop} 
          icon={Trash2}
          onAdd={() => handleAddItem('drop')} 
          onRemove={(i) => handleRemoveTask('drop', i)} 
        />
      </div>
    </div>
  );
};

