const EisenhowerMatrix = () => {
  const [items, setItems] = useState<Record<string, string[]>>(() => {
    const saved = localStorage.getItem('lsp_matrix_v3');
    try {
      return saved ? JSON.parse(saved) : { do: [], plan: [], delegate: [], drop: [] };
    } catch (e) {
      return { do: [], plan: [], delegate: [], drop: [] };
    }
  });

  useEffect(() => {
    localStorage.setItem('lsp_matrix_v3', JSON.stringify(items));
  }, [items]);

  // Robust addition logic: Ensure we create a new reference for the object and the nested array
  const handleAddItem = (quadrant: string) => {
    const topic = window.prompt(`New objective for ${quadrant.toUpperCase()}:`);
    if (topic && topic.trim()) {
      setItems(prev => ({
        ...prev,
        [quadrant]: [...(prev[quadrant] || []), topic.trim()]
      }));
    }
  };

  const handleRemoveTask = (quadrant: string, index: number) => {
    setItems(prev => {
      const updatedList = [...(prev[quadrant] || [])];
      updatedList.splice(index, 1);
      return {
        ...prev,
        [quadrant]: updatedList
      };
    });
  };

  return (
    <div className="space-y-6">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-[var(--accent-primary)]/20 animate-in">
        <div className="flex items-center gap-3 mb-3">
          <BrainCircuit className="text-[var(--accent-primary)]" size={20} />
          <h2 className="text-sm font-black uppercase tracking-widest text-white">Strategic OS</h2>
        </div>
        <p className="text-[11px] text-[var(--text-dim)] leading-relaxed font-medium">
          Filter your cognitive noise. Categorize objectives by <span className="text-rose-500 font-bold">Urgency</span> and <span className="text-emerald-500 font-bold">Importance</span>. 
          Tap the <Plus size={10} className="inline mx-1"/> to add items.
        </p>
      </div>

      <div className="grid grid-cols-2 gap-3 h-[450px]">
        <MatrixBox 
          title="DO" 
          desc="Immediate ROI" 
          color="border-rose-500/30 bg-rose-500/5 text-rose-500" 
          items={items.do} 
          icon={Zap}
          onAdd={() => handleAddItem('do')} 
          onRemove={(i) => handleRemoveTask('do', i)} 
        />
        <MatrixBox 
          title="PLAN" 
          desc="Strategic Growth" 
          color="border-emerald-500/30 bg-emerald-500/5 text-emerald-500" 
          items={items.plan} 
          icon={CalendarDays}
          onAdd={() => handleAddItem('plan')} 
          onRemove={(i) => handleRemoveTask('plan', i)} 
        />
        <MatrixBox 
          title="DELEGATE" 
          desc="Resource Shift" 
          color="border-amber-500/30 bg-amber-500/5 text-amber-500" 
          items={items.delegate} 
          icon={UserPlus}
          onAdd={() => handleAddItem('delegate')} 
          onRemove={(i) => handleRemoveTask('delegate', i)} 
        />
        <MatrixBox 
          title="ELIMINATE" 
          desc="Cognitive Leak" 
          color="border-slate-800 bg-slate-900/40 text-slate-500" 
          items={items.drop} 
          icon={Trash2}
          onAdd={() => handleAddItem('drop')} 
          onRemove={(i) => handleRemoveTask('drop', i)} 
        />
      </div>
    </div>
  );
};

