const PomodoroModule = () => {
  const [mode, setMode] = useState<'pomo' | 'stop'>('pomo');
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);

  useEffect(() => {
    let interval: any;
    if (isActive) {
      interval = setInterval(() => {
        setTimeLeft(t => mode === 'pomo' ? Math.max(0, t - 1) : t + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isActive, mode]);

  const fmt = (s: number) => `${Math.floor(s / 60)}:${(s % 60).toString().padStart(2, '0')}`;

  return (
    <div className="bg-[var(--card-bg)] p-10 rounded-[40px] border border-[var(--border-color)] text-center space-y-10">
      <div className="flex bg-black/40 p-1.5 rounded-2xl border border-white/5 mx-auto w-fit">
        <button onClick={() => {setMode('pomo'); setTimeLeft(25*60); setIsActive(false);}} className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'pomo' ? 'bg-[var(--accent-primary)] text-white shadow-lg' : 'text-slate-500'}`}>Pomodoro</button>
        <button onClick={() => {setMode('stop'); setTimeLeft(0); setIsActive(false);}} className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'stop' ? 'bg-[var(--accent-primary)] text-white shadow-lg' : 'text-slate-500'}`}>Stopwatch</button>
      </div>
      <div className="text-8xl font-black tracking-tighter text-white tabular-nums">{fmt(timeLeft)}</div>
      <div className="flex gap-4 justify-center">
        <button onClick={() => setIsActive(!isActive)} className={`w-20 h-20 rounded-full flex items-center justify-center transition-all ${isActive ? 'bg-rose-500 shadow-xl shadow-rose-500/20' : 'bg-[var(--accent-primary)] shadow-xl shadow-indigo-500/20'}`}>
          {isActive ? <X size={32} className="text-white"/> : <Zap size={32} className="text-white"/>}
        </button>
        <button onClick={() => {setIsActive(false); setTimeLeft(mode === 'pomo' ? 25*60 : 0);}} className="w-20 h-20 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-slate-500 hover:text-white">
          <Clock size={32}/>
        </button>
      </div>
    </div>
  );
};

const HabitTracker = () => {
  const [habits, setHabits] = useState<{name: string, streaks: boolean[]}[]>(() => {
    const saved = localStorage.getItem('lsp_habits');
    return saved ? JSON.parse(saved) : [
      { name: 'Meditation', streaks: [true, true, true, true, false, false, false] },
      { name: 'Deep Work', streaks: [true, true, true, false, false, false, false] },
      { name: 'Hydration', streaks: [true, true, true, true, true, false, false] },
      { name: 'Reading', streaks: [true, true, false, false, false, false, false] }
    ];
  });

  const toggleDay = (habitIdx: number, dayIdx: number) => {
    const next = [...habits];
    next[habitIdx].streaks[dayIdx] = !next[habitIdx].streaks[dayIdx];
    setHabits(next);
    localStorage.setItem('lsp_habits', JSON.stringify(next));
  };

  const addHabit = () => {
    const name = window.prompt("New Habit Name?");
    if (name) {
      setHabits(prev => [...prev, { name, streaks: Array(7).fill(false) }]);
    }
  };

  return (
    <div className="space-y-4">
      {habits.map((h, hIdx) => (
        <div key={h.name} className="bg-[var(--card-bg)] p-5 rounded-3xl border border-[var(--border-color)] flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-500"><Flame size={20}/></div>
            <span className="font-bold text-white text-sm">{h.name}</span>
          </div>
          <div className="flex gap-2">
            {h.streaks.map((s, dIdx) => (
              <button 
                key={dIdx} 
                onClick={() => toggleDay(hIdx, dIdx)}
                className={`w-6 h-6 rounded-lg border transition-colors ${s ? 'bg-emerald-500 border-emerald-500 shadow-sm' : 'border-white/5 bg-black/20'}`} 
              />
            ))}
          </div>
        </div>
      ))}
      <button onClick={addHabit} className="w-full p-4 border border-dashed border-white/10 rounded-2xl text-[9px] uppercase font-black tracking-widest text-slate-600 hover:text-emerald-500 transition-colors">Append Habit Loop</button>
    </div>
  );
};

const NoteSystem = () => {
  const [notes, setNotes] = useState<{id: string, title: string, content: string}[]>(() => {
    const saved = localStorage.getItem('lsp_notes');
    return saved ? JSON.parse(saved) : [
      { id: '1', title: 'Protocol Delta', content: 'Focus strictly on energy management during peak hours 08:00 - 11:00.' }
    ];
  });

  const addNote = () => {
    const title = window.prompt("Trace Subject?");
    const content = window.prompt("Trace Content?");
    if (title || content) {
      const newNote = { id: Date.now().toString(), title: title || "Untitled", content: content || "..." };
      const updated = [...notes, newNote];
      setNotes(updated);
      localStorage.setItem('lsp_notes', JSON.stringify(updated));
    }
  };

  const deleteNote = (id: string) => {
    const updated = notes.filter(n => n.id !== id);
    setNotes(updated);
    localStorage.setItem('lsp_notes', JSON.stringify(updated));
  };

  return (
    <div className="space-y-4">
