const ProductivityHub: React.FC<{ userName: string, karma: number }> = ({ userName, karma }) => (
  <div className="px-6 space-y-6">
    <div className="bg-rose-500/10 p-8 rounded-[40px] border border-rose-500/20 flex items-center gap-6">
      <div className="w-16 h-16 bg-rose-500 rounded-[24px] flex items-center justify-center text-white text-2xl font-black shadow-lg shadow-rose-500/20">{userName.charAt(0).toUpperCase()}</div>
      <div>
        <p className="text-lg font-black text-white">{userName}</p>
        <p className="text-[10px] text-rose-500 uppercase font-black tracking-widest mt-1">{karma} Karma Rating</p>
      </div>
    </div>
