          <NavBtn icon={Trophy} label="Focus" active={activeTab === Tab.UPCOMING && !overlayView} onClick={() => {setActiveTab(Tab.UPCOMING); setOverlayView(null);}} />
          <NavBtn icon={Activity} label="Pulse" active={activeTab === Tab.BROWSE && !overlayView} onClick={() => {setActiveTab(Tab.BROWSE); setOverlayView(null);}} />
        </nav>
      </div>

      {showQuickAdd && <QuickAddModal onClose={() => setShowQuickAdd(false)} onAdd={val => {
