);

// --- OVERLAY VIEWS ---

const OverlayRouter: React.FC<{ view: string }> = ({ view }) => {
  switch (view) {
    case 'pomodoro': return <PomodoroModule />;
    case 'habits': return <HabitTracker />;
    case 'notes': return <NoteSystem />;
    case 'countdown': return <CountdownProtocol />;
    default: return null;
  }
};

const PomodoroModule = () => {
  const [mode, setMode] = useState<'pomo' | 'stop'>('pomo');
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);

  useEffect(() => {
    let interval: any;
    if (isActive) {
      interval = setInterval(() => {
        setTimeLeft(t => mode === 'pomo' ? Math.max(0, t - 1) : t + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isActive, mode]);

  const fmt = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="space-y-6 animate-in">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5 shadow-2xl">
        <h2 className="text-sm font-black text-white uppercase tracking-widest mb-4 flex items-center gap-2">
          <Info size={18} className="text-[var(--accent-primary)]" /> 
          Strategic Focus Protocol
        </h2>
        <div className="space-y-4 text-[11px] font-medium leading-relaxed">
          <section>
            <p className="text-white font-bold mb-1">What is this?</p>
            <p className="text-[var(--text-dim)]">The Focus Chamber uses the Pomodoro technique—timed sprints of deep work followed by short breaks to recharge your cognitive energy.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How it works in day-to-day life?</p>
            <p className="text-[var(--text-dim)]">By working in 25-minute bursts, you eliminate distractions and prevent brain fatigue. It trains your mind to enter "Flow State" faster and stay there longer.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How to use this section:</p>
            <p className="text-[var(--text-dim)]">Select <b>Pomodoro</b> for a 25-minute countdown or <b>Stopwatch</b> to track open-ended work. Tap the <b>Lightning Bolt</b> to start/pause and the <b>Clock</b> to reset.</p>
          </section>
        </div>
      </div>

      <div className="bg-[var(--card-bg)] p-10 rounded-[40px] border border-[var(--border-color)] text-center space-y-10 shadow-xl">
        <div className="flex bg-black/40 p-1.5 rounded-2xl border border-white/5 mx-auto w-fit">
          <button 
            onClick={() => {setMode('pomo'); setTimeLeft(25*60); setIsActive(false);}} 
            className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'pomo' ? 'bg-[var(--accent-primary)] text-white shadow-lg' : 'text-slate-500'}`}
          >
            Pomodoro
          </button>
          <button 
            onClick={() => {setMode('stop'); setTimeLeft(0); setIsActive(false);}} 
            className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'stop' ? 'bg-[var(--accent-primary)] text-white shadow-lg' : 'text-slate-500'}`}
          >
            Stopwatch
          </button>
        </div>

        <div className="text-8xl font-black tracking-tighter text-white tabular-nums drop-shadow-[0_0_15px_rgba(255,255,255,0.1)]">
          {fmt(timeLeft)}
        </div>

        <div className="flex gap-4 justify-center">
          <button 
            onClick={() => setIsActive(!isActive)} 
            className={`w-20 h-20 rounded-full flex items-center justify-center transition-all active:scale-90 ${isActive ? 'bg-rose-500 shadow-xl shadow-rose-500/20' : 'bg-[var(--accent-primary)] shadow-xl shadow-indigo-500/20'}`}
          >
            {isActive ? <X size={32} className="text-white"/> : <Zap size={32} className="text-white"/>}
          </button>
          <button 
            onClick={() => {setIsActive(false); setTimeLeft(mode === 'pomo' ? 25*60 : 0);}} 
            className="w-20 h-20 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-slate-500 hover:text-white transition-all active:scale-90"
          >
            <Clock size={32}/>
          </button>
        </div>
      </div>
    </div>
  );
};

const HabitTracker = () => {
  const [habits, setHabits] = useState<{name: string, streaks: boolean[]}[]>(() => {
    const saved = localStorage.getItem('lsp_habits_v2');
    return saved ? JSON.parse(saved) : [
      { name: 'Meditation', streaks: [true, true, true, true, false, false, false] },
      { name: 'Deep Work', streaks: [true, true, true, false, false, false, false] },
      { name: 'Hydration', streaks: [true, true, true, true, true, false, false] },
      { name: 'Reading', streaks: [true, true, false, false, false, false, false] }
    ];
  });

  const toggleDay = (habitIdx: number, dayIdx: number) => {
    const next = [...habits];
    next[habitIdx] = {
      ...next[habitIdx],
      streaks: [...next[habitIdx].streaks]
    };
    next[habitIdx].streaks[dayIdx] = !next[habitIdx].streaks[dayIdx];
    setHabits(next);
    localStorage.setItem('lsp_habits_v2', JSON.stringify(next));
  };

  const addHabitLoop = () => {
    const name = window.prompt("Identify new neural loop (Habit Name):");
    if (name && name.trim()) {
      const next = [...habits, { name: name.trim(), streaks: Array(7).fill(false) }];
      setHabits(next);
      localStorage.setItem('lsp_habits_v2', JSON.stringify(next));
    }
  };

  const deleteHabit = (idx: number) => {
    if (window.confirm("Terminate this habit loop?")) {
      const next = habits.filter((_, i) => i !== idx);
      setHabits(next);
      localStorage.setItem('lsp_habits_v2', JSON.stringify(next));
    }
  };

  return (
    <div className="space-y-6 animate-in">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5 shadow-2xl">
        <h2 className="text-sm font-black text-white uppercase tracking-widest mb-4 flex items-center gap-2">
          <Info size={18} className="text-[var(--accent-primary)]" /> 
          Neural Habit Sync Protocol
        </h2>
        <div className="space-y-4 text-[11px] font-medium leading-relaxed">
          <section>
            <p className="text-white font-bold mb-1">What is this?</p>
            <p className="text-[var(--text-dim)]">Habit Sync is a system designed to automate positive behaviors. By tracking recurring actions, you move them from conscious effort to subconscious routine.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How it works in day-to-day life?</p>
            <p className="text-[var(--text-dim)]">Small wins lead to massive results. Marking a habit as complete triggers a dopamine release, reinforcing the neural pathway and making it easier to repeat tomorrow.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How to use this section:</p>
            <p className="text-[var(--text-dim)]">Tap the small boxes to log completion for the week. Use the <b>Append Habit Loop</b> button at the bottom to define new routines you want to master.</p>
          </section>
        </div>
      </div>

      <div className="space-y-4">
        {habits.map((h, hIdx) => (
          <div key={`${h.name}-${hIdx}`} className="bg-[var(--card-bg)] p-5 rounded-3xl border border-[var(--border-color)] flex items-center justify-between group transition-all hover:border-white/10">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-500">
                <Flame size={20} className={h.streaks.filter(s => s).length > 3 ? "animate-pulse" : ""}/>
              </div>
              <div>
                <span className="font-bold text-white text-sm block">{h.name}</span>
                <span className="text-[8px] uppercase tracking-tighter text-slate-500 font-black">
                  Current Velocity: {h.streaks.filter(s => s).length}/7
                </span>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <div className="flex gap-1.5">
                {h.streaks.map((s, dIdx) => (
                  <button 
                    key={dIdx} 
                    onClick={() => toggleDay(hIdx, dIdx)}
                    className={`w-6 h-6 rounded-lg border transition-all active:scale-90 ${s ? 'bg-emerald-500 border-emerald-500 shadow-lg shadow-emerald-500/20' : 'border-white/5 bg-black/20 hover:bg-white/5'}`} 
                  />
                ))}
              </div>
              <button 
                onClick={() => deleteHabit(hIdx)}
                className="p-2 text-slate-700 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100"
              >
                <Trash2 size={14}/>
              </button>
            </div>
          </div>
        ))}

        {habits.length === 0 && (
          <div className="py-12 text-center opacity-20 font-black uppercase text-[10px] tracking-[0.3em]">
            No Active Neural Loops
          </div>
        )}

        <button 
          onClick={(e) => { e.stopPropagation(); addHabitLoop(); }} 
          type="button"
          className="w-full p-5 bg-[var(--accent-primary)]/5 border border-dashed border-[var(--accent-primary)]/20 rounded-3xl text-[10px] uppercase font-black tracking-[0.2em] text-[var(--accent-primary)] hover:bg-[var(--accent-primary)]/10 transition-all flex items-center justify-center gap-2 cursor-pointer active:scale-95"
        >
          <Plus size={16}/>
          Append Habit Loop
        </button>
      </div>
    </div>
  );
};

const NoteSystem = () => {
  const [notes, setNotes] = useState<{id: string, title: string, content: string}[]>(() => {
    const saved = localStorage.getItem('lsp_notes');
    return saved ? JSON.parse(saved) : [
      { id: '1', title: 'Protocol Delta', content: 'Focus strictly on energy management during peak hours 08:00 - 11:00.' }
    ];
  });

  const addNote = () => {
    const title = window.prompt("Trace Subject?");
    const content = window.prompt("Trace Content?");
    if (title || content) {
      const newNote = { id: Date.now().toString(), title: title || "Untitled", content: content || "..." };
      const updated = [...notes, newNote];
      setNotes(updated);
      localStorage.setItem('lsp_notes', JSON.stringify(updated));
    }
  };

  const deleteNote = (id: string) => {
    const updated = notes.filter(n => n.id !== id);
    setNotes(updated);
    localStorage.setItem('lsp_notes', JSON.stringify(updated));
  };

  return (
    <div className="space-y-4">
      <button onClick={addNote} className="w-full p-5 bg-[var(--card-bg)] border-2 border-dashed border-[var(--border-color)] rounded-3xl text-slate-500 text-center py-10 flex flex-col items-center gap-3 hover:text-[var(--accent-primary)] hover:border-[var(--accent-primary)]/40 transition-all">
        <Plus size={32}/>
        <span className="text-[10px] font-black uppercase tracking-widest">Capture Neural Trace</span>
      </button>
      <div className="grid grid-cols-2 gap-4">
        {notes.map(n => (
          <div key={n.id} className="p-5 bg-[var(--card-bg)] rounded-3xl border border-[var(--border-color)] space-y-2 relative group">
            <button onClick={() => deleteNote(n.id)} className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-rose-500 transition-opacity"><Trash2 size={12}/></button>
            <h4 className="text-[10px] font-black text-[var(--accent-primary)] uppercase tracking-widest pr-4">{n.title}</h4>
            <p className="text-[10px] text-slate-400 leading-relaxed">{n.content}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

const CountdownProtocol = () => {
  const [events, setEvents] = useState<{id: string, name: string, date: string}[]>(() => {
    const saved = localStorage.getItem('lsp_countdowns');
    return saved ? JSON.parse(saved) : [{ id: '1', name: 'Strategic Exam', date: new Date(Date.now() + 12*24*60*60*1000).toISOString().split('T')[0] }];
  });

  const addEvent = () => {
    const name = window.prompt("Target Name?");
    const date = window.prompt("Target Date? (YYYY-MM-DD)");
    if (name && date) {
      const updated = [...events, { id: Date.now().toString(), name, date }];
      setEvents(updated);
      localStorage.setItem('lsp_countdowns', JSON.stringify(updated));
    }
  };

  const getDaysRemaining = (targetDate: string) => {
    const diff = new Date(targetDate).getTime() - new Date().getTime();
    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
  };

  return (
    <div className="space-y-4">
      {events.map(ev => (
        <div key={ev.id} className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-[var(--border-color)] flex items-center justify-between overflow-hidden relative group">
           <div className="absolute top-0 right-0 p-4 opacity-5"><Target size={80}/></div>
           <button onClick={() => {setEvents(prev => prev.filter(e => e.id !== ev.id)); localStorage.setItem('lsp_countdowns', JSON.stringify(events.filter(e => e.id !== ev.id)));}} className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-rose-500 transition-opacity"><X size={14}/></button>
           <div>
             <p className="text-[10px] font-black text-[var(--text-dim)] uppercase tracking-[0.2em] mb-1">Neural Deadline</p>
             <h3 className="text-xl font-black text-white">{ev.name}</h3>
           </div>
           <div className="text-right">
             <span className="text-3xl font-black text-[var(--accent-primary)]">{getDaysRemaining(ev.date)}</span>
             <span className="text-[10px] font-bold text-slate-500 uppercase ml-2">Days</span>
           </div>
        </div>
      ))}
      <button onClick={addEvent} className="w-full p-4 border border-dashed border-white/10 rounded-2xl text-[9px] uppercase font-black tracking-widest text-slate-600 hover:text-indigo-400 transition-colors">Deploy Target Marker</button>
    </div>
  );
};

