                    updateDayData(new Date().toISOString().split('T')[0], { goals: newGoals });
                  }}
                  onDelete={id => {
                    const newGoals = currentDay.goals.filter(g => g.id !== id);
                    updateDayData(new Date().toISOString().split('T')[0], { goals: newGoals });
                  }}
                />
              )}
              {activeTab === Tab.UPCOMING && <ProductivityHub userName={userName} karma={karma} />}
              {activeTab === Tab.BROWSE && <PerformanceView currentDay={currentDay} categories={categories} />}
