const CountdownProtocol = () => {
  const [events, setEvents] = useState<{id: string, name: string, date: string}[]>(() => {
    const saved = localStorage.getItem('lsp_countdowns_v2');
    return saved ? JSON.parse(saved) : [{ id: '1', name: 'Strategic Exam', date: new Date(Date.now() + 12*24*60*60*1000).toISOString().split('T')[0] }];
  });
  const [currentMonth, setCurrentMonth] = useState(new Date());

  // Check for today's notifications
  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const todaysEvents = events.filter(e => e.date === today);
    if (todaysEvents.length > 0) {
      todaysEvents.forEach(e => {
        // Notification simulation (browser alert for simplicity)
        if (!sessionStorage.getItem(`alerted_${e.id}`)) {
          alert(`NEURAL NOTIFICATION: ${e.name} has arrived.`);
          sessionStorage.setItem(`alerted_${e.id}`, 'true');
        }
      });
    }
  }, [events]);

  const addEventAtDate = (date: string) => {
    const name = window.prompt(`New Event for ${date}:`);
    if (name && name.trim()) {
      const updated = [...events, { id: Date.now().toString(), name: name.trim(), date }];
      setEvents(updated);
      localStorage.setItem('lsp_countdowns_v2', JSON.stringify(updated));
    }
  };

  const deleteEvent = (id: string) => {
    const updated = events.filter(e => e.id !== id);
    setEvents(updated);
    localStorage.setItem('lsp_countdowns_v2', JSON.stringify(updated));
  };

  // Calendar Logic
  const daysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const startDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

  const renderCalendar = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const totalDays = daysInMonth(year, month);
    const startOffset = startDayOfMonth(year, month);
    const calendarDays = [];

    // Header
    const monthName = currentMonth.toLocaleString('default', { month: 'long' });

    // Fill offset
    for (let i = 0; i < startOffset; i++) {
      calendarDays.push(<div key={`offset-${i}`} className="h-20 border border-[var(--border-color)]/5 opacity-10"></div>);
    }

    // Fill days
    for (let d = 1; d <= totalDays; d++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isToday = dateStr === new Date().toISOString().split('T')[0];
      const dayEvents = events.filter(e => e.date === dateStr);

      calendarDays.push(
        <div 
          key={dateStr} 
          onClick={() => addEventAtDate(dateStr)}
          className={`h-20 border border-[var(--border-color)] p-1.5 relative overflow-hidden transition-colors cursor-pointer hover:bg-white/5 ${isToday ? 'bg-indigo-500/5' : ''}`}
        >
          <span className={`text-[9px] font-black ${isToday ? 'text-indigo-400' : 'text-slate-500'}`}>{d}</span>
          <div className="mt-1 space-y-0.5">
            {dayEvents.map(e => (
              <div key={e.id} className="text-[7px] font-bold bg-indigo-500 text-white px-1 py-0.5 rounded truncate flex justify-between items-center">
                <span className="truncate">{e.name}</span>
                <X size={6} className="ml-1 cursor-pointer" onClick={(ev) => { ev.stopPropagation(); deleteEvent(e.id); }} />
              </div>
            ))}
          </div>
        </div>
      );
    }

    return (
      <div className="bg-[var(--card-bg)] rounded-[32px] border border-[var(--border-color)] overflow-hidden">
        <div className="p-6 flex justify-between items-center border-b border-[var(--border-color)]">
          <h3 className="text-sm font-black text-white uppercase tracking-widest">{monthName} {year}</h3>
          <div className="flex gap-2">
            <button onClick={() => setCurrentMonth(new Date(year, month - 1))} className="p-2 hover:bg-white/5 rounded-xl"><ChevronLeft size={16}/></button>
            <button onClick={() => setCurrentMonth(new Date(year, month + 1))} className="p-2 hover:bg-white/5 rounded-xl"><ChevronRight size={16}/></button>
          </div>
        </div>
        <div className="grid grid-cols-7 text-center py-2 border-b border-[var(--border-color)] bg-black/20">
          {['S','M','T','W','T','F','S'].map((d, i) => (
            <span key={i} className="text-[8px] font-black text-slate-600 uppercase">{d}</span>
          ))}
        </div>
        <div className="grid grid-cols-7">
          {calendarDays}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in">
      {/* Educational Header Box */}
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5 shadow-2xl">
        <h2 className="text-sm font-black text-white uppercase tracking-widest mb-4 flex items-center gap-2">
          <Info size={18} className="text-[var(--accent-primary)]" /> 
          Countdown Protocol Engine
        </h2>
        <div className="space-y-4 text-[11px] font-medium leading-relaxed">
          <section>
            <p className="text-white font-bold mb-1">What is this?</p>
            <p className="text-[var(--text-dim)]">Countdown Protocol is a temporal awareness tool. It transforms static dates into active milestones, helping you anticipate and prepare for future demands.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How it works in day-to-day life?</p>
            <p className="text-[var(--text-dim)]">By visualizing events on a neural timeline, you reduce last-minute stress. The system alerts you on arrival, ensuring no objective is overlooked.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How to use this section:</p>
            <p className="text-[var(--text-dim)]">Tap any date on the calendar to deploy a target marker (event). Use arrows to navigate months. System alerts activate automatically on event dates.</p>
          </section>
        </div>
      </div>

      {renderCalendar()}

      <div className="space-y-4">
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-[var(--accent-primary)] px-2">Upcoming Trajectory</p>
        {events
          .filter(e => new Date(e.date) >= new Date(new Date().toISOString().split('T')[0]))
          .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime())
          .slice(0, 3)
          .map(ev => {
            const diff = new Date(ev.date).getTime() - new Date(new Date().toISOString().split('T')[0]).getTime();
            const days = Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
            return (
              <div key={ev.id} className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-[var(--border-color)] flex items-center justify-between overflow-hidden relative group">
                <div className="absolute top-0 right-0 p-4 opacity-5"><Target size={80}/></div>
                <div>
                  <p className="text-[10px] font-black text-[var(--text-dim)] uppercase tracking-[0.2em] mb-1">{ev.date}</p>
                  <h3 className="text-xl font-black text-white">{ev.name}</h3>
                </div>
                <div className="text-right">
                  <span className="text-3xl font-black text-[var(--accent-primary)]">{days}</span>
                  <span className="text-[10px] font-bold text-slate-500 uppercase ml-2">Days</span>
                </div>
              </div>
            );
          })}
      </div>
    </div>
  );
};

