          </div>
          <button onClick={() => setShowAI(true)} className="p-2.5 bg-[var(--accent-primary)]/20 rounded-xl text-[var(--accent-primary)] border border-[var(--accent-primary)]/20 hover:bg-[var(--accent-primary)]/30 transition-all">
            <Bot size={22}/>
