const PomodoroModule = () => {
  const [mode, setMode] = useState<'pomo' | 'stop'>('pomo');
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);

  useEffect(() => {
    let interval: any;
    if (isActive) {
      interval = setInterval(() => {
        setTimeLeft(t => mode === 'pomo' ? Math.max(0, t - 1) : t + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isActive, mode]);

  const fmt = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="space-y-6 animate-in">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5 shadow-2xl">
        <h2 className="text-sm font-black text-white uppercase tracking-widest mb-4 flex items-center gap-2">
          <Info size={18} className="text-[var(--accent-primary)]" /> 
          Strategic Focus Protocol
        </h2>
        <div className="space-y-4 text-[11px] font-medium leading-relaxed">
          <section>
            <p className="text-white font-bold mb-1">What is this?</p>
            <p className="text-[var(--text-dim)]">The Focus Chamber uses the Pomodoro technique—timed sprints of deep work followed by short breaks to recharge your cognitive energy.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How it works in day-to-day life?</p>
            <p className="text-[var(--text-dim)]">By working in 25-minute bursts, you eliminate distractions and prevent brain fatigue. It trains your mind to enter "Flow State" faster and stay there longer.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How to use this section:</p>
            <p className="text-[var(--text-dim)]">Select <b>Pomodoro</b> for a 25-minute countdown or <b>Stopwatch</b> to track open-ended work. Tap the <b>Lightning Bolt</b> to start/pause and the <b>Clock</b> to reset.</p>
          </section>
        </div>
      </div>

      <div className="bg-[var(--card-bg)] p-10 rounded-[40px] border border-[var(--border-color)] text-center space-y-10 shadow-xl">
        <div className="flex bg-black/40 p-1.5 rounded-2xl border border-white/5 mx-auto w-fit">
          <button 
            onClick={() => {setMode('pomo'); setTimeLeft(25*60); setIsActive(false);}} 
            className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'pomo' ? 'bg-[var(--accent-primary)] text-white shadow-lg' : 'text-slate-500'}`}
          >
            Pomodoro
          </button>
          <button 
            onClick={() => {setMode('stop'); setTimeLeft(0); setIsActive(false);}} 
            className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${mode === 'stop' ? 'bg-[var(--accent-primary)] text-white shadow-lg' : 'text-slate-500'}`}
          >
            Stopwatch
          </button>
        </div>

        <div className="text-8xl font-black tracking-tighter text-white tabular-nums drop-shadow-[0_0_15px_rgba(255,255,255,0.1)]">
          {fmt(timeLeft)}
        </div>

        <div className="flex gap-4 justify-center">
          <button 
            onClick={() => setIsActive(!isActive)} 
            className={`w-20 h-20 rounded-full flex items-center justify-center transition-all active:scale-90 ${isActive ? 'bg-rose-500 shadow-xl shadow-rose-500/20' : 'bg-[var(--accent-primary)] shadow-xl shadow-indigo-500/20'}`}
          >
            {isActive ? <X size={32} className="text-white"/> : <Zap size={32} className="text-white"/>}
          </button>
          <button 
            onClick={() => {setIsActive(false); setTimeLeft(mode === 'pomo' ? 25*60 : 0);}} 
            className="w-20 h-20 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-slate-500 hover:text-white transition-all active:scale-90"
          >
            <Clock size={32}/>
          </button>
        </div>
      </div>
    </div>
  );
};

const HabitTracker = () => {
  const [habits, setHabits] = useState<{name: string, streaks: boolean[]}[]>(() => {
    const saved = localStorage.getItem('lsp_habits_v2');
    return saved ? JSON.parse(saved) : [
      { name: 'Meditation', streaks: [true, true, true, true, false, false, false] },
      { name: 'Deep Work', streaks: [true, true, true, false, false, false, false] },
      { name: 'Hydration', streaks: [true, true, true, true, true, false, false] },
      { name: 'Reading', streaks: [true, true, false, false, false, false, false] }
    ];
  });

  const toggleDay = (habitIdx: number, dayIdx: number) => {
    const next = [...habits];
    next[habitIdx] = {
      ...next[habitIdx],
      streaks: [...next[habitIdx].streaks]
    };
    next[habitIdx].streaks[dayIdx] = !next[habitIdx].streaks[dayIdx];
    setHabits(next);
    localStorage.setItem('lsp_habits_v2', JSON.stringify(next));
  };

  const deleteHabit = (idx: number) => {
    if (window.confirm("Terminate this habit loop?")) {
      const next = habits.filter((_, i) => i !== idx);
      setHabits(next);
      localStorage.setItem('lsp_habits_v2', JSON.stringify(next));
    }
  };

  return (
    <div className="space-y-6 animate-in">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5 shadow-2xl">
        <h2 className="text-sm font-black text-white uppercase tracking-widest mb-4 flex items-center gap-2">
          <Info size={18} className="text-[var(--accent-primary)]" /> 
          Neural Habit Sync Protocol
        </h2>
        <div className="space-y-4 text-[11px] font-medium leading-relaxed">
          <section>
            <p className="text-white font-bold mb-1">What is this?</p>
            <p className="text-[var(--text-dim)]">Habit Sync is a system designed to automate positive behaviors. By tracking recurring actions, you move them from conscious effort to subconscious routine.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How it works in day-to-day life?</p>
            <p className="text-[var(--text-dim)]">Small wins lead to massive results. Marking a habit as complete triggers a dopamine release, reinforcing the neural pathway and making it easier to repeat tomorrow.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How to use this section:</p>
            <p className="text-[var(--text-dim)]">Tap the small boxes to log completion for the week.</p>
          </section>
        </div>
      </div>

      <div className="space-y-4">
        {habits.map((h, hIdx) => (
          <div key={`${h.name}-${hIdx}`} className="bg-[var(--card-bg)] p-5 rounded-3xl border border-[var(--border-color)] flex items-center justify-between group transition-all hover:border-white/10">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-500">
                <Flame size={20} className={h.streaks.filter(s => s).length > 3 ? "animate-pulse" : ""}/>
              </div>
              <div>
                <span className="font-bold text-white text-sm block">{h.name}</span>
                <span className="text-[8px] uppercase tracking-tighter text-slate-500 font-black">
                  Current Velocity: {h.streaks.filter(s => s).length}/7
                </span>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <div className="flex gap-1.5">
                {h.streaks.map((s, dIdx) => (
                  <button 
                    key={dIdx} 
                    onClick={() => toggleDay(hIdx, dIdx)}
                    className={`w-6 h-6 rounded-lg border transition-all active:scale-90 ${s ? 'bg-emerald-500 border-emerald-500 shadow-lg shadow-emerald-500/20' : 'border-white/5 bg-black/20 hover:bg-white/5'}`} 
                  />
                ))}
              </div>
              <button 
                onClick={() => deleteHabit(hIdx)}
                className="p-2 text-slate-700 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100"
              >
                <Trash2 size={14}/>
              </button>
            </div>
          </div>
        ))}

        {habits.length === 0 && (
          <div className="py-12 text-center opacity-20 font-black uppercase text-[10px] tracking-[0.3em]">
            No Active Neural Loops
          </div>
        )}
      </div>
    </div>
  );
};

const NoteSystem = () => {
  const [notes, setNotes] = useState<{id: string, title: string, content: string}[]>(() => {
    const saved = localStorage.getItem('lsp_notes');
    return saved ? JSON.parse(saved) : [
      { id: '1', title: 'Protocol Delta', content: 'Focus strictly on energy management during peak hours 08:00 - 11:00.' }
    ];
  });

  const addNote = () => {
    const title = window.prompt("Trace Subject?");
    const content = window.prompt("Trace Content?");
    if (title || content) {
      const newNote = { id: Date.now().toString(), title: title || "Untitled", content: content || "..." };
      const updated = [...notes, newNote];
      setNotes(updated);
      localStorage.setItem('lsp_notes', JSON.stringify(updated));
    }
  };

  const deleteNote = (id: string) => {
    const updated = notes.filter(n => n.id !== id);
    setNotes(updated);
    localStorage.setItem('lsp_notes', JSON.stringify(updated));
  };

  return (
    <div className="space-y-4">
      <button onClick={addNote} className="w-full p-5 bg-[var(--card-bg)] border-2 border-dashed border-[var(--border-color)] rounded-3xl text-slate-500 text-center py-10 flex flex-col items-center gap-3 hover:text-[var(--accent-primary)] hover:border-[var(--accent-primary)]/40 transition-all">
        <Plus size={32}/>
        <span className="text-[10px] font-black uppercase tracking-widest">Capture Neural Trace</span>
      </button>
      <div className="grid grid-cols-2 gap-4">
        {notes.map(n => (
          <div key={n.id} className="p-5 bg-[var(--card-bg)] rounded-3xl border border-[var(--border-color)] space-y-2 relative group">
            <button onClick={() => deleteNote(n.id)} className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-rose-500 transition-opacity"><Trash2 size={12}/></button>
            <h4 className="text-[10px] font-black text-[var(--accent-primary)] uppercase tracking-widest pr-4">{n.title}</h4>
            <p className="text-[10px] text-slate-400 leading-relaxed">{n.content}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

const CountdownProtocol = () => {
  const [events, setEvents] = useState<{id: string, name: string, date: string}[]>(() => {
    const saved = localStorage.getItem('lsp_countdowns_v3');
    return saved ? JSON.parse(saved) : [{ id: '1', name: 'Neural Launch', date: new Date().toISOString().split('T')[0] }];
  });
  const [currentMonth, setCurrentMonth] = useState(new Date());

  // Google Calendar style Notification Logic
  useEffect(() => {
    const interval = setInterval(() => {
      const today = new Date().toISOString().split('T')[0];
      const todaysEvents = events.filter(e => e.date === today);

      todaysEvents.forEach(e => {
        const key = `alerted_v3_${e.id}_${today}`;
        if (!localStorage.getItem(key)) {
          // Check if browser supports notifications
          if ("Notification" in window && Notification.permission === "granted") {
            new Notification("Neural Event", { body: `Protocol Active: ${e.name}` });
          } else {
            alert(`SYSTEM ALERT: ${e.name} is scheduled for today.`);
          }
          localStorage.setItem(key, 'true');
        }
      });
    }, 60000); // Check every minute
    return () => clearInterval(interval);
  }, [events]);

  const addEventAtDate = (date: string) => {
    const name = window.prompt(`Identify new event for ${date}:`);
    if (name && name.trim()) {
      const updated = [...events, { id: Date.now().toString(), name: name.trim(), date }];
      setEvents(updated);
      localStorage.setItem('lsp_countdowns_v3', JSON.stringify(updated));

      // Request notification permission if not yet granted
      if ("Notification" in window && Notification.permission !== "denied") {
        Notification.requestPermission();
      }
    }
  };

  const deleteEvent = (id: string) => {
    if(window.confirm("Terminate this temporal marker?")) {
      const updated = events.filter(e => e.id !== id);
      setEvents(updated);
      localStorage.setItem('lsp_countdowns_v3', JSON.stringify(updated));
    }
  };

  const renderCalendar = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const days = new Date(year, month + 1, 0).getDate();
    const monthName = currentMonth.toLocaleString('default', { month: 'long' });

    const cells = [];
    // Leading empty cells
    for (let i = 0; i < firstDay; i++) {
      cells.push(<div key={`empty-${i}`} className="h-20 border border-[var(--border-color)] opacity-5 bg-black/20" />);
    }

    // Actual days
    for (let d = 1; d <= days; d++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isToday = dateStr === new Date().toISOString().split('T')[0];
      const dayEvents = events.filter(e => e.date === dateStr);

      cells.push(
        <div 
          key={dateStr}
          onClick={() => addEventAtDate(dateStr)}
          className={`h-20 border border-[var(--border-color)] p-1 flex flex-col gap-1 cursor-pointer transition-all hover:bg-white/5 group relative ${isToday ? 'bg-indigo-500/5' : ''}`}
        >
          <span className={`text-[10px] font-black ${isToday ? 'text-[var(--accent-primary)]' : 'text-slate-500 group-hover:text-white'}`}>{d}</span>
          <div className="flex-1 overflow-y-auto custom-scroll space-y-0.5">
            {dayEvents.map(ev => (
              <div key={ev.id} className="bg-[var(--accent-primary)] text-white text-[7px] font-bold px-1 py-0.5 rounded truncate flex justify-between items-center">
                <span className="truncate">{ev.name}</span>
                <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="hover:text-rose-200"><X size={6}/></button>
              </div>
            ))}
          </div>
          {isToday && <div className="absolute bottom-1 right-1 w-1 h-1 bg-[var(--accent-primary)] rounded-full animate-pulse" />}
        </div>
      );
    }

    return (
      <div className="bg-[var(--card-bg)] rounded-[32px] border border-[var(--border-color)] overflow-hidden shadow-2xl">
        <div className="p-5 flex justify-between items-center border-b border-[var(--border-color)]">
          <h3 className="text-sm font-black text-white uppercase tracking-widest">{monthName} {year}</h3>
          <div className="flex gap-2">
            <button onClick={() => setCurrentMonth(new Date(year, month - 1))} className="p-2 hover:bg-white/10 rounded-xl transition-colors"><ChevronLeft size={18}/></button>
            <button onClick={() => setCurrentMonth(new Date(year, month + 1))} className="p-2 hover:bg-white/10 rounded-xl transition-colors"><ChevronRight size={18}/></button>
          </div>
        </div>
        <div className="grid grid-cols-7 text-center py-2 bg-black/10 border-b border-[var(--border-color)]">
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => (
            <span key={d} className="text-[8px] font-black text-slate-600 uppercase tracking-widest">{d}</span>
          ))}
        </div>
        <div className="grid grid-cols-7 bg-black/5">
          {cells}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in">
      {/* Educational Header Box */}
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5 shadow-2xl">
        <h2 className="text-sm font-black text-white uppercase tracking-widest mb-4 flex items-center gap-2">
          <Info size={18} className="text-[var(--accent-primary)]" /> 
          Countdown Protocol: Operational Manual
        </h2>
        <div className="space-y-4 text-[11px] font-medium leading-relaxed">
          <section>
            <p className="text-white font-bold mb-1">What is this?</p>
            <p className="text-[var(--text-dim)]">Countdown Protocol is your personal neural timeline. It’s a specialized calendar designed to map out critical deadlines and life-changing events before they arrive.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How it works in day-to-day life?</p>
            <p className="text-[var(--text-dim)]">Instead of being surprised by deadlines, you see them approaching. This spatial visualization reduces anxiety and allows your brain to allocate resources efficiently as dates get closer.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How to use this section:</p>
            <p className="text-[var(--text-dim)]"><b>Tap any date</b> to define a new event. Navigate months with the arrows. The system will trigger a <b>Neural Notification</b> (browser alert) on the day an event goes live.</p>
          </section>
        </div>
      </div>

      {renderCalendar()}

      {/* Trajectory Summary */}
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
          <Calendar size={14} className="text-[var(--accent-primary)]" />
          <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Temporal Trajectory</span>
        </div>
        {events
          .filter(e => new Date(e.date) >= new Date(new Date().toISOString().split('T')[0]))
          .sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime())
          .slice(0, 3)
          .map(ev => {
            const diff = new Date(ev.date).getTime() - new Date(new Date().toISOString().split('T')[0]).getTime();
            const days = Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
            return (
              <div key={ev.id} className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-[var(--border-color)] flex items-center justify-between overflow-hidden relative group">
                <div className="absolute top-0 right-0 p-4 opacity-5"><Target size={80}/></div>
                <div>
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">{ev.date}</p>
                  <h3 className="text-xl font-black text-white">{ev.name}</h3>
                </div>
                <div className="text-right">
                  <span className="text-3xl font-black text-[var(--accent-primary)] tabular-nums">{days}</span>
                  <span className="text-[10px] font-bold text-slate-600 uppercase ml-2">Days</span>
                </div>
              </div>
            );
          })}
        {events.length === 0 && (
          <div className="py-12 text-center opacity-20 font-black text-[10px] uppercase tracking-widest">No Active Milestones</div>
        )}
      </div>
    </div>
  );
};

// --- PERFORMANCE DASHBOARD ---

const PerformanceView: React.FC<{ 
  currentDay: DayData, 
  categories: any[], 
  onUpdateDayData: (date: string, updates: Partial<DayData>) => void,
  onUpdateCategories: (cats: any[]) => void
}> = ({ currentDay, categories, onUpdateDayData, onUpdateCategories }) => {
  const [h, setH] = useState(0);
  const [m, setM] = useState(0);

  useEffect(() => {
    const totalMins = parseInt(currentDay.deviceTime || '0');
    setH(Math.floor(totalMins / 60));
    setM(totalMins % 60);
  }, [currentDay.deviceTime]);

  const handleDeviceTimeChange = (newH: number, newM: number) => {
    const total = (newH * 60) + newM;
    onUpdateDayData(new Date().toISOString().split('T')[0], { deviceTime: total.toString() });
  };

  const getDeviceStatus = () => {
    const total = (h * 60) + m;
    if (total < 240) return { label: 'Good', color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20' };
    if (total <= 420) return { label: 'OK', color: 'text-amber-400', bg: 'bg-amber-500/10', border: 'border-amber-500/20' };
    return { label: 'Not Good', color: 'text-rose-400', bg: 'bg-rose-500/10', border: 'border-rose-500/20' };
  };

  const status = getDeviceStatus();

  const addLog = (catId: string, topic: string, hr: string, min: string) => {
    const total = (parseInt(hr || '0') * 60) + parseInt(min || '0');
    const newLog = { id: Date.now().toString(), category: catId, topic, time: total.toString() };
    onUpdateDayData(new Date().toISOString().split('T')[0], { studyLogs: [...currentDay.studyLogs, newLog] });
  };

  const deleteLog = (id: string) => {
    onUpdateDayData(new Date().toISOString().split('T')[0], { studyLogs: currentDay.studyLogs.filter(l => l.id !== id) });
  };

  const addSegment = () => {
    const name = window.prompt("Identify new neural segment:");
    if (name) {
      onUpdateCategories([...categories, { id: Date.now().toString(), name, icon: 'Cpu', color: 'from-slate-500 to-slate-700' }]);
    }
  };

  return (
    <div className="px-6 space-y-6 animate-in">
      {/* Device Time Matrix */}
      <div className={`p-8 rounded-[40px] border transition-all ${status.bg} ${status.border}`}>
        <div className="flex justify-between items-start mb-6">
          <div>
            <h2 className="text-[10px] font-black uppercase tracking-[0.2em] text-white/40 mb-1">Cognitive Load Matrix</h2>
            <p className="text-2xl font-black text-white">DEVICE TIME: <span className={status.color}>{status.label}</span></p>
          </div>
          <Cpu className={status.color} />
        </div>

        <div className="flex gap-4 mb-6">
          <div className="flex-1 bg-black/40 p-4 rounded-3xl border border-white/5">
            <span className="text-[8px] font-black uppercase text-slate-500 block mb-1">Hours</span>
            <input 
              type="number" 
              value={h} 
              onChange={e => handleDeviceTimeChange(parseInt(e.target.value) || 0, m)}
              className="w-full bg-transparent text-2xl font-black text-white outline-none" 
            />
          </div>
          <div className="flex-1 bg-black/40 p-4 rounded-3xl border border-white/5">
            <span className="text-[8px] font-black uppercase text-slate-500 block mb-1">Minutes</span>
            <input 
              type="number" 
              value={m} 
              onChange={e => handleDeviceTimeChange(h, parseInt(e.target.value) || 0)}
              className="w-full bg-transparent text-2xl font-black text-white outline-none" 
            />
          </div>
        </div>

        <div className="grid grid-cols-3 gap-2">
          <div className="p-3 bg-emerald-500/10 rounded-2xl border border-emerald-500/10 text-center">
            <span className="block text-[8px] font-black text-emerald-400 uppercase tracking-widest">Good</span>
            <span className="text-[9px] font-bold text-emerald-500/60">&lt; 4Hr</span>
          </div>
          <div className="p-3 bg-amber-500/10 rounded-2xl border border-amber-500/10 text-center">
            <span className="block text-[8px] font-black text-amber-400 uppercase tracking-widest">OK</span>
            <span className="text-[9px] font-bold text-amber-500/60">4-7Hr</span>
          </div>
          <div className="p-3 bg-rose-500/10 rounded-2xl border border-rose-500/10 text-center">
            <span className="block text-[8px] font-black text-rose-400 uppercase tracking-widest">Warning</span>
            <span className="text-[9px] font-bold text-rose-500/60">&gt; 7Hr</span>
          </div>
        </div>
      </div>

      {/* Performance Segments */}
      <div className="space-y-4">
        {categories.map(cat => (
          <PerformanceSegment 
            key={cat.id} 
            cat={cat} 
            logs={currentDay.studyLogs.filter(l => l.category === cat.id)} 
            onAdd={addLog}
            onDelete={deleteLog}
            onRemoveCat={() => onUpdateCategories(categories.filter(c => c.id !== cat.id))}
          />
        ))}

        <button 
          onClick={addSegment}
          className="w-full p-6 border-2 border-dashed border-white/5 rounded-[32px] text-slate-500 hover:text-[var(--accent-primary)] hover:border-[var(--accent-primary)]/20 transition-all flex items-center justify-center gap-2 group"
        >
          <Plus size={20} className="group-hover:scale-110 transition-transform" />
          <span className="text-[10px] font-black uppercase tracking-widest">Initialize Segment</span>
        </button>
