const PerformanceView: React.FC<{ 
  currentDay: DayData, 
  categories: any[], 
  onUpdateDayData: (date: string, updates: Partial<DayData>) => void,
  onUpdateCategories: (cats: any[]) => void
}> = ({ currentDay, categories, onUpdateDayData, onUpdateCategories }) => {
  const [h, setH] = useState(0);
  const [m, setM] = useState(0);

  useEffect(() => {
    const totalMins = parseInt(currentDay.deviceTime || '0');
    setH(Math.floor(totalMins / 60));
    setM(totalMins % 60);
  }, [currentDay.deviceTime]);

  const handleDeviceTimeChange = (newH: number, newM: number) => {
    const total = (newH * 60) + newM;
    onUpdateDayData(new Date().toISOString().split('T')[0], { deviceTime: total.toString() });
  };

  const getDeviceStatus = () => {
    const total = (h * 60) + m;
    if (total < 240) return { label: 'Good', color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20' };
    if (total <= 420) return { label: 'OK', color: 'text-amber-400', bg: 'bg-amber-500/10', border: 'border-amber-500/20' };
    return { label: 'Not Good', color: 'text-rose-400', bg: 'bg-rose-500/10', border: 'border-rose-500/20' };
  };

  const status = getDeviceStatus();

  const addLog = (catId: string, topic: string, hr: string, min: string) => {
    const total = (parseInt(hr || '0') * 60) + parseInt(min || '0');
    const newLog = { id: Date.now().toString(), category: catId, topic, time: total.toString() };
    onUpdateDayData(new Date().toISOString().split('T')[0], { studyLogs: [...currentDay.studyLogs, newLog] });
  };

  const deleteLog = (id: string) => {
    onUpdateDayData(new Date().toISOString().split('T')[0], { studyLogs: currentDay.studyLogs.filter(l => l.id !== id) });
  };

  const addSegment = () => {
    const name = window.prompt("Identify new neural segment:");
    if (name) {
      onUpdateCategories([...categories, { id: Date.now().toString(), name, icon: 'Cpu', color: 'from-slate-500 to-slate-700' }]);
    }
  };

  return (
    <div className="px-6 space-y-6 animate-in">
      {/* Device Time Monitoring Header */}
      <div className={`p-8 rounded-[40px] border transition-all ${status.bg} ${status.border}`}>
        <div className="flex justify-between items-start mb-6">
          <div>
            <h2 className="text-[10px] font-black uppercase tracking-[0.2em] text-white/40 mb-1">Cognitive Load: Device Time</h2>
            <p className="text-2xl font-black text-white">STATUS: <span className={status.color}>{status.label}</span></p>
          </div>
          <Smartphone className={status.color} />
        </div>

        <div className="flex gap-4 mb-6">
          <div className="flex-1 bg-black/40 p-4 rounded-3xl border border-white/5">
            <span className="text-[8px] font-black uppercase text-slate-500 block mb-1">Hours</span>
            <input 
              type="number" 
              value={h} 
              onChange={e => handleDeviceTimeChange(parseInt(e.target.value) || 0, m)}
              className="w-full bg-transparent text-2xl font-black text-white outline-none" 
            />
          </div>
          <div className="flex-1 bg-black/40 p-4 rounded-3xl border border-white/5">
            <span className="text-[8px] font-black uppercase text-slate-500 block mb-1">Minutes</span>
            <input 
              type="number" 
              value={m} 
              onChange={e => handleDeviceTimeChange(h, parseInt(e.target.value) || 0)}
              className="w-full bg-transparent text-2xl font-black text-white outline-none" 
            />
          </div>
        </div>

        <div className="grid grid-cols-3 gap-2">
          <div className="p-3 bg-emerald-500/10 rounded-2xl border border-emerald-500/10 text-center">
            <span className="block text-[8px] font-black text-emerald-400 uppercase tracking-widest">Good</span>
            <span className="text-[9px] font-bold text-emerald-500/60">&lt; 4Hr</span>
          </div>
          <div className="p-3 bg-amber-500/10 rounded-2xl border border-amber-500/10 text-center">
            <span className="block text-[8px] font-black text-amber-400 uppercase tracking-widest">OK</span>
            <span className="text-[9px] font-bold text-amber-500/60">4-7Hr</span>
          </div>
          <div className="p-3 bg-rose-500/10 rounded-2xl border border-rose-500/10 text-center">
            <span className="block text-[8px] font-black text-rose-400 uppercase tracking-widest">Not Good</span>
            <span className="text-[9px] font-bold text-rose-500/60">&gt; 7Hr</span>
          </div>
        </div>
      </div>

      {/* Categories / Segments */}
      <div className="space-y-4">
        {categories.map(cat => (
          <PerformanceSegment 
            key={cat.id} 
            cat={cat} 
            logs={currentDay.studyLogs.filter(l => l.category === cat.id)} 
            onAdd={addLog}
            onDelete={deleteLog}
            onRemoveCat={() => onUpdateCategories(categories.filter(c => c.id !== cat.id))}
          />
        ))}

        <button 
          onClick={addSegment}
          className="w-full p-6 border-2 border-dashed border-white/5 rounded-[32px] text-slate-500 hover:text-[var(--accent-primary)] hover:border-[var(--accent-primary)]/20 transition-all flex items-center justify-center gap-2 group"
        >
          <Plus size={20} className="group-hover:scale-110 transition-transform" />
          <span className="text-[10px] font-black uppercase tracking-widest">Deploy New Segment</span>
        </button>
      </div>
    </div>
  );
};

const PerformanceSegment: React.FC<{ 
  cat: any, 
  logs: StudyLog[], 
  onAdd: (cid: string, t: string, h: string, m: string) => void,
  onDelete: (id: string) => void,
  onRemoveCat: () => void
}> = ({ cat, logs, onAdd, onDelete, onRemoveCat }) => {
  const [topic, setTopic] = useState("");
  const [h, setH] = useState("");
  const [m, setM] = useState("");

  const totalMins = logs.reduce((acc, curr) => acc + parseInt(curr.time), 0);
  const totalH = Math.floor(totalMins / 60);
  const totalM = totalMins % 60;

  const getLogStatus = () => {
    const total = (totalH * 60) + totalM;
    if (total > 180) return { label: 'Good', color: 'text-emerald-400', bg: 'bg-emerald-500/5', border: 'border-emerald-500/10' };
    if (total >= 60) return { label: 'OK', color: 'text-amber-400', bg: 'bg-amber-500/5', border: 'border-amber-500/10' };
    return { label: 'Not Good', color: 'text-rose-400', bg: 'bg-rose-500/5', border: 'border-rose-500/10' };
  };

  const status = getLogStatus();

  return (
    <div className={`p-6 rounded-[32px] border transition-all bg-[var(--card-bg)] ${status.border} relative group`}>
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center gap-4">
          <div className={`p-3 rounded-2xl bg-gradient-to-br ${cat.color} text-white shadow-xl`}>
            {ICON_MAP[cat.icon] || <Cpu size={20}/>}
          </div>
          <div>
            <h3 className="text-[10px] font-black uppercase text-white tracking-widest">{cat.name}</h3>
            <p className={`text-[11px] font-black tracking-tight ${status.color}`}>
              {totalH}h {totalM}m • {status.label}
            </p>
          </div>
        </div>
        <button onClick={onRemoveCat} className="p-2 text-rose-500/10 hover:text-rose-500 transition-colors">
          <Trash2 size={16}/>
        </button>
      </div>

      {/* Input Row */}
      <div className="flex gap-2 mb-6">
        <input 
          placeholder="Topic..." 
          value={topic}
          onChange={e => setTopic(e.target.value)}
          className="flex-1 bg-black/40 border border-white/5 rounded-2xl px-4 py-3 text-[10px] text-white outline-none focus:border-[var(--accent-primary)]/40" 
        />
        <input 
          placeholder="Hr" 
          type="number"
          value={h}
          onChange={e => setH(e.target.value)}
          className="w-12 bg-black/40 border border-white/5 rounded-2xl px-2 py-3 text-[10px] text-center text-white outline-none" 
        />
        <input 
          placeholder="Min" 
          type="number"
          value={m}
          onChange={e => setM(e.target.value)}
          className="w-12 bg-black/40 border border-white/5 rounded-2xl px-2 py-3 text-[10px] text-center text-white outline-none" 
        />
        <button 
          onClick={() => { if(topic) { onAdd(cat.id, topic, h, m); setTopic(""); setH(""); setM(""); } }}
          className={`p-3 rounded-2xl bg-gradient-to-br ${cat.color} text-white shadow-md active:scale-90 transition-all`}
        >
          <Plus size={18} />
        </button>
      </div>

      {/* Health Indicator Footer */}
      <div className="flex gap-2 mb-4">
        <div className={`flex-1 h-1.5 rounded-full ${totalMins >= 180 ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.3)]' : 'bg-white/5'}`} />
        <div className={`flex-1 h-1.5 rounded-full ${totalMins >= 60 && totalMins < 180 ? 'bg-amber-500 shadow-[0_0_8px_rgba(245,158,11,0.3)]' : 'bg-white/5'}`} />
        <div className={`flex-1 h-1.5 rounded-full ${totalMins < 60 ? 'bg-rose-500 shadow-[0_0_8px_rgba(244,63,94,0.3)]' : 'bg-white/5'}`} />
      </div>

      {/* Log History */}
      <div className="space-y-1.5 max-h-32 overflow-y-auto custom-scroll">
        {logs.map(log => (
          <div key={log.id} className="flex justify-between items-center bg-black/20 px-4 py-2.5 rounded-xl border border-white/5 group/log">
            <span className="text-[10px] font-medium text-slate-300 truncate pr-4">{log.topic}</span>
            <div className="flex items-center gap-3">
              <span className="text-[9px] font-black text-slate-500 tabular-nums">
                {Math.floor(parseInt(log.time)/60)}h {parseInt(log.time)%60}m
              </span>
              <button onClick={() => onDelete(log.id)} className="text-slate-700 hover:text-rose-500 transition-colors">
                <X size={10}/>
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

