const CountdownProtocol = () => {
  const [events, setEvents] = useState<{id: string, name: string, date: string}[]>(() => {
    const saved = localStorage.getItem('lsp_countdowns_v3');
    return saved ? JSON.parse(saved) : [{ id: '1', name: 'Neural Launch', date: new Date().toISOString().split('T')[0] }];
  });
  const [currentMonth, setCurrentMonth] = useState(new Date());

  useEffect(() => {
    const interval = setInterval(() => {
      const today = new Date().toISOString().split('T')[0];
      const todaysEvents = events.filter(e => e.date === today);

      todaysEvents.forEach(e => {
        const key = `alerted_v3_${e.id}_${today}`;
        if (!localStorage.getItem(key)) {
          if ("Notification" in window && Notification.permission === "granted") {
            new Notification("Neural Event", { body: `Protocol Active: ${e.name}` });
          } else {
            alert(`SYSTEM ALERT: ${e.name} is scheduled for today.`);
          }
          localStorage.setItem(key, 'true');
        }
      });
    }, 60000);
    return () => clearInterval(interval);
  }, [events]);

  const addEventAtDate = (date: string) => {
    const name = window.prompt(`Identify new event for ${date}:`);
    if (name && name.trim()) {
      const updated = [...events, { id: Date.now().toString(), name: name.trim(), date }];
      setEvents(updated);
      localStorage.setItem('lsp_countdowns_v3', JSON.stringify(updated));
      if ("Notification" in window && Notification.permission !== "denied") {
        Notification.requestPermission();
      }
    }
  };

  const deleteEvent = (id: string) => {
    if(window.confirm("Terminate this temporal marker?")) {
      const updated = events.filter(e => e.id !== id);
      setEvents(updated);
      localStorage.setItem('lsp_countdowns_v3', JSON.stringify(updated));
    }
  };

  const renderCalendar = () => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const days = new Date(year, month + 1, 0).getDate();
    const monthName = currentMonth.toLocaleString('default', { month: 'long' });

    const cells = [];
    for (let i = 0; i < firstDay; i++) {
      cells.push(<div key={`empty-${i}`} className="h-20 border border-[var(--border-color)] opacity-5 bg-black/20" />);
    }

    for (let d = 1; d <= days; d++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isToday = dateStr === new Date().toISOString().split('T')[0];
      const dayEvents = events.filter(e => e.date === dateStr);

      cells.push(
        <div 
          key={dateStr}
          onClick={() => addEventAtDate(dateStr)}
          className={`h-20 border border-[var(--border-color)] p-1 flex flex-col gap-1 cursor-pointer transition-all hover:bg-white/5 group relative ${isToday ? 'bg-indigo-500/5' : ''}`}
        >
          <span className={`text-[10px] font-black ${isToday ? 'text-[var(--accent-primary)]' : 'text-slate-500 group-hover:text-white'}`}>{d}</span>
          <div className="flex-1 overflow-y-auto custom-scroll space-y-0.5">
            {dayEvents.map(ev => (
              <div key={ev.id} className="bg-[var(--accent-primary)] text-white text-[7px] font-bold px-1 py-0.5 rounded truncate flex justify-between items-center">
                <span className="truncate">{ev.name}</span>
                <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="hover:text-rose-200"><X size={6}/></button>
              </div>
            ))}
          </div>
          {isToday && <div className="absolute bottom-1 right-1 w-1 h-1 bg-[var(--accent-primary)] rounded-full animate-pulse" />}
        </div>
      );
    }

    return (
      <div className="bg-[var(--card-bg)] rounded-[32px] border border-[var(--border-color)] overflow-hidden shadow-2xl">
        <div className="p-5 flex justify-between items-center border-b border-[var(--border-color)]">
          <h3 className="text-sm font-black text-white uppercase tracking-widest">{monthName} {year}</h3>
          <div className="flex gap-2">
            <button onClick={() => setCurrentMonth(new Date(year, month - 1))} className="p-2 hover:bg-white/10 rounded-xl transition-colors"><ChevronLeft size={18}/></button>
            <button onClick={() => setCurrentMonth(new Date(year, month + 1))} className="p-2 hover:bg-white/10 rounded-xl transition-colors"><ChevronRight size={18}/></button>
          </div>
        </div>
        <div className="grid grid-cols-7 text-center py-2 bg-black/10 border-b border-[var(--border-color)]">
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => (
            <span key={d} className="text-[8px] font-black text-slate-600 uppercase tracking-widest">{d}</span>
          ))}
        </div>
        <div className="grid grid-cols-7 bg-black/5">
          {cells}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5 shadow-2xl">
        <h2 className="text-sm font-black text-white uppercase tracking-widest mb-4 flex items-center gap-2">
          <Info size={18} className="text-[var(--accent-primary)]" /> 
          Countdown Protocol: Operational Manual
        </h2>
        <div className="space-y-4 text-[11px] font-medium leading-relaxed">
          <section>
            <p className="text-white font-bold mb-1">What is this?</p>
            <p className="text-[var(--text-dim)]">Countdown Protocol is your personal neural timeline. It’s a specialized calendar designed to map out critical deadlines and life-changing events before they arrive.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How it works in day-to-day life?</p>
            <p className="text-[var(--text-dim)]">Instead of being surprised by deadlines, you see them approaching. This spatial visualization reduces anxiety and allows your brain to allocate resources efficiently as dates get closer.</p>
          </section>
          <section>
            <p className="text-white font-bold mb-1">How to use this section:</p>
            <p className="text-[var(--text-dim)]"><b>Tap any date</b> to define a new event. Navigate months with the arrows. The system will trigger a <b>Neural Notification</b> (browser alert) on the day an event goes live.</p>
          </section>
        </div>
      </div>
      {renderCalendar()}
    </div>
  );
};

