        <button onClick={() => val && onAdd(val)} className="w-full py-5 bg-[var(--accent-primary)] rounded-[24px] text-white font-black uppercase text-[10px] tracking-widest shadow-2xl shadow-indigo-500/20">Initialize</button>
      </div>
