const PomodoroModule: React.FC<any> = () => {
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [isMuted, setIsMuted] = useState(true);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    let interval: any;
    if (isActive) {
      interval = setInterval(() => setTimeLeft(t => Math.max(0, t - 1)), 1000);
      if (!isMuted && audioRef.current) audioRef.current.play();
    } else {
      if (audioRef.current) audioRef.current.pause();
    }
    return () => clearInterval(interval);
  }, [isActive, isMuted]);

  return (
    <div className="space-y-6 animate-in">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5">
        <h2 className="text-sm font-black text-white mb-2 flex items-center gap-2"><Timer className="text-indigo-500" /> Focus Chamber</h2>
        <p className="text-[11px] text-slate-400 leading-relaxed">Boost deep work by cycling 25-minute sprints. Prevents mental fatigue and keeps neural pathways primed for high-stakes problem solving.</p>
      </div>
      <div className="bg-[var(--card-bg)] p-12 rounded-[40px] border border-white/10 text-center space-y-8 relative overflow-hidden">
        <audio ref={audioRef} loop src="https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3" />
        <button onClick={() => setIsMuted(!isMuted)} className="absolute top-6 right-6 p-2 text-slate-500 hover:text-white transition-colors">
          {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} className="animate-pulse" />}
        </button>
        <div className="text-8xl font-black text-white tracking-tighter tabular-nums">{Math.floor(timeLeft / 60)}:{String(timeLeft % 60).padStart(2, '0')}</div>
        <div className="flex gap-4 justify-center">
          <button onClick={() => setIsActive(!isActive)} className={`w-20 h-20 rounded-full flex items-center justify-center ${isActive ? 'bg-rose-500' : 'bg-indigo-500'} shadow-2xl transition-all active:scale-95`}>
            {isActive ? <X size={32} /> : <Zap size={32} />}
          </button>
          <button onClick={() => { setIsActive(false); setTimeLeft(25*60); }} className="w-20 h-20 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-slate-500"><Clock size={32}/></button>
        </div>
      </div>
    </div>
  );
};

