const CountdownProtocol: React.FC<any> = ({ addNotification }) => {
  const [events, setEvents] = useState<any[]>(() => JSON.parse(localStorage.getItem('lsp_countdowns') || '[]'));
  const [currentDate] = useState(new Date());

  const addEvent = (d: number) => {
    const name = window.prompt("Event Protocol?");
    if (name) {
      const dateStr = `${currentDate.getFullYear()}-${currentDate.getMonth()+1}-${d}`;
      const newEvents = [...events, { name, date: dateStr }];
      setEvents(newEvents);
      localStorage.setItem('lsp_countdowns', JSON.stringify(newEvents));
      addNotification(`Marker Placed: ${name}`);
    }
  };

  return (
    <div className="space-y-6 animate-in">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5">
        <h2 className="text-sm font-black text-white mb-2 flex items-center gap-2"><Clock className="text-cyan-500" /> Countdown Matrix</h2>
        <p className="text-[11px] text-slate-400 leading-relaxed">Visualize your timeline. Map critical milestones to optimize neural preparation and deadline awareness.</p>
      </div>
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/10">
        <div className="grid grid-cols-7 gap-2">
          {Array.from({ length: 31 }, (_, i) => i + 1).map(d => (
            <div key={d} onClick={() => addEvent(d)} className="aspect-square bg-white/5 rounded-xl flex flex-col items-center justify-center cursor-pointer hover:bg-white/10 relative overflow-hidden group">
              <span className="text-[10px] font-black text-slate-600">{d}</span>
              {events.some(e => e.date.endsWith(`-${d}`)) && <div className="absolute inset-0 bg-cyan-500/20 flex items-center justify-center"><div className="w-1.5 h-1.5 bg-cyan-500 rounded-full animate-pulse" /></div>}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const NoteSystem = () => {
  const [notes, setNotes] = useState<any[]>(() => JSON.parse(localStorage.getItem('lsp_notes_v2') || '[]'));
  const [tag, setTag] = useState('Personal');

  const addNote = () => {
