        <p className="text-[11px] text-slate-400 leading-relaxed">Offload cognitive baggage. Use tags to categorize sparks of insight into structured data clusters for easier retrieval.</p>
      </div>
      <div className="flex gap-2 overflow-x-auto pb-2 custom-scroll">
        {['Personal', 'Work', 'Ideas', 'High-Priority'].map(t => (
