const AIModal: React.FC<any> = ({ onClose, context }) => {
  const [p, setP] = useState("");
  const [res, setRes] = useState("");
  const [loading, setLoading] = useState(false);
  const ask = async () => {
    if(!p) return; setLoading(true); setRes("");
    for await (const chunk of askAIArchitectStream(p, context)) { setRes(v => v + chunk); }
    setLoading(false);
  };
  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[100] flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-[var(--card-bg)] w-full max-w-md rounded-[48px] border border-white/10 overflow-hidden shadow-2xl" onClick={e => e.stopPropagation()}>
        <div className="p-8 bg-indigo-600 flex justify-between items-center text-white"><Bot size={32}/><h2 className="text-xl font-black uppercase tracking-tighter">Oracle</h2><button onClick={onClose}><X size={28}/></button></div>
        <div className="p-8 space-y-6">
          <textarea value={p} onChange={e => setP(e.target.value)} className="w-full bg-black/40 rounded-3xl p-6 text-white text-sm outline-none border border-white/5 h-44" placeholder="Strategic Request..." />
          <button onClick={ask} disabled={loading} className="w-full py-5 bg-indigo-600 text-white font-black uppercase text-[10px] tracking-widest rounded-3xl">{loading ? 'Synthesizing...' : 'Sync Architect'}</button>
          {res && <div className="p-6 bg-white/5 rounded-3xl text-sm italic text-indigo-100 max-h-40 overflow-y-auto custom-scroll leading-relaxed">{res}</div>}
        </div>
      </div>
    </div>
  );
};

