const CountdownProtocol: React.FC<any> = ({ addNotification }) => {
  const [events, setEvents] = useState<any[]>(() => JSON.parse(localStorage.getItem('lsp_temporal_markers_v2') || '[]'));
  const [currentMonth, setCurrentMonth] = useState(new Date());

  const addEvent = (d: number) => {
    const name = window.prompt("Designate Event?");
    if (name) {
      const dateStr = `${currentMonth.getFullYear()}-${currentMonth.getMonth()+1}-${d}`;
      const newEvents = [...events, { name, date: dateStr, id: Date.now() }];
      setEvents(newEvents);
      localStorage.setItem('lsp_temporal_markers_v2', JSON.stringify(newEvents));
      addNotification(`Protocol Locked: ${name}`);
    }
  };

  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();

  return (
    <div className="space-y-6 animate-in">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5 shadow-2xl">
        <h2 className="text-sm font-black text-white mb-2 flex items-center gap-2 uppercase tracking-widest"><Clock className="text-cyan-500" /> Temporal Matrix</h2>
        <p className="text-[11px] text-slate-400 leading-relaxed font-medium">Timeline visualization. Map critical mission markers to optimize preparation. Proactive notification protocol ensures zero deadline drift.</p>
      </div>
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/10 shadow-2xl">
        <div className="flex justify-between items-center mb-6">
          <h3 className="font-black text-white uppercase text-xs tracking-widest">{currentMonth.toLocaleString('default', { month: 'long' })} {currentMonth.getFullYear()}</h3>
          <div className="flex gap-2">
            <button onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth()-1))} className="p-2 bg-white/5 rounded-xl"><ChevronLeft size={16}/></button>
            <button onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth()+1))} className="p-2 bg-white/5 rounded-xl"><ChevronRight size={16}/></button>
          </div>
        </div>
        <div className="grid grid-cols-7 gap-2">
          {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(d => (
            <div key={d} onClick={() => addEvent(d)} className="aspect-square bg-white/5 rounded-xl flex flex-col items-center justify-center cursor-pointer hover:bg-[var(--accent-primary)]/20 relative group transition-all">
              <span className="text-[10px] font-black text-slate-600 group-hover:text-white">{d}</span>
              {events.some(e => e.date === `${currentMonth.getFullYear()}-${currentMonth.getMonth()+1}-${d}`) && (
                <div className="absolute top-1 right-1 w-1.5 h-1.5 bg-cyan-500 rounded-full animate-pulse shadow-glow shadow-cyan-500/50" />
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const NoteSystem = () => {
  const [notes, setNotes] = useState<any[]>(() => JSON.parse(localStorage.getItem('lsp_neural_notes_v3') || '[]'));
  const [activeTag, setActiveTag] = useState('Protocol');

  const addNote = () => {
    const content = window.prompt("Capture Neural Trace?");
    if (content) {
      const newNotes = [...notes, { content, tag: activeTag, id: Date.now() }];
      setNotes(newNotes);
      localStorage.setItem('lsp_neural_notes_v3', JSON.stringify(newNotes));
    }
  };

  return (
    <div className="space-y-6 animate-in">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5 shadow-2xl">
        <h2 className="text-sm font-black text-white mb-2 flex items-center gap-2 uppercase tracking-widest"><StickyNote className="text-amber-500" /> Neural Traces</h2>
        <p className="text-[11px] text-slate-400 leading-relaxed font-medium">External memory core. Offload cognitive overhead by capturing ideas instantly. Use tags to categorize your neural data for perfect recall.</p>
      </div>
      <div className="flex gap-2 overflow-x-auto pb-2 custom-scroll no-scrollbar">
        {['Protocol', 'Intelligence', 'Sync', 'Archive'].map(t => (
          <button key={t} onClick={() => setActiveTag(t)} className={`px-4 py-2 rounded-full text-[9px] font-black uppercase whitespace-nowrap transition-all border ${activeTag === t ? 'bg-amber-500 border-amber-400 text-white' : 'bg-white/5 border-white/10 text-slate-500'}`}>{t}</button>
        ))}
      </div>
      <button onClick={addNote} className="w-full p-8 bg-amber-500/10 border-2 border-dashed border-amber-500/30 rounded-[40px] text-amber-500 font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3 transition-all active:scale-95 shadow-lg shadow-amber-500/5">
        <Plus size={20} /> Capturing: {activeTag}
      </button>
      <div className="grid grid-cols-1 gap-4">
        {notes.filter(n => n.tag === activeTag).map(n => (
          <div key={n.id} className="p-6 bg-[var(--card-bg)] rounded-3xl border border-white/5 relative group shadow-lg hover:border-amber-500/30 transition-all">
            <div className="flex items-center gap-2 mb-2 text-[8px] font-black text-amber-500 uppercase tracking-widest"><Tag size={10} /> {n.tag}</div>
            <p className="text-sm text-slate-300 pr-6 leading-relaxed font-medium">{n.content}</p>
            <button onClick={() => {
              const updated = notes.filter(x => x.id !== n.id);
              setNotes(updated);
              localStorage.setItem('lsp_neural_notes_v3', JSON.stringify(updated));
            }} className="absolute top-4 right-4 text-slate-700 hover:text-rose-500 transition-colors"><Trash2 size={16}/></button>
          </div>
        ))}
      </div>
    </div>
  );
};

const OverlayRouter: React.FC<any> = ({ view, addNotification }) => {
  switch (view) {
    case 'pomodoro': return <PomodoroModule />;
    case 'habits': return <HabitTracker />;
    case 'notes': return <NoteSystem />;
    case 'countdown': return <CountdownProtocol addNotification={addNotification} />;
    default: return null;
  }
};

const QuickAddModal: React.FC<any> = ({ onClose, onAdd }) => {
  const [val, setVal] = useState('');
  return (
    <div className="fixed inset-0 bg-black/90 backdrop-blur-xl z-[100] flex items-end animate-in" onClick={onClose}>
      <div className="bg-[var(--card-bg)] w-full rounded-t-[40px] p-8 space-y-8 border-t border-white/10 shadow-2xl" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center text-slate-500 uppercase text-[10px] font-black tracking-widest"><span>Strategic Target</span><button onClick={onClose}><X size={20}/></button></div>
        <input autoFocus value={val} onChange={e => setVal(e.target.value)} placeholder="Enter details..." className="w-full bg-transparent text-2xl font-black text-white outline-none placeholder:opacity-20" onKeyDown={e => e.key === 'Enter' && val && onAdd(val)} />
        <button onClick={() => val && onAdd(val)} className="w-full py-5 bg-[var(--accent-primary)] rounded-[24px] text-white font-black uppercase text-xs tracking-widest shadow-2xl active:scale-95 transition-all">Initialize Objective</button>
      </div>
    </div>
  );
};

const AIModal: React.FC<any> = ({ onClose, context }) => {
  const [p, setP] = useState("");
  const [res, setRes] = useState("");
  const [loading, setLoading] = useState(false);
  const ask = async () => {
    if(!p) return; setLoading(true); setRes("");
    for await (const chunk of askAIArchitectStream(p, context)) { setRes(v => v + chunk); }
    setLoading(false);
  };
  return (
    <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[100] flex items-center justify-center p-4 animate-in" onClick={onClose}>
      <div className="bg-[var(--card-bg)] w-full max-w-md rounded-[48px] border border-white/10 overflow-hidden shadow-2xl" onClick={e => e.stopPropagation()}>
        <div className="p-8 bg-indigo-600 flex justify-between items-center text-white"><Bot size={32}/><h2 className="text-xl font-black uppercase tracking-tighter leading-none">Oracle AI</h2><button onClick={onClose}><X size={28}/></button></div>
        <div className="p-8 space-y-6">
          <textarea value={p} onChange={e => setP(e.target.value)} className="w-full bg-black/40 rounded-3xl p-6 text-white text-sm outline-none border border-white/5 h-44 resize-none" placeholder="Submit Strategic Inquiry..." />
          <button onClick={ask} disabled={loading} className="w-full py-5 bg-indigo-600 text-white font-black uppercase text-[10px] tracking-widest rounded-3xl shadow-lg active:scale-95 transition-all">{loading ? 'Synthesizing...' : 'Sync Architect'}</button>
          {res && <div className="p-6 bg-white/5 rounded-3xl text-sm italic text-indigo-100 max-h-40 overflow-y-auto custom-scroll leading-relaxed border border-white/5">{res}</div>}
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Trash2, Zap, Smartphone, GraduationCap, BookOpen, Briefcase, 
  Moon, Trophy, Sparkles, Target, Activity, Cpu, Check, Settings2, Clock, 
  CalendarDays, ChevronRight, Bot, ChevronLeft, Timer, StickyNote, Flame, 
  Waves, Sun, Snowflake, X, ArrowRight, Volume2, VolumeX, Tag, Info, Award
} from 'lucide-react';
import { AppState, Tab, DayData, Goal, StudyLog } from './types';
import { askAIArchitectStream } from './geminiService';

// --- CONSTANTS ---
const THEMES: Record<string, any> = {
  Night: { bg: '#020617', card: '#0f172a', accent: '#4f46e5', text: '#f8fafc' },
  Forest: { bg: '#052e16', card: '#064e3b', accent: '#22c55e', text: '#ecfdf5' },
  Sky: { bg: '#f0f9ff', card: '#ffffff', accent: '#0ea5e9', text: '#0c4a6e' },
  Winter: { bg: '#f1f5f9', card: '#ffffff', accent: '#38bdf8', text: '#1e293b' }
};

const DEFAULT_CATEGORIES = [
  { id: '1', name: 'Academic', icon: 'GraduationCap', color: 'from-blue-500 to-cyan-500' },
  { id: '2', name: 'Tuition', icon: 'BookOpen', color: 'from-emerald-500 to-teal-500' },
  { id: '3', name: 'Career', icon: 'Briefcase', color: 'from-amber-500 to-orange-500' },
  { id: '4', name: 'Self Growth', icon: 'Sparkles', color: 'from-purple-500 to-pink-500' },
  { id: '5', name: 'Islamic', icon: 'Moon', color: 'from-indigo-500 to-purple-500' }
];

const AVATARS = {
  boy: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Felix&backgroundColor=b6e3f4',
  girl: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Anya&backgroundColor=ffdfbf'
};

const ICON_MAP: Record<string, any> = {
  GraduationCap: <GraduationCap size={20}/>, BookOpen: <BookOpen size={20}/>, 
  Briefcase: <Briefcase size={20}/>, Moon: <Moon size={20}/>, Sparkles: <Sparkles size={20}/>,
  Activity: <Activity size={20}/>, Cpu: <Cpu size={20}/>
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [onboardingStep, setOnboardingStep] = useState(0); 
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TODAY);
  const [overlayView, setOverlayView] = useState<string | null>(null);
  const [theme, setTheme] = useState('Night');
  const [localData, setLocalData] = useState<Record<string, DayData>>({});
  const [categories, setCategories] = useState(DEFAULT_CATEGORIES);
  const [showSidebar, setShowSidebar] = useState(false);
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [showAI, setShowAI] = useState(false);
  const [userName, setUserName] = useState("");
  const [gender, setGender] = useState<'boy' | 'girl' | ''>('');
  const [karma, setKarma] = useState(100);
  const [notifications, setNotifications] = useState<string[]>([]);

  useEffect(() => {
    const savedData = localStorage.getItem('lsp_v7_data');
    const savedName = localStorage.getItem('lsp_user_name');
    const savedGender = localStorage.getItem('lsp_user_gender');
    const savedTheme = localStorage.getItem('lsp_theme');
    const savedCats = localStorage.getItem('lsp_categories');
    const onboardingComplete = localStorage.getItem('lsp_onboarding_done');

    if (savedData) setLocalData(JSON.parse(savedData));
    if (savedName && savedGender && onboardingComplete) { 
      setUserName(savedName); 
      setGender(savedGender as any);
      setAppState(AppState.DASHBOARD); 
    }
    if (savedTheme) applyTheme(savedTheme);
    if (savedCats) setCategories(JSON.parse(savedCats));
  }, []);

  const completeOnboarding = () => {
    localStorage.setItem('lsp_user_name', userName);
    localStorage.setItem('lsp_user_gender', gender);
    localStorage.setItem('lsp_onboarding_done', 'true');
    setAppState(AppState.DASHBOARD);
  };

  const applyTheme = (name: string) => {
    const t = THEMES[name];
    if (!t) return;
    const root = document.documentElement;
    root.style.setProperty('--app-bg', t.bg);
    root.style.setProperty('--card-bg', t.card);
    root.style.setProperty('--accent-primary', t.accent);
    root.style.setProperty('--text-main', t.text);
    localStorage.setItem('lsp_theme', name);
    setTheme(name);
  };

  const updateDayData = (date: string, updates: Partial<DayData>) => {
    const day = localData[date] || { goals: [], deviceTime: '0', studyLogs: [] };
    const newData = { ...localData, [date]: { ...day, ...updates } };
    localStorage.setItem('lsp_v7_data', JSON.stringify(newData));
    setLocalData(newData);
  };

  const updateCategories = (newCats: any[]) => {
    setCategories(newCats);
    localStorage.setItem('lsp_categories', JSON.stringify(newCats));
  };

  const currentDay = localData[new Date().toISOString().split('T')[0]] || { goals: [], deviceTime: '0', studyLogs: [] };

  if (appState === AppState.WELCOME) {
    if (onboardingStep === 0) {
      return (
        <div className="h-screen flex items-center justify-center p-6 bg-[#020617] overflow-hidden">
          <div className="w-full max-w-sm aspect-[3/4] bg-[#4c1d95] rounded-[40px] shadow-2xl relative border-[12px] border-[#2e1065] flex flex-col items-center justify-between p-10 text-center animate-in">
             <div className="mt-8">
               <h1 className="text-4xl font-black text-white tracking-tighter uppercase mb-2">MY LIFE<br/>SYNC PRO</h1>
               <p className="text-white/50 text-[10px] font-bold tracking-[0.3em]">NEURAL PROTOCOL v7</p>
             </div>
             <div className="w-full space-y-4">
               <input value={userName} onChange={e => setUserName(e.target.value)} className="w-full bg-white/10 border-2 border-white/20 p-4 rounded-2xl text-center text-white font-bold outline-none" placeholder="NAME" />
               <div className="flex gap-4">
                 <button onClick={() => setGender('boy')} className={`flex-1 p-2 rounded-2xl border-2 transition-all ${gender === 'boy' ? 'bg-indigo-500 border-white' : 'bg-white/5 border-white/10 opacity-50'}`}>
                   <img src={AVATARS.boy} className="w-16 h-16 mx-auto rounded-full" alt="Boy" />
                 </button>
                 <button onClick={() => setGender('girl')} className={`flex-1 p-2 rounded-2xl border-2 transition-all ${gender === 'girl' ? 'bg-pink-500 border-white' : 'bg-white/5 border-white/10 opacity-50'}`}>
                   <img src={AVATARS.girl} className="w-16 h-16 mx-auto rounded-full" alt="Girl" />
                 </button>
               </div>
             </div>
             <button disabled={!userName || !gender} onClick={() => setOnboardingStep(1)} className="w-16 h-16 bg-white rounded-full flex items-center justify-center text-[#4c1d95] disabled:opacity-30"><ArrowRight size={32} /></button>
          </div>
        </div>
      );
    } else {
      return (
        <div className="h-screen bg-[#020617] p-8 flex flex-col items-center justify-center animate-in">
           <div className="max-w-md w-full bg-[#0f172a] rounded-[48px] border border-white/10 p-10 shadow-2xl space-y-8">
              <h2 className="text-2xl font-black text-white">USER MANUAL 📖</h2>
              <div className="space-y-4 text-slate-400 text-sm">
                 <p>⚡ <b>Daily Sync:</b> Complete tasks to earn Karma points.</p>
                 <p>🧠 <b>Performance:</b> Monitor your cognitive load in real-time.</p>
                 <p>⏳ <b>Focus Chamber:</b> 25min sprints for extreme deep work.</p>
                 <p>🗓️ <b>Countdown:</b> Map your timeline and miss zero deadlines.</p>
              </div>
              <button onClick={completeOnboarding} className="w-full py-5 bg-indigo-500 rounded-3xl text-white font-black uppercase text-xs">Enter Neural OS</button>
           </div>
        </div>
      );
    }
  }

  return (
    <div className="flex h-screen overflow-hidden text-[var(--text-main)] bg-[var(--app-bg)] transition-colors duration-500">
      <Sidebar 
        isOpen={showSidebar} onClose={() => setShowSidebar(false)} 
        onSelectOverlay={setOverlayView} onThemeChange={applyTheme} activeTheme={theme} 
        userName={userName} gender={gender}
      />
      <div className="flex-1 flex flex-col relative overflow-hidden">
        <header className="px-6 pt-12 pb-5 flex justify-between items-center bg-transparent backdrop-blur-md z-30">
          <div className="flex items-center gap-4">
            <button onClick={() => setShowSidebar(true)} className="p-2 -ml-2 text-[var(--text-dim)]"><Menu size={26}/></button>
            <h1 className="text-xl font-black capitalize tracking-tight">{overlayView ? overlayView.replace('-', ' ') : activeTab}</h1>
          </div>
          <div className="flex gap-2">
            {notifications.length > 0 && <div className="p-2.5 bg-rose-500/20 rounded-xl text-rose-500 border border-rose-500/20"><Bell size={22} className="animate-bounce" /></div>}
            <button onClick={() => setShowAI(true)} className="p-2.5 bg-[var(--accent-primary)]/20 rounded-xl text-[var(--accent-primary)] border border-[var(--accent-primary)]/20 hover:bg-[var(--accent-primary)]/30"><Bot size={22}/></button>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto custom-scroll pb-32">
          {overlayView ? (
            <div className="px-6 py-4 animate-in">
              <button onClick={() => setOverlayView(null)} className="flex items-center gap-2 text-[10px] font-black uppercase text-[var(--text-dim)] mb-6"><ChevronLeft size={14}/> Dashboard</button>
              <OverlayRouter view={overlayView} addNotification={(msg) => setNotifications(p => [msg, ...p])} />
            </div>
          ) : (
            <>
              {activeTab === Tab.TODAY && <TodayView data={currentDay.goals} onToggle={id => {
                const newGoals = currentDay.goals.map(g => g.id === id ? { ...g, done: !g.done } : g);
                updateDayData(new Date().toISOString().split('T')[0], { goals: newGoals });
              }} onDelete={id => {
                const newGoals = currentDay.goals.filter(g => g.id !== id);
                updateDayData(new Date().toISOString().split('T')[0], { goals: newGoals });
              }} />}
              {activeTab === Tab.UPCOMING && <ProductivityHub userName={userName} karma={karma} localData={localData} />}
              {activeTab === Tab.BROWSE && <PerformanceView currentDay={currentDay} categories={categories} onUpdateDayData={updateDayData} onUpdateCategories={updateCategories} />}
            </>
          )}
        </main>

        <button onClick={() => setShowQuickAdd(true)} className="fixed right-6 bottom-28 w-14 h-14 bg-[var(--accent-primary)] rounded-full shadow-2xl flex items-center justify-center text-white z-40 active:scale-95 transition-all"><Plus size={28} /></button>

        <nav className="fixed bottom-0 left-0 right-0 bg-[var(--app-bg)]/80 backdrop-blur-2xl border-t border-[var(--border-color)] px-8 pt-4 pb-8 flex justify-between items-center z-50">
          <NavBtn icon={CalendarDays} label="Daily" active={activeTab === Tab.TODAY && !overlayView} onClick={() => {setActiveTab(Tab.TODAY); setOverlayView(null);}} />
          <NavBtn icon={Trophy} label="Stats" active={activeTab === Tab.UPCOMING && !overlayView} onClick={() => {setActiveTab(Tab.UPCOMING); setOverlayView(null);}} />
          <NavBtn icon={Activity} label="Energy" active={activeTab === Tab.BROWSE && !overlayView} onClick={() => {setActiveTab(Tab.BROWSE); setOverlayView(null);}} />
        </nav>
      </div>

      {showQuickAdd && <QuickAddModal onClose={() => setShowQuickAdd(false)} onAdd={val => {
        const date = new Date().toISOString().split('T')[0];
        const day = localData[date] || { goals: [], deviceTime: '0', studyLogs: [] };
        updateDayData(date, { goals: [...day.goals, { id: Date.now().toString(), text: val, priority: 'standard', done: false, date }] });
        setShowQuickAdd(false);
      }} />}
      {showAI && <AIModal onClose={() => setShowAI(false)} context={currentDay} />}
    </div>
  );
};

