const TodayView: React.FC<any> = ({ data, onToggle, onDelete }) => (
  <div className="px-6 space-y-4">
    {data.map((g: any) => (
      <div key={g.id} className="flex items-start gap-4 p-5 bg-[var(--card-bg)] border border-[var(--border-color)] rounded-3xl active:scale-[0.98] transition-transform shadow-sm">
        <button onClick={() => onToggle(g.id)} className={`mt-0.5 w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all ${g.done ? 'bg-[var(--accent-primary)] border-[var(--accent-primary)] shadow-lg shadow-indigo-500/20' : 'border-slate-800'}`}>
          {g.done && <Check size={14} className="text-white" strokeWidth={4}/>}
