const PerformanceView: React.FC<any> = ({ currentDay, categories, onUpdateDayData, onUpdateCategories }) => {
  const totalMins = parseInt(currentDay.deviceTime || '0');
  const h = Math.floor(totalMins / 60);
  const m = totalMins % 60;

  const getStatus = () => {
    if (totalMins < 240) return { label: 'Good', color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20' };
    if (totalMins <= 420) return { label: 'OK', color: 'text-amber-400', bg: 'bg-amber-500/10', border: 'border-amber-500/20' };
    return { label: 'Not Good', color: 'text-rose-400', bg: 'bg-rose-500/10', border: 'border-rose-500/20' };
  };
  const status = getStatus();

  const handleTimeUpdate = (val: string, type: 'h' | 'm') => {
    const num = parseInt(val) || 0;
    const newTotal = type === 'h' ? (num * 60) + m : (h * 60) + num;
    onUpdateDayData(new Date().toISOString().split('T')[0], { deviceTime: newTotal.toString() });
  };

  const addLog = (catId: string, topic: string, hr: string, min: string) => {
    const logTotal = (parseInt(hr || '0') * 60) + parseInt(min || '0');
    const newLog = { id: Date.now().toString(), category: catId, topic, time: logTotal.toString() };
    onUpdateDayData(new Date().toISOString().split('T')[0], { studyLogs: [...currentDay.studyLogs, newLog] });
  };

  return (
    <div className="px-6 space-y-6 animate-in">
      {/* Device Time Section */}
      <div className={`p-8 rounded-[40px] border transition-all duration-700 shadow-xl ${status.bg} ${status.border}`}>
        <div className="flex justify-between items-start mb-6">
          <div>
            <h2 className="text-[10px] font-black uppercase text-white/40 mb-1 tracking-widest">Cognitive Energy Load</h2>
            <p className="text-2xl font-black text-white">STATUS: <span className={status.color}>{status.label}</span></p>
          </div>
          <Smartphone className={status.color} />
        </div>
        <div className="flex gap-4">
          <div className="flex-1 bg-black/40 p-4 rounded-3xl border border-white/5">
            <span className="text-[8px] font-black uppercase text-slate-500 block mb-1">Hours</span>
            <input type="number" value={h} onChange={e => handleTimeUpdate(e.target.value, 'h')} className="w-full bg-transparent text-2xl font-black text-white outline-none" />
          </div>
          <div className="flex-1 bg-black/40 p-4 rounded-3xl border border-white/5">
            <span className="text-[8px] font-black uppercase text-slate-500 block mb-1">Minutes</span>
            <input type="number" value={m} onChange={e => handleTimeUpdate(e.target.value, 'm')} className="w-full bg-transparent text-2xl font-black text-white outline-none" />
          </div>
        </div>
      </div>

      {/* Categories Sections */}
      <div className="space-y-4 pb-12">
        {categories.map((cat: any) => (
          <SegmentCard 
            key={cat.id} 
            cat={cat} 
            logs={currentDay.studyLogs.filter((l: any) => l.category === cat.id)}
            onAdd={addLog}
            onDelete={(id: string) => onUpdateDayData(new Date().toISOString().split('T')[0], { studyLogs: currentDay.studyLogs.filter((l: any) => l.id !== id) })}
            onRemove={() => onUpdateCategories(categories.filter((c: any) => c.id !== cat.id))}
          />
        ))}

        <button 
          onClick={() => {
            const name = window.prompt("New segment name?");
            if (name) onUpdateCategories([...categories, { id: Date.now().toString(), name, icon: 'Cpu', color: 'from-slate-500 to-slate-700' }]);
          }}
          className="w-full p-6 border-2 border-dashed border-white/10 rounded-[32px] text-slate-500 font-black uppercase text-xs tracking-widest hover:border-white/20 transition-all active:scale-95"
        >
          Add Custom Segment
        </button>
      </div>
    </div>
  );
};

const SegmentCard = ({ cat, logs, onAdd, onDelete, onRemove }: any) => {
  const [topic, setTopic] = useState("");
  const [h, setH] = useState("");
  const [m, setM] = useState("");

  const totalMins = logs.reduce((acc: number, curr: any) => acc + parseInt(curr.time), 0);
  const totalH = Math.floor(totalMins / 60);
  const totalM = totalMins % 60;

  const getStatus = () => {
    if (totalMins > 180) return { label: 'Good', color: 'text-emerald-400', border: 'border-emerald-500/20' };
    if (totalMins >= 60) return { label: 'OK', color: 'text-amber-400', border: 'border-amber-400/20' };
    return { label: 'Not Good', color: 'text-rose-400', border: 'border-rose-400/20' };
  };
  const status = getStatus();

  return (
    <div className={`p-6 bg-[var(--card-bg)] rounded-[32px] border transition-all ${status.border} group relative`}>
      <button onClick={onRemove} className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity p-2 text-rose-500/20 hover:text-rose-500"><Trash2 size={16}/></button>
      <div className="flex items-center gap-4 mb-6">
        <div className={`p-3 rounded-2xl bg-gradient-to-br ${cat.color} text-white shadow-lg`}>{ICON_MAP[cat.icon] || <Cpu size={20}/>}</div>
        <div>
          <h3 className="text-[10px] font-black uppercase text-white tracking-widest">{cat.name}</h3>
          <p className={`text-xs font-black ${status.color}`}>{totalH}h {totalM}m • {status.label}</p>
        </div>
      </div>
      <div className="flex gap-2 mb-4">
        <input placeholder="Topic..." value={topic} onChange={e => setTopic(e.target.value)} className="flex-1 bg-black/40 border border-white/5 rounded-2xl px-4 py-3 text-[11px] text-white outline-none" />
        <input placeholder="H" value={h} onChange={e => setH(e.target.value)} className="w-12 bg-black/40 border border-white/5 rounded-2xl px-2 py-3 text-center text-[11px] text-white outline-none" />
        <input placeholder="M" value={m} onChange={e => setM(e.target.value)} className="w-12 bg-black/40 border border-white/5 rounded-2xl px-2 py-3 text-center text-[11px] text-white outline-none" />
        <button onClick={() => { if(topic) { onAdd(cat.id, topic, h, m); setTopic(""); setH(""); setM(""); } }} className={`p-3 rounded-2xl bg-gradient-to-br ${cat.color} text-white active:scale-90 transition-all`}><Plus size={18} /></button>
      </div>
      <div className="space-y-2">
        {logs.map((l: any) => (
          <div key={l.id} className="flex justify-between items-center text-[10px] bg-white/5 p-3 rounded-xl border border-white/5">
            <span className="text-slate-400">{l.topic}</span>
            <div className="flex items-center gap-3">
              <span className="text-white font-bold">{Math.floor(l.time/60)}h {l.time%60}m</span>
              <button onClick={() => onDelete(l.id)} className="text-rose-500/30 hover:text-rose-500"><X size={14}/></button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

const PomodoroModule = () => {
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [isMuted, setIsMuted] = useState(true);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    let interval: any;
    if (isActive) {
      interval = setInterval(() => setTimeLeft(t => Math.max(0, t - 1)), 1000);
      if (!isMuted && audioRef.current) audioRef.current.play();
    } else {
      if (audioRef.current) audioRef.current.pause();
    }
    return () => clearInterval(interval);
  }, [isActive, isMuted]);

  return (
    <div className="space-y-6 animate-in">
      <div className="bg-[var(--card-bg)] p-6 rounded-[32px] border border-white/5 shadow-2xl">
        <h2 className="text-sm font-black text-white mb-2 flex items-center gap-2 uppercase tracking-widest"><Timer className="text-indigo-500" /> Focus Protocol</h2>
        <p className="text-[11px] text-slate-400 leading-relaxed font-medium">Immerse in Deep Work. 25-minute sprints maximize neural efficiency while strategic breaks prevent decision fatigue.</p>
      </div>
      <div className="bg-[var(--card-bg)] p-12 rounded-[40px] border border-white/10 text-center space-y-10 relative overflow-hidden shadow-2xl">
        <audio ref={audioRef} loop src="https://www.soundhelix.com/examples/mp3/SoundHelix-Song-8.mp3" />
        <button onClick={() => setIsMuted(!isMuted)} className="absolute top-8 right-8 p-3 bg-white/5 rounded-full text-slate-500 hover:text-white transition-all">
          {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} className="animate-pulse text-indigo-400" />}
        </button>
        <div className="text-8xl font-black text-white tracking-tighter tabular-nums">{Math.floor(timeLeft / 60)}:{String(timeLeft % 60).padStart(2, '0')}</div>
        <div className="flex gap-4 justify-center">
          <button onClick={() => setIsActive(!isActive)} className={`w-20 h-20 rounded-full flex items-center justify-center transition-all active:scale-90 ${isActive ? 'bg-rose-500' : 'bg-indigo-500'}`}>
            {isActive ? <X size={32} /> : <Zap size={32} />}
          </button>
          <button onClick={() => { setIsActive(false); setTimeLeft(25*60); }} className="w-20 h-20 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-slate-500"><Clock size={32}/></button>
        </div>
      </div>
    </div>
  );
};

