const EnergyMatrix: React.FC<any> = ({ currentDay, updateDayData }) => {
  const mins = parseInt(currentDay.deviceTime || '0');
  const h = Math.floor(mins / 60);
  const m = mins % 60;

  const getDeviceStatus = () => {
    if (mins < 240) return { label: 'Good', color: 'text-emerald-400', glow: 'shadow-[0_0_30px_rgba(16,185,129,0.1)]' };
    if (mins <= 420) return { label: 'OK', color: 'text-amber-400', glow: 'shadow-[0_0_30px_rgba(245,158,11,0.1)]' };
    return { label: 'Not Good', color: 'text-rose-400', glow: 'shadow-[0_0_30px_rgba(244,63,94,0.1)]' };
  };
  const status = getDeviceStatus();

  const handleTimeChange = (val: string, type: 'h'|'m') => {
    const num = parseInt(val) || 0;
    const newMins = type === 'h' ? (num * 60) + m : (h * 60) + num;
    updateDayData(new Date().toISOString().split('T')[0], { deviceTime: newMins.toString() });
  };

  return (
    <div className="space-y-8 animate-in pb-12">
      <div className={`p-8 bg-slate-900 rounded-[2.5rem] border border-white/5 transition-all duration-700 ${status.glow}`}>
        <div className="flex justify-between items-start mb-6">
          <div className="space-y-1">
            <h4 className="text-[10px] font-black uppercase text-slate-500 tracking-widest flex items-center gap-2"><Smartphone size={14}/> Device Usage</h4>
            <p className="text-xl font-black">Rating: <span className={status.color}>{status.label}</span></p>
          </div>
        </div>
        <div className="flex gap-4">
          <div className="flex-1 space-y-2">
            <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Hours</span>
            <input type="number" value={h} onChange={e => handleTimeChange(e.target.value, 'h')} className="w-full bg-black/30 border border-white/5 p-4 rounded-2xl text-2xl font-black outline-none focus:border-indigo-500" />
          </div>
          <div className="flex-1 space-y-2">
            <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Minutes</span>
            <input type="number" value={m} onChange={e => handleTimeChange(e.target.value, 'm')} className="w-full bg-black/30 border border-white/5 p-4 rounded-2xl text-2xl font-black outline-none focus:border-indigo-500" />
          </div>
        </div>
      </div>

      <div className="space-y-4">
        {['Academic', 'Tuition', 'Career', 'Self Growth', 'Islamic', 'Custom'].map(seg => (
          <SegmentCard 
            key={seg} 
            name={seg} 
            logs={currentDay.studyLogs.filter((l: any) => l.category === seg)} 
            onAdd={(topic: string, hr: string, min: string) => {
              const total = (parseInt(hr) * 60) + parseInt(min);
              updateDayData(new Date().toISOString().split('T')[0], { studyLogs: [...currentDay.studyLogs, {id: Date.now().toString(), category: seg, topic, time: total.toString()}] });
            }}
            onDelete={(id: string) => {
              updateDayData(new Date().toISOString().split('T')[0], { studyLogs: currentDay.studyLogs.filter((l: any) => l.id !== id) });
            }}
          />
        ))}
      </div>
    </div>
  );
};

const SegmentCard: React.FC<any> = ({ name, logs, onAdd, onDelete }) => {
  const [topic, setTopic] = useState("");
  const [hr, setHr] = useState("");
  const [min, setMin] = useState("");
  const totalMins = logs.reduce((acc: number, cur: any) => acc + parseInt(cur.time), 0);

  const getStatus = () => {
    if (totalMins >= 180) return { label: 'Good', color: 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' };
    if (totalMins >= 60) return { label: 'OK', color: 'bg-amber-500/10 border-amber-500/20 text-amber-400' };
    return { label: 'Low', color: 'bg-rose-500/10 border-rose-500/20 text-rose-400' };
  };
  const status = getStatus();

  return (
    <div className={`p-6 rounded-[2rem] border transition-all ${status.color}`}>
      <div className="flex justify-between items-center mb-6">
        <h4 className="text-sm font-black uppercase tracking-tight">{name}</h4>
        <span className="text-[10px] font-black px-3 py-1 bg-black/20 rounded-full">{Math.floor(totalMins/60)}h {totalMins%60}m</span>
      </div>

      <div className="flex gap-2 mb-4">
        <input placeholder="Topic..." value={topic} onChange={e => setTopic(e.target.value)} className="flex-1 bg-black/20 rounded-xl px-4 py-3 text-xs outline-none" />
        <input placeholder="H" value={hr} onChange={e => setHr(e.target.value)} className="w-12 bg-black/20 rounded-xl px-2 py-3 text-center text-xs outline-none" />
        <input placeholder="M" value={min} onChange={e => setMin(e.target.value)} className="w-12 bg-black/20 rounded-xl px-2 py-3 text-center text-xs outline-none" />
        <button onClick={() => { if(topic) onAdd(topic, hr||"0", min||"0"); setTopic(""); setHr(""); setM(""); }} className="p-3 bg-white/10 rounded-xl active:scale-90 transition-all"><Plus size={18}/></button>
      </div>

      <div className="space-y-2">
        {logs.map((log: any) => (
          <div key={log.id} className="flex justify-between items-center text-[10px] font-bold bg-black/10 p-2 px-3 rounded-lg">
            <span>{log.topic}</span>
            <div className="flex items-center gap-2">
              <span>{Math.floor(log.time/60)}h {log.time%60}m</span>
              <button onClick={() => onDelete(log.id)} className="opacity-40 hover:opacity-100"><X size={14}/></button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

