const OverlayRouter: React.FC<any> = ({ view, onClose, addNotification, userName, gender, setUserName, setGender, selectedCalendarDate, setSelectedCalendarDate }) => {
  switch (view) {
    case 'focus': return <FocusChamber onClose={onClose} />;
    case 'habits': return <HabitSync onClose={onClose} />;
    case 'countdown': return <CountdownProtocol onClose={onClose} addNotification={addNotification} selectedDate={selectedCalendarDate} setSelectedDate={setSelectedCalendarDate} />;
    case 'notes': return <NeuralNotes onClose={onClose} />;
    case 'oracle': return <AIModal onClose={onClose} />;
    case 'quick-add': return <QuickAddModal onClose={onClose} />;
    case 'profile': return <ProfileSettings onClose={onClose} name={userName} gender={gender} setUserName={setUserName} setGender={setGender} />;
    default: return null;
  }
};

const FocusChamber: React.FC<any> = ({ onClose }) => {
  const [time, setTime] = useState(25 * 60);
  const [active, setActive] = useState(false);

  useEffect(() => {
    let timer: any;
    if (active && time > 0) timer = setInterval(() => setTime(t => t - 1), 1000);
    return () => clearInterval(timer);
  }, [active, time]);

  return (
    <div className="space-y-8 animate-in">
      <div className="bg-indigo-600 p-6 rounded-[2rem] text-white">
