const CountdownProtocol: React.FC<any> = ({ onClose, addNotification, selectedDate, setSelectedDate }) => {
  const [events, setEvents] = useState<any[]>(() => JSON.parse(localStorage.getItem('lsp_v8_events') || '[]'));

  const addEvent = () => {
    const text = window.prompt("Event Name?");
    if (text) {
      const newEvents = [...events, { id: Date.now().toString(), date: selectedDate, text }];
      setEvents(newEvents);
      localStorage.setItem('lsp_v8_events', JSON.stringify(newEvents));
      addNotification(`Event Synced: ${text}`);
    }
  };

  const dayEvents = events.filter(e => e.date === selectedDate);

  return (
    <div className="space-y-8 animate-in">
      <div className="bg-cyan-600 p-6 rounded-[2rem] text-white">
        <h2 className="text-lg font-black uppercase mb-2 flex items-center gap-2"><Clock size={20}/> Temporal Planning</h2>
        <p className="text-[11px] opacity-80 leading-relaxed">Synchronize your future. Map milestones onto your neural timeline to optimize long-term preparation and ensure you're never blindsided by a deadline.</p>
      </div>

      <div className="bg-slate-900 p-6 rounded-[2rem] border border-white/5">
        <div className="grid grid-cols-7 gap-2">
          {Array.from({length: 31}, (_, i) => i+1).map(d => {
            const dateStr = `2026-01-${String(d).padStart(2, '0')}`;
            const hasEvent = events.some(e => e.date === dateStr);
            return (
              <button 
                key={d} 
                onClick={() => setSelectedDate(dateStr)}
                className={`aspect-square flex flex-col items-center justify-center rounded-xl relative transition-all ${selectedDate === dateStr ? 'bg-indigo-600 scale-105' : 'bg-white/5'}`}
              >
                <span className="text-[10px] font-black">{d}</span>
                {hasEvent && <div className="absolute bottom-1 w-1 h-1 bg-cyan-400 rounded-full" />}
              </button>
            )
          })}
        </div>
      </div>

      <div className="space-y-4">
        <button onClick={addEvent} className="w-full p-6 bg-white/5 border-2 border-dashed border-white/10 rounded-3xl text-slate-500 font-black uppercase text-[10px] tracking-widest hover:border-white/20">Sync Event on {selectedDate}</button>
        {dayEvents.map(e => (
          <div key={e.id} className="bg-slate-900 p-5 rounded-2xl border border-white/5 flex justify-between items-center group">
            <span className="font-bold text-sm">{e.text}</span>
            <button onClick={() => {
              const updated = events.filter(x => x.id !== e.id);
              setEvents(updated);
              localStorage.setItem('lsp_v8_events', JSON.stringify(updated));
            }} className="text-slate-700 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={16}/></button>
          </div>
        ))}
      </div>
    </div>
  );
};

