        <textarea value={prompt} onChange={e => setPrompt(e.target.value)} className="w-full bg-black/40 p-6 rounded-3xl text-white text-sm outline-none border border-white/5 h-40 resize-none" placeholder="Submit inquiry to strategic architect..." />
        <button onClick={ask} disabled={loading} className="w-full py-5 bg-indigo-600 rounded-2xl text-white font-black uppercase tracking-widest text-xs active:scale-95 transition-all shadow-xl shadow-indigo-500/20">{loading ? 'Synthesizing...' : 'Request Insight'}</button>
        {response && <div className="p-6 bg-white/5 rounded-3xl text-sm italic text-indigo-100 max-h-40 overflow-y-auto leading-relaxed border border-white/5">{response}</div>}
      </div>
    </div>
  );
};

