    setL(false);
  };
  return (
    <div className="space-y-6 animate-in max-w-md mx-auto">
      <div className="p-10 bg-indigo-600 rounded-[2.5rem] text-white flex flex-col items-center gap-4 text-center shadow-2xl relative overflow-hidden">
