  );
};

const QuickAddView: React.FC<any> = ({ onClose, addNotification, updateDayData, localData }) => {
  const [val, setVal] = useState("");
  const currentDayStr = new Date().toISOString().split('T')[0];

  const handleAdd = () => {
    if(!val) return;
    const day = localData[currentDayStr] || { goals: [], deviceTime: '0', studyLogs: [] };
    const newGoal = { id: Date.now().toString(), text: val, priority: 'standard', done: false, date: currentDayStr };
    updateDayData(currentDayStr, { goals: [...day.goals, newGoal] });
    addNotification(`Sync Complete: ${val}`);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/90 backdrop-blur-xl z-[100] flex items-end animate-in" onClick={onClose}>
      <div className="bg-slate-900 w-full rounded-t-[3rem] p-10 space-y-8 border-t border-white/10 shadow-2xl relative" onClick={e => e.stopPropagation()}>
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-12 h-1 bg-white/10 rounded-full mt-4" />
        <div className="flex justify-between items-center text-slate-500 uppercase text-[10px] font-black tracking-[0.2em]"><span>Protocol Initialization</span><button onClick={onClose}><X size={20}/></button></div>
        <input 
          autoFocus 
          value={val} 
          onChange={e => setVal(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && handleAdd()}
          placeholder="New core objective..." 
          className="w-full bg-transparent text-2xl font-black text-white outline-none placeholder:text-white/5" 
        />
        <button onClick={handleAdd} className="w-full py-5 bg-[var(--accent-primary)] rounded-2xl text-white font-black uppercase text-xs shadow-2xl active:scale-95 transition-all">Synchronize Parameter</button>
      </div>
    </div>
  );
};

