          <span className="font-bold text-sm text-white">{h}</span>
          <div className="flex gap-1.5">{[1,1,1,0,0,0,0].map((s,i) => <div key={i} className={`w-5 h-5 rounded-md ${s ? 'bg-emerald-500 shadow-glow-sm' : 'bg-white/5'}`} />)}</div>
        </div>
      ))}
