  'Navy Blue': { bg: '#0d1b2a', card: '#1b263b', accent: '#415a77', text: '#e0e1dd' },
  'Beige': { bg: '#d6ccc2', card: '#f5ebe0', accent: '#d5bdaf', text: '#463f3a' },
